-- Realism, eighth round: meetings that come back after the missions, so free play has a working week. The daily
-- standup (weekdays at 10:00, as Priya says on day 1), a 1:1 with Maya every other Thursday, sprint planning every
-- other Monday and the retro on the Friday of the other week (two-week sprints from Monday, October 26), and the
-- all-hands on the first Thursday of the month. Each routine takes its conversations in turn (only the hero's own).
-- The routines table is in db/schema.sql (this CREATE TABLE is the same).
CREATE TABLE IF NOT EXISTS routines (id varchar(32) PRIMARY KEY, hero varchar(32) NOT NULL DEFAULT 'all', title varchar(120) NOT NULL, title_ko varchar(120), days varchar(40) NOT NULL, every varchar(8) NOT NULL DEFAULT 'week', parity int NOT NULL DEFAULT 0, time varchar(5) NOT NULL, place varchar(32) NOT NULL, episodes varchar(1000) NOT NULL, people varchar(255), miss_points int NOT NULL DEFAULT 5, sort int NOT NULL DEFAULT 0);


