REPLACE INTO routines (id, hero, title, title_ko, days, every, parity, time, place, episodes, people, miss_points, sort) VALUES
  ('standup', 'all', 'Daily standup', '데일리 스탠드업', 'mon,tue,wed,thu,fri', 'week', 0, '10:00', 'office_meeting', 'rt_standup_jun_1,rt_standup_jun_2,rt_standup_jun_3,rt_standup_jun_4,rt_standup_jun_5,rt_standup_dk_1,rt_standup_dk_2,rt_standup_dk_3,rt_standup_dk_4,rt_standup_dk_5,rt_standup_pr_1,rt_standup_pr_2,rt_standup_pr_3,rt_standup_pr_4,rt_standup_pr_5', 'priya,derek,jun', 5, 1),
  ('one_on_one', 'all', '1:1 with Maya', '마야와 1:1', 'thu', '2weeks', 0, '11:00', 'office_manager', 'rt_1on1_jun_1,rt_1on1_jun_2,rt_1on1_jun_3,rt_1on1_dk_1,rt_1on1_dk_2,rt_1on1_dk_3,rt_1on1_pr_1,rt_1on1_pr_2,rt_1on1_pr_3', NULL, 10, 2),
  ('planning', 'all', 'Sprint planning', '스프린트 계획', 'mon', '2weeks', 1, '13:30', 'office_meeting', 'rt_planning_dev_1,rt_planning_dev_2,rt_planning_pr_1,rt_planning_pr_2', 'priya,derek,jun,maya', 10, 3),
  ('retro', 'all', 'Sprint retro', '스프린트 회고', 'fri', '2weeks', 0, '15:00', 'office_meeting', 'rt_retro_1,rt_retro_2,rt_retro_3', 'maya,priya,derek,jun', 5, 4),
  ('all_hands', 'all', 'All-hands meeting', '전사 회의', 'thu', 'month', 0, '16:00', 'office_meeting', 'rt_allhands_1,rt_allhands_2', 'maya,priya,derek,jun,tom,sam,linda', 5, 5);
REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('rt_standup_jun_1', 'Standup: a flaky test', '스탠드업: 들쭉날쭉한 테스트', 'office_meeting', 'priya', 16, NULL, '09:45', '10:30', NULL, 'The ten o''clock standup. Give your update, bring up the test that keeps failing at random, and accept help without holding up the meeting.', '10시 스탠드업입니다. 진행 상황을 말하고, 이따금 실패하는 테스트 얘기를 꺼내고, 회의를 붙잡지 않으면서 도움을 받으세요.', 0, 0, 2000, 'meeting,standup,routine', 'jun'),
  ('rt_standup_jun_2', 'Standup: waiting on a review', '스탠드업: 리뷰를 기다리며', 'office_meeting', 'priya', 16, NULL, '09:45', '10:30', NULL, 'The ten o''clock standup. Give your update, mention the pull request that has waited two days for review, and settle on a time without pointing fingers.', '10시 스탠드업입니다. 진행 상황을 말하고, 이틀째 리뷰를 기다리는 풀 리퀘스트 얘기를 꺼내고, 누구 탓도 하지 말고 시간을 정하세요.', 0, 0, 2001, 'meeting,standup,routine', 'jun'),
  ('rt_standup_jun_3', 'Standup: a store manager''s bug', '스탠드업: 매장 관리자가 찾은 버그', 'office_meeting', 'priya', 16, NULL, '09:45', '10:30', NULL, 'A pilot store manager reported a bug last night. Report it at the standup, explain the likely cause in plain words, and help Priya answer the store without promising too much.', '시범 매장 관리자가 어젯밤 버그를 알려 왔습니다. 스탠드업에서 보고하고, 짐작되는 원인을 쉬운 말로 설명하고, 프리야가 매장에 지나친 약속 없이 답하도록 도우세요.', 0, 0, 2002, 'meeting,standup,routine', 'jun'),
  ('rt_standup_jun_4', 'Standup: take it offline', '스탠드업: 따로 얘기해요', 'office_meeting', 'priya', 16, NULL, '09:45', '10:30', NULL, 'Give your update, and when Derek''s question turns into a long back-and-forth, move it out of the meeting and keep your own turn short.', '진행 상황을 말하고, 데릭의 질문이 길게 오가는 논쟁이 되면 회의 밖으로 미루고, 당신 차례는 짧게 끝내세요.', 0, 0, 2003, 'meeting,standup,routine', 'jun'),
  ('rt_standup_jun_5', 'Standup: before the demo', '스탠드업: 데모를 앞두고', 'office_meeting', 'priya', 16, NULL, '09:45', '10:30', NULL, 'Priya demos the dashboard to Summit Retail tomorrow. Tell her honestly what will be ready, help her choose where to run it, and offer to back her up.', '프리야가 내일 서밋 리테일에 대시보드를 시연합니다. 무엇이 준비될지 솔직하게 말하고, 어디서 시연할지 고르게 돕고, 뒤를 받쳐 주겠다고 하세요.', 0, 0, 2004, 'meeting,standup,routine', 'jun');
REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('rt_standup_dk_1', 'Standup: paged at night', '스탠드업: 한밤의 호출', 'office_meeting', 'priya', 16, NULL, '09:45', '10:30', NULL, 'You''re on call, and a page woke you last night. Explain what happened, reassure Priya about the stores, and plan a realistic day.', '당신은 온콜이고, 어젯밤 호출에 잠이 깼습니다. 무슨 일이 있었는지 설명하고, 매장 걱정을 덜어 주고, 현실적인 하루 계획을 말하세요.', 0, 0, 2010, 'meeting,standup,routine', 'derek'),
  ('rt_standup_dk_2', 'Standup: the slow page', '스탠드업: 느린 페이지', 'office_meeting', 'priya', 16, NULL, '09:45', '10:30', NULL, 'Pilot stores say a dashboard page is slow, and you found out why. Explain it in plain words, give a careful timeline, and bring Jun in.', '시범 매장들이 대시보드 페이지가 느리다고 하는데, 당신이 원인을 찾았습니다. 쉬운 말로 설명하고, 신중한 일정을 말하고, 준도 끌어들이세요.', 0, 0, 2011, 'meeting,standup,routine', 'derek'),
  ('rt_standup_dk_3', 'Standup: a library upgrade', '스탠드업: 라이브러리 업그레이드', 'office_meeting', 'priya', 16, NULL, '09:45', '10:30', NULL, 'The dashboard''s chart library needs an upgrade for a security fix. Give your update, explain why the upgrade matters, and keep the details for later.', '대시보드의 차트 라이브러리를 보안 수정 때문에 업그레이드해야 합니다. 진행 상황을 말하고, 업그레이드가 왜 중요한지 설명하고, 자세한 건 나중으로 미루세요.', 0, 0, 2012, 'meeting,standup,routine', 'derek'),
  ('rt_standup_dk_4', 'Standup: staging is down', '스탠드업: 스테이징이 멈췄다', 'office_meeting', 'priya', 16, NULL, '09:45', '10:30', NULL, 'Staging has been down since last night, and your work can''t be tested. Report the blocker fairly, say what you''ve done about it, and use the time well when Sam shows up.', '스테이징이 어젯밤부터 멈춰서 작업을 시험할 수 없습니다. 막힌 점을 공정하게 알리고, 무엇을 했는지 말하고, 샘이 나타나면 남는 시간을 잘 쓰세요.', 0, 0, 2013, 'meeting,standup,routine', 'derek'),
  ('rt_standup_dk_5', 'Standup: after an interview', '스탠드업: 면접 다음 날', 'office_meeting', 'priya', 16, NULL, '09:45', '10:30', NULL, 'You sat on a hiring panel yesterday. Give your update without sharing what you think of the candidate, and say yes to another panel with an honest heads-up.', '어제 채용 면접관으로 들어갔습니다. 지원자에 대한 생각은 말하지 말고 진행 상황을 전하고, 면접 하나를 더 맡되 솔직하게 미리 알려 주세요.', 0, 0, 2014, 'meeting,standup,routine', 'derek');
REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('rt_standup_pr_1', 'Standup: on the clock', '스탠드업: 15분 안에', 'office_meeting', 'derek', 16, NULL, '09:45', '10:30', NULL, 'You run the ten o''clock standup. Start on time, stop a debate that runs long, and take the last blocker as your own action item.', '10시 스탠드업은 당신이 진행합니다. 제시간에 시작하고, 길어지는 논쟁을 멈추고, 마지막으로 나온 막힌 점은 당신이 할 일로 맡으세요.', 0, 0, 2020, 'meeting,standup,routine', 'priya'),
  ('rt_standup_pr_2', 'Standup: a note from a store', '스탠드업: 매장에서 온 메일', 'office_meeting', 'derek', 16, NULL, '09:45', '10:30', NULL, 'A pilot store emailed you about a wrong list on the dashboard. Share it without blaming anyone, get the right people on it, and keep the store in the loop.', '시범 매장이 대시보드의 잘못된 목록에 대해 메일을 보냈습니다. 누구 탓도 하지 말고 알리고, 맞는 사람에게 맡기고, 매장에도 상황을 알리세요.', 0, 0, 2021, 'meeting,standup,routine', 'priya'),
  ('rt_standup_pr_3', 'Standup: stale tickets', '스탠드업: 묵은 티켓', 'office_meeting', 'derek', 16, NULL, '09:45', '10:30', NULL, 'Some tickets on the team board haven''t moved in weeks. Ask for updates without singling anyone out, connect two pieces of work that depend on each other, and keep the board honest.', '팀 보드의 티켓 몇 개가 몇 주째 그대로입니다. 누구를 콕 집지 말고 갱신을 부탁하고, 서로 기대는 두 작업을 이어 주고, 보드가 실제 상황을 보여 주게 하세요.', 0, 0, 2022, 'meeting,standup,routine', 'priya'),
  ('rt_standup_pr_4', 'Standup: the design isn''t ready', '스탠드업: 디자인이 아직', 'office_meeting', 'derek', 16, NULL, '09:45', '10:30', NULL, 'Jun can''t start his page because the design isn''t ready. Find him something useful, keep a bigger idea out of the standup, and decide whether Summit needs to hear about it.', '디자인이 준비되지 않아 준이 페이지를 시작하지 못합니다. 그에게 쓸모 있는 일을 찾아 주고, 큰 아이디어는 스탠드업 밖으로 미루고, 서밋에 알려야 할지 정하세요.', 0, 0, 2023, 'meeting,standup,routine', 'priya'),
  ('rt_standup_pr_5', 'Standup: a request from Greg', '스탠드업: 그렉의 요청', 'office_meeting', 'derek', 16, NULL, '09:45', '10:30', NULL, 'Greg from Summit Retail asked for something new. Share it without overpromising, give Jun''s excitement its own meeting, and keep the sprint focused.', '서밋 리테일의 그렉이 새로운 걸 요청했습니다. 지나친 약속 없이 알리고, 준의 열의는 따로 회의를 잡아 받아 주고, 스프린트가 흐트러지지 않게 하세요.', 0, 0, 2024, 'meeting,standup,routine', 'priya');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_jun_1', 1, NULL, 'Ten o''clock standup in the meeting room: yesterday, today, blockers, fifteen minutes. Yesterday you finished the sales-by-hour chart for the store dashboard and opened a pull request. Today you plan to start the CSV export.', '회의실에서 10시 스탠드업입니다. 어제, 오늘, 막힌 점을 15분 안에 말합니다. 어제 당신은 매장 대시보드의 시간대별 매출 차트를 끝내고 풀 리퀘스트를 올렸습니다. 오늘은 CSV 내보내기를 시작할 계획입니다.', 'Morning, everyone. Jun, you''re up. Yesterday, today, blockers.', '좋은 아침이에요, 여러분. 준, 먼저 해요. 어제, 오늘, 막힌 점이요.', 'Sum up what you got done and what comes next, in two sentences.', '한 일과 다음 할 일을 두 문장으로 정리하세요.', '[]', 'Yesterday I finished the sales-by-hour chart and opened a PR. Today I''m starting the CSV export.', '어제 시간대별 매출 차트를 끝내고 PR을 올렸어요. 오늘은 CSV 내보내기를 시작해요.', '["Yesterday I started the CSV export. Today I''ll finish the sales-by-hour chart and open a PR.","Yesterday I finished the sales-by-hour chart and merged it to main. Today I''m starting the export.","Long day yesterday. My dentist ran late, and then the chart fought me all afternoon."]', '["어제 CSV 내보내기를 시작했어요. 오늘은 시간대별 매출 차트를 끝내고 PR을 올릴게요.","어제 시간대별 매출 차트를 끝내서 main에 머지했어요. 오늘은 내보내기를 시작해요.","어제 하루가 길었어요. 치과가 늦게 끝났고, 오후 내내 차트랑 씨름했어요."]', '["Wait, I thought the chart was the one you finished?","Merged already? Did someone review it?","Sorry to hear that. But what''s the plan for today?"]', '["잠깐요, 끝낸 건 차트 아니었어요?","벌써 머지했어요? 리뷰는 누가 했어요?","고생했네요. 그런데 오늘 계획은요?"]', NULL, 'Great. Any blockers?', '좋아요. 막힌 건 있어요?'),
  ('rt_standup_jun_1', 2, NULL, 'One test in the build fails about one run in five, then passes when you run it again. It keeps your pull request''s checks red. Nobody knows why yet.', '빌드의 테스트 하나가 다섯 번에 한 번꼴로 실패하고, 다시 돌리면 통과합니다. 그 때문에 당신의 풀 리퀘스트 검사가 계속 빨간불입니다. 아직 아무도 이유를 모릅니다.', 'Anything slowing you down?', '발목 잡는 거 있어요?', 'Mention the build problem and ask for a hand, without blaming anyone.', '빌드 문제를 말하고, 누구 탓도 하지 말고 도움을 청하세요.', '[]', 'One test fails randomly, maybe one run in five. Could someone look at it with me?', '테스트 하나가 다섯 번에 한 번쯤 아무 때나 실패해요. 누가 같이 봐 줄 수 있을까요?', '["No blockers. One test fails sometimes, but I just re-run the build until it passes.","Derek''s old test is broken again. It fails every single time, so he needs to fix it.","One test fails randomly. I''ll rewrite the whole test suite today so it never happens again."]', '["막힌 건 없어요. 테스트 하나가 가끔 실패하는데, 통과할 때까지 빌드를 다시 돌리면 돼요.","데릭이 예전에 짠 테스트가 또 고장 났어요. 매번 실패하니까 데릭이 고쳐야 해요.","테스트 하나가 아무 때나 실패해요. 다시는 안 그러게 오늘 테스트 전체를 새로 짤게요."]', '["Hmm. Re-running isn''t really a fix, though.","Every time? Let''s not point fingers before we know.","The whole suite? Let''s not go that far today."]', '["음. 다시 돌리는 건 해결이 아니잖아요.","매번요? 원인을 알기 전에 누구 탓은 하지 말아요.","테스트 전체를요? 오늘 그렇게까지는 말아요."]', NULL, 'Good flag. Derek, could you take a look with Jun?', '잘 말해 줬어요. 데릭, 준이랑 같이 봐 줄래요?'),
  ('rt_standup_jun_1', 3, 'derek', 'Derek nods. You have nothing on your calendar at eleven.', '데릭이 고개를 끄덕입니다. 당신은 11시에 아무 일정이 없습니다.', 'Sure. I bet it''s the time zone one. I''ve got time at eleven.', '그래요. 아마 시간대 테스트일 거예요. 11시에 시간 돼요.', 'Accept, and keep it short so the standup can move on.', '받아들이고, 스탠드업이 넘어가도록 짧게 끝내세요.', '[]', 'Eleven works. Thanks, Derek. That''s all from me.', '11시 좋아요. 고마워요, 데릭. 저는 여기까지예요.', '["Eleven? Can we just look at it right now? It''ll only take a minute.","Thanks, but eleven is bad. I''m busy all morning, so maybe Friday?","Eleven works. Also, quick question about the export: CSV or Excel?"]', '["11시요? 그냥 지금 보면 안 돼요? 1분이면 될 텐데요.","고마워요, 근데 11시는 안 돼요. 오전 내내 바빠서, 금요일은 어때요?","11시 좋아요. 그리고 내보내기 말인데요, CSV예요, 엑셀이에요?"]', '["Let''s not hold up the standup. Eleven.","Friday? Your PR is stuck until then.","Let''s take that one after standup, too."]', '["스탠드업 붙잡지 말아요. 11시에 봐요.","금요일요? 그때까지 PR이 묶여 있잖아요.","그것도 스탠드업 끝나고 얘기해요."]', NULL, 'Cool. I''ll come by your desk.', '좋아요. 자리로 갈게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_jun_2', 1, NULL, 'Ten o''clock standup in the meeting room. Yesterday you fixed a rounding bug: the weekly totals on the dashboard were off by a cent. Today you plan to start the low-stock widget.', '회의실에서 10시 스탠드업입니다. 어제 당신은 반올림 버그를 고쳤습니다. 대시보드의 주간 합계가 1센트씩 틀렸거든요. 오늘은 재고 부족 위젯을 시작할 계획입니다.', 'Jun, how''s it going?', '준, 어떻게 돼 가요?', 'Say what you finished and what''s next.', '끝낸 일과 다음 할 일을 말하세요.', '[]', 'Yesterday I fixed the rounding bug in the weekly totals. Today I''m starting the low-stock widget.', '어제 주간 합계의 반올림 버그를 고쳤어요. 오늘은 재고 부족 위젯을 시작해요.', '["Yesterday I started the low-stock widget. Today I''ll look into the rounding bug in the totals.","Yesterday I fixed the weekly totals. The store manager was typing the numbers in wrong, as usual.","Yesterday I fixed the rounding bug in the weekly totals. Today, honestly, I''m not sure yet."]', '["어제 재고 부족 위젯을 시작했어요. 오늘은 합계의 반올림 버그를 볼게요.","어제 주간 합계를 고쳤어요. 늘 그렇듯 매장 관리자가 숫자를 잘못 넣었더라고요.","어제 주간 합계의 반올림 버그를 고쳤어요. 오늘은, 솔직히, 아직 모르겠어요."]', '["Wait, wasn''t the rounding bug the one you fixed?","Careful. That''s one of our pilot stores, and it was our bug.","Okay. Maybe have a plan by the end of the day?"]', '["잠깐요, 반올림 버그는 고친 거 아니었어요?","조심해요. 우리 시범 매장이고, 우리 버그였잖아요.","그래요. 오늘 안에는 계획을 세워 봐요."]', NULL, 'Nice work. Blockers?', '잘했어요. 막힌 건요?'),
  ('rt_standup_jun_2', 2, NULL, 'Your pull request for the store filter has been waiting two days for a review. Derek usually reviews your code, and he''s been busy on call this week.', '매장 필터 풀 리퀘스트가 이틀째 리뷰를 기다리고 있습니다. 보통 데릭이 당신 코드를 리뷰하는데, 이번 주에는 온콜로 바빴습니다.', 'Anything in your way?', '걸리는 거 있어요?', 'Bring up the stalled review politely, without pointing fingers.', '멈춰 있는 리뷰 얘기를, 누구 탓도 하지 말고 정중하게 꺼내세요.', '[]', 'My store filter PR has been waiting two days. Could someone take a look today?', '매장 필터 PR이 이틀째 기다리고 있어요. 오늘 누가 봐 줄 수 있을까요?', '["Derek still hasn''t reviewed my PR. It''s been two days, so I''m just stuck.","My store filter PR has been open for two weeks. Could someone look at it?","No blockers. If nobody gets to my PR today, I''ll just merge it myself."]', '["데릭이 아직 제 PR을 리뷰 안 했어요. 이틀째라서 그냥 꼼짝 못 하고 있어요.","매장 필터 PR이 2주째 열려 있어요. 누가 봐 줄 수 있을까요?","막힌 건 없어요. 오늘 아무도 PR을 안 보면 제가 그냥 머지할게요."]', '["Derek''s been on call. Let''s keep it friendly.","Two weeks? I thought it was newer than that.","Please don''t. Everything gets a review here."]', '["데릭은 온콜이었잖아요. 좋게 말해요.","2주요? 그보다 최근인 줄 알았는데요.","그러지 말아요. 여기선 전부 리뷰를 거쳐요."]', NULL, 'Fair. Derek, can you fit it in?', '그렇네요. 데릭, 시간 낼 수 있어요?'),
  ('rt_standup_jun_2', 3, 'derek', 'The store filter is needed for a pilot-store demo tomorrow morning.', '매장 필터는 내일 아침 시범 매장 데모에 필요합니다.', 'Sorry, Jun. On call ate my week. I can do it after lunch, or first thing tomorrow.', '미안해요, 준. 온콜 때문에 한 주가 날아갔어요. 점심 먹고 볼 수도 있고, 내일 아침 일찍 봐도 돼요.', 'Pick the option that gets it reviewed in time, and thank him.', '제때 리뷰받을 수 있는 쪽을 고르고, 고맙다고 하세요.', '[]', 'After lunch is perfect. Thanks, Derek.', '점심 후면 딱 좋아요. 고마워요, 데릭.', '["Tomorrow morning works. I''ll remind you first thing.","After lunch? Honestly, it needed to be done yesterday.","Could you just do it now, while we''re all here?"]', '["내일 아침 좋아요. 아침에 바로 알려 드릴게요.","점심 후요? 솔직히 어제 됐어야 했는데요.","다 모였을 때 지금 그냥 봐 주면 안 돼요?"]', '["Tomorrow? Isn''t that when the demo is?","Okay... I did say I was sorry.","Not during standup, Jun."]', '["내일요? 그때가 데모 아니에요?","그래요... 미안하다고 했잖아요.","스탠드업 중엔 안 돼요, 준."]', NULL, 'Deal. I''ll ping you when I start.', '좋아요. 시작할 때 메시지 보낼게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_jun_3', 1, NULL, 'Ten o''clock standup. Last night a manager at one of the pilot stores emailed you: for about an hour after midnight, the dashboard shows the day''s sales as zero. You haven''t fixed it yet.', '10시 스탠드업입니다. 어젯밤 시범 매장 한 곳의 관리자가 메일을 보냈습니다. 자정이 지나고 한 시간쯤 대시보드에 그날 매출이 0으로 나온다고요. 아직 고치지 못했습니다.', 'Jun, go ahead.', '준, 시작해요.', 'Tell the team about the store''s report and that you''re handling it.', '매장에서 온 신고를 팀에 알리고, 당신이 맡고 있다고 말하세요.', '[]', 'A pilot store manager says sales show zero for an hour after midnight. I''m looking into it today.', '시범 매장 관리자가 자정 후 한 시간 동안 매출이 0으로 나온대요. 오늘 살펴볼게요.', '["A pilot store manager says sales show zero after midnight. I already fixed it last night.","A store manager emailed me, but I think he''s confused. The numbers look fine to me.","A pilot store manager says sales show zero all day long. I''m looking into it today."]', '["시범 매장 관리자가 자정 후 매출이 0으로 나온대요. 어젯밤에 벌써 고쳤어요.","매장 관리자가 메일을 보냈는데, 착각하신 것 같아요. 제가 보기엔 숫자가 멀쩡해요.","시범 매장 관리자가 하루 종일 매출이 0으로 나온대요. 오늘 살펴볼게요."]', '["Already? Did it go through review?","Let''s not assume that. They''re our pilot users.","All day? That sounds a lot worse."]', '["벌써요? 리뷰는 거쳤어요?","그렇게 단정하지 말아요. 우리 시범 사용자들이에요.","하루 종일요? 훨씬 심각하게 들리는데요."]', NULL, 'Good. Any idea what''s causing it?', '좋아요. 원인은 짐작 가요?'),
  ('rt_standup_jun_3', 2, NULL, 'You suspect the server counts days in a different time zone from the stores. Priya is not an engineer.', '서버가 매장과 다른 시간대로 날짜를 세는 것 같습니다. 프리야는 엔지니어가 아닙니다.', 'Do you know why it happens?', '왜 그런지 알아요?', 'Explain your guess in words a non-engineer can follow.', '엔지니어가 아닌 사람도 알아듣게 짐작을 설명하세요.', '[]', 'I think our server and the stores use different time zones, so the day ends at the wrong hour.', '서버와 매장이 다른 시간대를 쓰는 것 같아요. 그래서 하루가 엉뚱한 시각에 끝나요.', '["It''s probably a UTC offset issue in the aggregation job''s date truncation. Pretty standard.","I think the store''s computers have the wrong time set. They should fix their clocks.","No idea yet, honestly. It could be anything, so it might take a few weeks."]', '["아마 집계 작업의 날짜 자르기에서 UTC 오프셋 문제일 거예요. 흔한 거예요.","매장 컴퓨터 시간이 잘못 맞춰져 있는 것 같아요. 그쪽에서 시계를 고쳐야 해요.","솔직히 아직 몰라요. 뭐든 될 수 있어서 몇 주 걸릴 수도 있어요."]', '["Um... in English, please?","Their clocks? I''d rather not tell Summit that.","A few weeks? Let''s not say that to the store."]', '["음... 쉬운 말로 해 줄래요?","매장 시계요? 서밋에 그렇게 말하긴 싫은데요.","몇 주요? 매장에 그렇게 말하진 말아요."]', NULL, 'Got it. That makes sense even to me.', '알겠어요. 저도 이해가 돼요.'),
  ('rt_standup_jun_3', 3, NULL, 'You expect to have a fix ready for Derek''s review by the end of the day. It can go live once he approves.', '오늘 안에 수정을 마쳐 데릭에게 리뷰를 맡길 수 있을 것 같습니다. 그가 승인하면 반영할 수 있습니다.', 'Should I tell the store manager anything?', '매장 관리자한테 뭐라고 할까요?', 'Suggest what she can tell the store, without promising too much.', '지나친 약속 없이, 매장에 뭐라고 하면 좋을지 제안하세요.', '[]', 'Maybe say we found the likely cause, and a fix is a day or two out.', '원인을 거의 찾았고, 하루 이틀 안에 수정이 나갈 거라고 하시면 돼요.', '["Tell him it''s fixed. I''m pretty sure I''ll have it done tonight anyway.","Tell him the problem is on their side, so it''s not really on us.","Let''s not tell him anything until it''s fixed. He''ll notice on his own."]', '["고쳤다고 하세요. 어차피 오늘 밤엔 끝낼 수 있을 거예요.","문제가 그쪽에 있다고 하세요. 그러니 우리 책임은 아니라고요.","고칠 때까지 아무 말 하지 말아요. 알아서 알게 될 거예요."]', '["I''d rather not promise that before Derek reviews it.","But you just said it was our server.","Hmm. I''d rather keep him in the loop."]', '["데릭이 리뷰하기 전에 그렇게 약속하긴 싫어요.","방금 우리 서버 문제라고 했잖아요.","음. 계속 상황을 알려 드리고 싶어요."]', NULL, 'Perfect. I''ll email him right after standup.', '좋아요. 스탠드업 끝나면 바로 메일 보낼게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_jun_4', 1, NULL, 'Ten o''clock standup. Yesterday you finished the inventory chart and opened a pull request for Derek to review. Today you''ll start the store picker. Nothing is blocking you.', '10시 스탠드업입니다. 어제 당신은 재고 차트를 끝내고 데릭에게 리뷰를 맡길 풀 리퀘스트를 올렸습니다. 오늘은 매장 선택기를 시작합니다. 막힌 건 없습니다.', 'Morning. Jun, kick us off.', '좋은 아침이에요. 준, 먼저 시작해요.', 'Give your update in a few words.', '진행 상황을 몇 마디로 말하세요.', '[]', 'Yesterday I finished the inventory chart and opened a PR. Today, the store picker. No blockers.', '어제 재고 차트를 끝내고 PR을 올렸어요. 오늘은 매장 선택기요. 막힌 건 없어요.', '["Yesterday I finished the inventory chart and shipped it to the pilot stores. Today, the store picker.","Yesterday I started the store picker. Today I''ll finish the inventory chart and open a PR.","Yesterday was the inventory chart. It got really tricky, so let me walk you through how it works."]', '["어제 재고 차트를 끝내서 시범 매장에 내보냈어요. 오늘은 매장 선택기요.","어제 매장 선택기를 시작했어요. 오늘은 재고 차트를 끝내고 PR을 올릴게요.","어제는 재고 차트였어요. 꽤 까다로워서, 어떻게 돌아가는지 쭉 설명할게요."]', '["Shipped? Did Derek review it first?","Wait, I thought the chart was done?","Maybe just the headline, Jun?"]', '["내보냈다고요? 데릭이 먼저 리뷰했어요?","잠깐요, 차트는 끝난 줄 알았는데요?","요점만 말해 줄래요, 준?"]', NULL, 'Great. Derek, you had a question for Jun?', '좋아요. 데릭, 준한테 물어볼 게 있었죠?'),
  ('rt_standup_jun_4', 2, 'derek', 'Your chart keeps its data for five minutes before asking the database again. Derek thinks that''s too long. You two have already gone back and forth three times, and Priya and Maya are waiting.', '당신의 차트는 데이터를 5분 동안 들고 있다가 데이터베이스에 다시 묻습니다. 데릭은 너무 길다고 봅니다. 둘이 벌써 세 번이나 주거니 받거니 했고, 프리야와 마야가 기다리고 있습니다.', 'But five minutes is a long time for stock levels. Why not one minute? Or no cache at all?', '근데 재고 수량에 5분은 길어요. 왜 1분은 안 돼요? 아예 캐시를 안 쓰든가요?', 'Take his point seriously, but move the rest of the discussion out of the meeting.', '그의 지적은 진지하게 받되, 나머지 논의는 회의 밖으로 옮기세요.', '[]', 'Fair question. Can we dig into it right after standup? I''ll come by your desk.', '좋은 질문이에요. 스탠드업 끝나고 바로 파 볼까요? 자리로 갈게요.', '["Because one minute would hit the database way too often. Let me show you the numbers.","Five minutes is fine, trust me. I already decided, so let''s not change it now.","Fair question. Let''s just go with no cache at all, then. Problem solved."]', '["1분이면 데이터베이스를 너무 자주 두드려요. 숫자를 보여 드릴게요.","5분이면 괜찮아요, 믿어 주세요. 이미 정했으니 이제 와서 바꾸지 말아요.","좋은 질문이에요. 그럼 그냥 캐시를 아예 빼요. 해결됐네요."]', '["Uh, maybe not right now? People are waiting.","Whoa. It''s a review, Jun. I''m allowed to ask.","No cache? That would hammer the database."]', '["어, 지금은 말고요? 다들 기다려요.","워. 리뷰잖아요, 준. 물어볼 수는 있죠.","캐시를 빼요? 그럼 데이터베이스가 버티질 못해요."]', NULL, 'Deal. Sorry, everyone, we got carried away.', '좋아요. 다들 미안해요, 너무 길어졌네요.'),
  ('rt_standup_jun_4', 3, NULL, 'You also want to ask Maya how the mobile app, phase two, will be planned. It starts in January, so it isn''t urgent, and it''s a long topic.', '마야에게 2단계인 모바일 앱을 어떻게 계획할지도 묻고 싶습니다. 1월에 시작하니 급하지 않고, 이야기가 깁니다.', 'Thanks, both. Jun, anything else?', '둘 다 고마워요. 준, 더 있어요?', 'Close your turn, and mention the other topic without spending time on it now.', '당신 차례를 마무리하고, 다른 주제는 지금 시간을 쓰지 않는 식으로 꺼내세요.', '[]', 'One thing: Maya, can I grab you later about the mobile app? That''s it from me.', '하나만요. 마야, 나중에 모바일 앱 얘기 좀 할 수 있을까요? 저는 여기까지예요.', '["Yes, a big one. Maya, how are we planning the mobile app? Like, which screens come first?","Nothing else. Oh, and Derek, I still think five minutes is right, by the way.","One thing: Maya, can I grab you later about the mobile app? It starts next week, right?"]', '["네, 큰 거 하나요. 마야, 모바일 앱은 어떻게 계획해요? 어떤 화면부터 해요?","없어요. 아, 그리고 데릭, 그래도 저는 5분이 맞다고 생각해요.","하나만요. 마야, 나중에 모바일 앱 얘기 좀 할 수 있을까요? 다음 주에 시작하죠?"]', '["Let''s keep that one for later, Jun.","We just moved that out of standup, remember?","Next week? It''s planned for January."]', '["그건 나중으로 미뤄요, 준.","그건 방금 스탠드업 밖으로 미뤘잖아요.","다음 주요? 1월로 잡혀 있어요."]', NULL, 'Perfect. Thanks, Jun. Who''s next?', '좋아요. 고마워요, 준. 다음은 누구죠?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_jun_5', 1, NULL, 'Ten o''clock standup. You''re building the store comparison page. The page itself works, but its export button doesn''t yet. You can finish the export by the end of tomorrow, after the demo.', '10시 스탠드업입니다. 당신은 매장 비교 페이지를 만들고 있습니다. 페이지는 돌아가지만 내보내기 버튼은 아직입니다. 내보내기는 데모가 끝난 뒤, 내일 퇴근 전까지 끝낼 수 있습니다.', 'Reminder: I''m demoing to Greg tomorrow afternoon. Jun, where''s the comparison page?', '다시 알려요. 내일 오후에 그렉한테 시연해요. 준, 비교 페이지는 어디까지 됐어요?', 'Tell her honestly what will and won''t be ready for the demo.', '데모 때 무엇이 준비되고 무엇이 안 될지 솔직하게 말하세요.', '[]', 'The page works, but the export button won''t be ready until after the demo.', '페이지는 돌아가는데, 내보내기 버튼은 데모가 끝난 뒤에야 돼요.', '["It''ll all be ready, the export too. I''ll stay late tonight if I have to.","The comparison page works, and the export button is already done and tested too.","It''s not really ready. Maybe you should push the demo to next week?"]', '["내보내기까지 다 될 거예요. 필요하면 오늘 밤늦게까지 할게요.","비교 페이지는 돌아가고, 내보내기 버튼도 벌써 다 만들어서 시험까지 했어요.","아직 준비가 덜 됐어요. 데모를 다음 주로 미루시는 게 어때요?"]', '["Let''s not plan on late nights. What''s realistic?","Really? Last time I checked, it didn''t do anything.","Push it? Greg''s been waiting for this."]', '["밤샘은 계획에 넣지 말아요. 현실적으로는요?","정말요? 지난번에 봤을 땐 아무 반응이 없던데요.","미루자고요? 그렉이 기다리고 있는데요."]', NULL, 'That''s fine. I just won''t click it.', '괜찮아요. 그 버튼만 안 누르면 되죠.'),
  ('rt_standup_jun_5', 2, NULL, 'The comparison page is only on staging, which has been stable all week. Production, where the pilot stores work, doesn''t have it yet.', '비교 페이지는 스테이징에만 있고, 스테이징은 이번 주 내내 안정적이었습니다. 시범 매장들이 쓰는 운영 서버에는 아직 없습니다.', 'Can I demo on staging, or is that risky?', '스테이징으로 시연해도 될까요, 위험할까요?', 'Recommend where to run the demo, and give the reason.', '어디서 시연할지 권하고, 이유를 말하세요.', '[]', 'Staging is safer. It has the comparison page, and it''s been stable all week.', '스테이징이 더 안전해요. 비교 페이지도 있고, 이번 주 내내 안정적이었어요.', '["Use production instead. The comparison page is already live there, too.","Staging is safer. It''s been going down a lot this week, though.","Either one is fine, honestly. Just pick whichever one you like better."]', '["운영 서버를 쓰세요. 비교 페이지가 벌써 거기 올라가 있어요.","스테이징이 더 안전해요. 이번 주에 자주 멈추긴 했지만요.","솔직히 아무 데나 괜찮아요. 마음에 드는 쪽으로 고르세요."]', '["Live? I thought it was only on staging.","Wait, then how is it safer?","I was hoping you''d tell me which."]', '["올라가 있다고요? 스테이징에만 있는 줄 알았는데요.","잠깐요, 그럼 왜 더 안전해요?","어느 쪽인지 말해 주길 바랐는데요."]', NULL, 'Staging it is. Thanks.', '스테이징으로 할게요. 고마워요.'),
  ('rt_standup_jun_5', 3, NULL, 'Your calendar is open tomorrow afternoon. It''s Priya''s demo and her client.', '내일 오후 당신의 일정은 비어 있습니다. 프리야의 데모이고 그녀의 고객입니다.', 'Can you join the demo, in case Greg asks something technical?', '그렉이 기술적인 걸 물을 수도 있으니, 데모에 같이 들어와 줄래요?', 'Agree, and offer one thing that would help her get ready.', '그러겠다고 하고, 그녀가 준비하는 데 도움이 될 것을 하나 제안하세요.', '[]', 'Sure, I''ll be there. Want a quick run-through this afternoon?', '그럼요, 들어갈게요. 오늘 오후에 한번 맞춰 볼래요?', '["Sure. But I''ll do most of the talking, if that''s okay with you.","Tomorrow afternoon? Sorry, I''m booked solid all day tomorrow.","Sure. Let''s walk through the whole demo now, while everyone''s here."]', '["그럼요. 괜찮으시면 말은 주로 제가 할게요.","내일 오후요? 죄송해요, 내일은 하루 종일 꽉 찼어요.","그럼요. 다들 있을 때 지금 데모 전체를 한번 훑어봐요."]', '["It''s my demo, Jun. Just back me up.","Oh? I thought your calendar was open.","Not now. Let''s keep standup short."]', '["제 데모예요, 준. 뒤만 받쳐 줘요.","어? 일정 비어 있는 줄 알았는데요.","지금은 말고요. 스탠드업은 짧게 해요."]', NULL, 'Yes, please. Let''s say two o''clock.', '좋아요. 2시로 해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_dk_1', 1, NULL, 'Ten o''clock standup. You''re on call this week. At two in the morning a page woke you: the nightly data import from Summit Retail had failed. You restarted it, and it finished by three. You don''t know why it failed.', '10시 스탠드업입니다. 당신은 이번 주 온콜입니다. 새벽 2시에 호출이 와서 깼습니다. 서밋 리테일의 야간 데이터 가져오기가 실패했던 거죠. 다시 돌렸고 3시에 끝났습니다. 왜 실패했는지는 모릅니다.', 'Derek, you look tired. Rough night?', '데릭, 피곤해 보여요. 힘든 밤이었어요?', 'Explain briefly what happened overnight.', '밤사이 무슨 일이 있었는지 짧게 설명하세요.', '[]', 'I got paged at two. The nightly import failed, so I restarted it. It was done by three.', '2시에 호출을 받았어요. 야간 가져오기가 실패해서 다시 돌렸어요. 3시에 끝났어요.', '["I got paged at two. The nightly import failed, and it''s still down right now.","Yeah. My neighbor''s dog barked half the night, and then the pager went off too.","I got paged at two. Jun''s new code broke the nightly import, I''m pretty sure."]', '["2시에 호출을 받았어요. 야간 가져오기가 실패했고, 지금도 멈춰 있어요.","네. 옆집 개가 밤새 짖더니, 호출기까지 울리더라고요.","2시에 호출을 받았어요. 준의 새 코드가 야간 가져오기를 망가뜨린 것 같아요."]', '["Still down? Should we tell the stores?","Oof. But what was the page about?","Do we know that yet?"]', '["아직 멈춰 있다고요? 매장에 알려야 해요?","저런. 근데 호출은 무슨 일이었어요?","그건 확실히 알아요?"]', NULL, 'Thanks for handling it. Did the stores see anything wrong?', '처리해 줘서 고마워요. 매장에서 이상한 걸 봤을까요?'),
  ('rt_standup_dk_1', 2, NULL, 'The stores open at nine, so the data was in place long before anyone looked. The cause is still a mystery.', '매장은 9시에 문을 여니, 누가 보기 훨씬 전에 데이터가 들어와 있었습니다. 원인은 아직 모릅니다.', 'Did the stores see anything wrong?', '매장에서 이상한 걸 봤을까요?', 'Reassure her about the stores, and be honest about what you still don''t know.', '매장은 괜찮다고 안심시키고, 아직 모르는 건 솔직하게 말하세요.', '[]', 'No, it was done long before the stores opened. I still don''t know why it failed.', '아니요, 매장 문 열기 한참 전에 끝났어요. 왜 실패했는지는 아직 몰라요.', '["No, they were fine. It was a one-time glitch, so it won''t happen again.","Yes, the stores opened to empty dashboards this morning. It wasn''t great.","Not sure, honestly. I didn''t check. I went straight back to sleep."]', '["아니요, 괜찮았어요. 한 번 있는 오류라 다시는 안 일어날 거예요.","네, 오늘 아침 매장들이 빈 대시보드를 봤어요. 좋진 않았죠.","솔직히 잘 모르겠어요. 확인 안 했어요. 바로 다시 잤거든요."]', '["How can you be sure, if we don''t know the cause?","Really? Nobody''s called me about it.","Could you check after standup, then?"]', '["원인도 모르는데 어떻게 확신해요?","정말요? 아무도 저한테 연락 안 했는데요.","그럼 스탠드업 끝나고 확인해 줄래요?"]', NULL, 'Good. Will you dig into it today?', '다행이에요. 오늘 원인을 파 볼 거예요?'),
  ('rt_standup_dk_1', 3, NULL, 'Today you also have Jun''s pull request to review and a hiring panel interview at one for the backend developer job. Digging into the import would take a couple of hours.', '오늘은 준의 풀 리퀘스트 리뷰도 있고, 1시에 백엔드 개발자 채용 면접관도 맡았습니다. 가져오기 원인을 찾는 데는 두어 시간이 걸립니다.', 'Will you dig into it today?', '오늘 원인을 파 볼 거예요?', 'Lay out your day realistically, keeping the investigation in it.', '원인 조사를 빼지 말고, 오늘 하루를 현실적으로 정리하세요.', '[]', 'This morning, yes. Then Jun''s review, and I''m on the interview panel at one.', '오전에 할게요. 그다음 준의 리뷰, 1시엔 면접에 들어가요.', '["I''m interviewing at one today, so the import will have to wait until next week.","Yes, all day. I''ll skip the interview at one. It''s not that important.","This morning, yes. Then the interview at three, and Jun''s review after."]', '["오늘 1시에 면접이 있어서, 가져오기는 다음 주까지 기다려야 해요.","네, 하루 종일요. 1시 면접은 빠질게요. 그렇게 중요하진 않아요.","오전에 할게요. 그다음 3시에 면접, 그 뒤에 준의 리뷰요."]', '["Next week? It might fail again tonight.","Please don''t. Linda''s counting on you.","Three? I have it at one on the calendar."]', '["다음 주요? 오늘 밤에 또 실패할 수도 있잖아요.","그러지 말아요. 린다가 당신만 믿고 있어요.","3시요? 달력엔 1시로 돼 있는데요."]', NULL, 'Sounds like a plan. Shout if you need cover.', '좋은 계획이에요. 대신 맡아 줄 사람 필요하면 말해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_dk_2', 1, NULL, 'Ten o''clock standup. Pilot store managers say the weekly sales page takes about ten seconds to load. You found that one query reads the entire sales table every time. An index should fix it.', '10시 스탠드업입니다. 시범 매장 관리자들이 주간 매출 페이지가 뜨는 데 10초쯤 걸린다고 합니다. 당신은 쿼리 하나가 매번 매출 표 전체를 읽는다는 걸 찾았습니다. 인덱스를 걸면 고쳐질 겁니다.', 'Derek, any news on the slow page?', '데릭, 느린 페이지는 뭐 알아냈어요?', 'Say what you found in words a non-engineer can follow.', '엔지니어가 아닌 사람도 알아듣게 찾은 걸 말하세요.', '[]', 'Yes. One query reads the whole sales table every time. An index should fix it.', '네. 쿼리 하나가 매번 매출 표 전체를 읽어요. 인덱스를 걸면 고쳐질 거예요.', '["Yes. The stores'' internet is just slow. There''s not much we can do about it.","Yes. The page loads in about a second now, so we''re all good there.","Yes. It''s a sequential scan on the sales fact table, from a missing composite index."]', '["네. 매장 인터넷이 느린 거예요. 우리가 할 수 있는 게 별로 없어요.","네. 이제 1초 만에 떠요. 그쪽은 다 해결됐어요.","네. 복합 인덱스가 없어서 매출 팩트 테이블을 순차 스캔해요."]', '["Their internet? I thought you''d found something in our code.","Really? A store manager said it was slow this morning.","Could you say that in plain English for me?"]', '["매장 인터넷요? 우리 코드에서 뭘 찾은 줄 알았는데요.","정말요? 매장 관리자가 오늘 아침에도 느리다던데요.","쉬운 말로 다시 해 줄래요?"]', NULL, 'Great find. Can we ship it today?', '잘 찾았어요. 오늘 내보낼 수 있어요?'),
  ('rt_standup_dk_2', 2, NULL, 'You want to test the index on staging today with a copy of real data. If it goes well, it can go to production tomorrow morning, before the stores open.', '오늘 실제 데이터 사본으로 스테이징에서 인덱스를 시험하고 싶습니다. 잘되면 내일 아침, 매장 문 열기 전에 운영 서버에 반영할 수 있습니다.', 'Can we ship it today?', '오늘 내보낼 수 있어요?', 'Give a realistic timeline, without rushing it.', '서두르지 말고 현실적인 일정을 말하세요.', '[]', 'Let''s test it on staging today. If it looks good, it ships tomorrow morning.', '오늘 스테이징에서 시험해요. 괜찮으면 내일 아침에 내보내요.', '["Sure. I''ll push it straight to production right after standup, then.","I''d rather test it on staging first. So maybe sometime next month?","Sure, let''s ship it today. If it breaks something, we''ll just roll it back."]', '["그럼요. 스탠드업 끝나면 바로 운영 서버에 올릴게요.","먼저 스테이징에서 시험하고 싶어요. 그러니까 다음 달쯤요?","그럼요, 오늘 내보내요. 뭐가 망가지면 그냥 되돌리면 돼요."]', '["Without testing? That makes me nervous.","Next month? It''s one index, right?","I''d rather not find out on the pilot stores."]', '["시험도 안 하고요? 불안한데요.","다음 달요? 인덱스 하나잖아요.","시범 매장에서 알게 되는 건 싫은데요."]', NULL, 'Tomorrow morning works. I''ll tell the store managers.', '내일 아침 좋아요. 매장 관리자들한테 알릴게요.'),
  ('rt_standup_dk_2', 3, 'jun', 'Jun has never worked on the database side. Pairing with him would teach him a lot. The details belong after standup.', '준은 데이터베이스 쪽 일을 해 본 적이 없습니다. 같이 하면 많이 배울 겁니다. 자세한 얘기는 스탠드업 뒤에 할 일입니다.', 'I can help test it on staging, if you want.', '원하시면 스테이징 시험 제가 도울게요.', 'Take him up on the offer, and move the details out of the standup.', '제안을 받아들이고, 자세한 얘기는 스탠드업 밖으로 미루세요.', '[]', 'That''d be great. Let''s pair on it right after standup.', '좋죠. 스탠드업 끝나고 바로 같이 해요.', '["Great. So first, open the query planner and run an explain on the...","Thanks, but it''s faster if I just do it alone. Maybe next time.","Sure. You do the whole thing, and I''ll check it next week."]', '["좋아요. 그럼 먼저 쿼리 플래너를 열고 explain을 돌려서...","고마워요, 근데 혼자 하는 게 빨라요. 다음에 해요.","그래요. 준이 다 하고, 제가 다음 주에 확인할게요."]', '["Uh, maybe after standup?","Oh. Okay, sure. I just wanted to learn.","Next week? I thought it shipped tomorrow."]', '["어, 스탠드업 끝나고 할까요?","아. 네, 알겠어요. 배우고 싶었는데.","다음 주요? 내일 내보내는 줄 알았는데요."]', NULL, 'Cool. I''ll grab my laptop.', '좋아요. 노트북 가져올게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_dk_3', 1, NULL, 'Ten o''clock standup. Yesterday you reviewed two of Jun''s pull requests and read the upgrade notes for the chart library. Today you plan to start the upgrade. Priya hasn''t heard about it yet.', '10시 스탠드업입니다. 어제 당신은 준의 풀 리퀘스트 두 개를 리뷰하고 차트 라이브러리의 업그레이드 안내를 읽었습니다. 오늘은 업그레이드를 시작할 계획입니다. 프리야는 아직 모릅니다.', 'Derek, what''s on your plate?', '데릭, 뭐 하고 있어요?', 'Give your yesterday and today, including the new piece of work.', '새로 생긴 일을 포함해서 어제와 오늘을 말하세요.', '[]', 'Yesterday I reviewed two of Jun''s PRs. Today I''m starting the chart library upgrade.', '어제 준의 PR 두 개를 리뷰했어요. 오늘은 차트 라이브러리 업그레이드를 시작해요.', '["Yesterday I finished the chart library upgrade. Today I''ll review Jun''s two PRs.","Yesterday I reviewed Jun''s PRs. Honestly, there were a lot of mistakes in them.","Yesterday I reviewed a couple of PRs. Today, the usual stuff. Nothing special."]', '["어제 차트 라이브러리 업그레이드를 끝냈어요. 오늘은 준의 PR 두 개를 리뷰할게요.","어제 준의 PR을 리뷰했어요. 솔직히 실수가 많더라고요.","어제 PR 두어 개 리뷰했어요. 오늘은 늘 하던 거요. 별거 없어요."]', '["Finished? I didn''t even know it had started.","Let''s keep that between you and Jun.","Nothing special? Anything I should know about?"]', '["끝냈다고요? 시작한 줄도 몰랐는데요.","그건 준이랑 둘이서 얘기해요.","별거 없어요? 제가 알아야 할 건 없고요?"]', NULL, 'An upgrade? Is that urgent?', '업그레이드요? 급한 거예요?'),
  ('rt_standup_dk_3', 2, NULL, 'The new major version has a security fix. Some charts are set up differently in it, so you estimate about two days of work.', '새 메이저 버전에는 보안 수정이 들어 있습니다. 몇몇 차트는 설정 방식이 달라져서 이틀쯤 걸릴 것으로 봅니다.', 'Is that urgent?', '급한 거예요?', 'Explain why it matters and how long it will take.', '왜 중요한지, 얼마나 걸릴지 설명하세요.', '[]', 'It has a security fix. About two days of work, since some charts change.', '보안 수정이 들어 있어요. 차트 몇 개가 바뀌어서 이틀쯤 걸려요.', '["Not urgent at all. I just like to keep things on the latest version.","The new version has a security fix. It''s a five-minute change, really.","Very urgent. We should stop all other work until it''s done."]', '["전혀 급하지 않아요. 그냥 최신 버전을 쓰는 게 좋아서요.","새 버전에 보안 수정이 있어요. 사실 5분이면 바꿔요.","아주 급해요. 끝날 때까지 다른 일은 다 멈춰야 해요."]', '["Then why now, with everything else going on?","Five minutes? For a whole new version?","Stop everything? Let''s not panic."]', '["그럼 왜 하필 지금요, 다른 일도 많은데?","5분요? 완전히 새 버전인데요?","다 멈추자고요? 너무 놀라지 말아요."]', NULL, 'Okay. Does it affect the rollout?', '알겠어요. 확대 적용에 영향이 있어요?'),
  ('rt_standup_dk_3', 3, NULL, 'The rollout to the next group of stores is two weeks away. Two days of work leaves plenty of room, and you''ll test it on staging first.', '다음 매장들에 확대 적용하는 건 2주 뒤입니다. 이틀 일이면 여유가 충분하고, 먼저 스테이징에서 시험할 겁니다.', 'Will it affect the rollout to the next stores?', '다음 매장 확대 적용에 영향이 있어요?', 'Reassure her, and offer to go over the details later.', '안심시키고, 자세한 건 나중에 설명하겠다고 하세요.', '[]', 'No, there''s plenty of time. I can walk you through the details after standup.', '아니요, 시간은 충분해요. 자세한 건 스탠드업 끝나고 설명할게요.', '["No, there''s plenty of time. Let me go through every chart that changes right now.","Probably, yes. We may have to push the rollout back a couple of weeks.","No idea, honestly. The rollout is more your problem than mine."]', '["아니요, 시간은 충분해요. 바뀌는 차트를 지금 하나하나 짚어 볼게요.","아마 그럴 거예요. 확대 적용을 2주쯤 미뤄야 할 수도 있어요.","솔직히 모르겠어요. 확대 적용은 제 문제라기보다 프리야 문제잖아요."]', '["Maybe after standup? People are waiting.","Push it back? For two days of work?","Well, we''re on the same team, Derek."]', '["스탠드업 끝나고 할까요? 다들 기다려요.","미루자고요? 이틀짜리 일 때문에요?","음, 우린 같은 팀이에요, 데릭."]', NULL, 'Perfect. Put fifteen minutes on my calendar.', '좋아요. 제 달력에 15분 잡아 줘요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_dk_4', 1, NULL, 'Ten o''clock standup. Yesterday you finished the store ID cleanup for the new stores. You wanted to test it on staging today, but staging has been down since last night: every deploy fails with an access error. Nobody knows the cause yet.', '10시 스탠드업입니다. 어제 당신은 새 매장들을 위한 매장 ID 정리를 끝냈습니다. 오늘 스테이징에서 시험하려 했는데, 스테이징이 어젯밤부터 멈춰 있습니다. 배포할 때마다 접근 오류가 납니다. 아직 원인은 아무도 모릅니다.', 'Derek, you''re up.', '데릭, 차례예요.', 'Give your update, and name what''s in your way.', '진행 상황을 말하고, 무엇이 가로막는지 말하세요.', '[]', 'I finished the store ID cleanup yesterday. But I can''t test it: staging''s been down since last night.', '어제 매장 ID 정리를 끝냈어요. 근데 시험을 못 해요. 스테이징이 어젯밤부터 멈췄거든요.', '["I finished the store ID cleanup. I tested it on staging this morning, and it''s all good.","I finished the store ID cleanup. Staging is down again, because IT broke it again.","I finished the store ID cleanup yesterday. No blockers. Everything''s running smoothly."]', '["매장 ID 정리를 끝냈어요. 오늘 아침 스테이징에서 시험했는데 다 괜찮아요.","매장 ID 정리를 끝냈어요. 스테이징이 또 멈췄어요. IT가 또 망가뜨렸거든요.","어제 매장 ID 정리를 끝냈어요. 막힌 건 없어요. 다 잘 돌아가요."]', '["This morning? I heard staging was down all night.","Do we know it was IT? Let''s not guess.","Huh. Jun said staging was down."]', '["오늘 아침요? 스테이징이 밤새 멈춰 있었다던데요.","IT 때문인 건 확실해요? 짐작하지 말아요.","어? 준은 스테이징이 멈췄다던데요."]', NULL, 'Ugh. Has anyone told Sam?', '아이고. 샘한테는 누가 알렸어요?'),
  ('rt_standup_dk_4', 2, NULL, 'Sam Reyes from the IT help desk looks after the staging server. Last night you filed a ticket with him. You haven''t heard back.', 'IT 헬프데스크의 샘 레예스가 스테이징 서버를 관리합니다. 어젯밤 당신이 그에게 티켓을 올렸습니다. 아직 답이 없습니다.', 'Has anyone told Sam?', '샘한테는 누가 알렸어요?', 'Say what you''ve done, and where it stands.', '무엇을 했는지, 지금 어떤 상황인지 말하세요.', '[]', 'I filed a ticket with Sam last night. No reply yet.', '어젯밤에 샘한테 티켓을 올렸어요. 아직 답은 없어요.', '["Not yet. I figured someone else would get to it.","I filed a ticket last night. Sam never answers anything, though.","I filed a ticket last night, and Sam already fixed it."]', '["아직요. 다른 누가 하겠거니 했어요.","어젯밤에 티켓을 올렸어요. 근데 샘은 원래 답을 안 해요.","어젯밤에 티켓을 올렸고, 샘이 벌써 고쳤어요."]', '["Hmm. Someone should, though.","Let''s be fair. He covers the whole office.","Fixed? Then why can''t you test?"]', '["음. 누군가는 알려야죠.","공정하게 말해요. 샘이 사무실 전체를 맡고 있잖아요.","고쳤다고요? 그럼 왜 시험을 못 해요?"]', NULL, 'Okay. Let''s give him a little time.', '알겠어요. 조금만 기다려 봐요.'),
  ('rt_standup_dk_4', 3, 'sam', 'Sam leans in at the meeting room door with his laptop. Meanwhile, Jun has a pull request waiting for your review.', '샘이 노트북을 들고 회의실 문으로 고개를 내밉니다. 마침 준의 풀 리퀘스트가 당신의 리뷰를 기다리고 있습니다.', 'Sorry to barge in. The staging certificate expired last night. I''m renewing it now. About thirty minutes.', '불쑥 들어와서 미안해요. 스테이징 인증서가 어젯밤 만료됐어요. 지금 갱신하고 있어요. 30분쯤 걸려요.', 'Thank him, and say how you''ll use the wait.', '고맙다고 하고, 기다리는 동안 무엇을 할지 말하세요.', '[]', 'Thanks, Sam. I''ll review Jun''s PR in the meantime.', '고마워요, 샘. 그동안 준의 PR을 리뷰할게요.', '["Thirty minutes? Can''t you make it faster? We''re all blocked.","Thanks, Sam. Can we set up auto-renewal right now, together?","Thanks, Sam. I''ll just deploy to production in the meantime."]', '["30분요? 더 빨리 안 돼요? 다들 막혀 있어요.","고마워요, 샘. 지금 같이 자동 갱신을 설정할까요?","고마워요, 샘. 그동안 그냥 운영 서버에 배포할게요."]', '["I''m going as fast as I can, man.","Happy to. After your standup, though?","Whoa. Please don''t do that."]', '["최대한 빨리 하는 중이에요.","좋죠. 근데 스탠드업 끝나고 해요.","워. 제발 그러지 마요."]', NULL, 'Cool. I''ll ping you when it''s back.', '좋아요. 다시 되면 메시지 보낼게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_dk_5', 1, NULL, 'Ten o''clock standup. The team is interviewing for one more backend developer. Yesterday you fixed a bug in the older gift card refund code and sat on an interview panel. Today you''ll write your interview feedback and pair with Jun.', '10시 스탠드업입니다. 팀은 백엔드 개발자 한 명을 더 뽑는 중입니다. 어제 당신은 예전 기프트 카드 환불 코드의 버그를 고치고 면접관으로 들어갔습니다. 오늘은 면접 평가를 쓰고 준과 짝 프로그래밍을 합니다.', 'Derek, what''s new?', '데릭, 새로운 거 있어요?', 'Give your yesterday and today.', '어제와 오늘을 말하세요.', '[]', 'Yesterday, a gift card refund bug and an interview. Today, my feedback and pairing with Jun.', '어제는 기프트 카드 환불 버그랑 면접이요. 오늘은 평가 쓰고 준이랑 같이 코딩해요.', '["Yesterday I sat on an interview panel. The candidate was pretty weak, to be honest with you.","Yesterday I fixed a gift card refund bug. Today I''m on the interview panel, then feedback.","Yesterday I fixed the refund bug. Today I''m just catching up on things. Nothing planned."]', '["어제 면접에 들어갔어요. 솔직히 지원자가 좀 약했어요.","어제 기프트 카드 환불 버그를 고쳤어요. 오늘은 면접에 들어가고, 그다음 평가를 써요.","어제 환불 버그를 고쳤어요. 오늘은 밀린 일만 해요. 계획은 없어요."]', '["Maybe save that for the feedback form.","Today? I thought the interview was yesterday.","Nothing? Weren''t you pairing with Jun?"]', '["그건 평가서에 쓰는 게 좋겠어요.","오늘요? 면접은 어제인 줄 알았는데요.","없다고요? 준이랑 같이 하기로 하지 않았어요?"]', NULL, 'Thanks, Derek.', '고마워요, 데릭.'),
  ('rt_standup_dk_5', 2, 'jun', 'Linda in HR asked panelists to keep their opinions for the written feedback and the debrief, not for team chats.', '인사팀의 린다는 면접관들에게 의견은 팀 잡담이 아니라 서면 평가와 평가 회의에서만 말해 달라고 했습니다.', 'Oh, how was the candidate? Did you like them?', '아, 지원자는 어땠어요? 마음에 들었어요?', 'Kindly decline to talk about the candidate here.', '여기서는 지원자 얘기를 하지 않겠다고 좋게 거절하세요.', '[]', 'I''ll save that for the debrief. Linda wants our feedback in writing first.', '그건 평가 회의 때 말할게요. 린다가 먼저 서면으로 내 달래요.', '["Strong backend skills, but I''m a little worried about the team fit, honestly.","None of your business, Jun. That''s for the people on the panel.","Ask Maya. She was on the panel too, so she can fill you in."]', '["백엔드 실력은 좋은데, 솔직히 팀이랑 잘 맞을지 좀 걱정돼요.","준이 알 일이 아니에요. 그건 면접관들 일이에요.","마야한테 물어봐요. 마야도 면접관이었으니 알려 줄 거예요."]', '["Oh. Should you be telling me that?","Whoa. Sorry I asked.","Really? Is she allowed to tell me?"]', '["아. 그거 저한테 말해도 돼요?","워. 괜히 물어봤네요.","정말요? 마야는 말해도 되는 거예요?"]', NULL, 'Makes sense. Sorry, I was just curious.', '그렇겠네요. 미안해요, 그냥 궁금해서요.'),
  ('rt_standup_dk_5', 3, NULL, 'Next Tuesday at two your calendar is free, but you''re on call all next week and could get paged at any time.', '다음 주 화요일 2시에는 일정이 비어 있지만, 다음 주 내내 온콜이라 언제든 호출이 올 수 있습니다.', 'Speaking of hiring, Linda asked if you could do another panel next Tuesday at two.', '채용 얘기가 나와서 말인데, 린다가 다음 주 화요일 2시 면접도 맡아 줄 수 있냐고 물었어요.', 'Agree, but mention the one thing that could get in the way.', '그러겠다고 하되, 방해가 될 수 있는 한 가지를 말하세요.', '[]', 'Sure, Tuesday at two works. Just so you know, I''m on call that week.', '좋아요, 화요일 2시 괜찮아요. 참고로 그 주에 제가 온콜이에요.', '["Sure, Tuesday at two works. My whole week is totally clear, so no problem.","No, I already did one this month. Ask someone else this time.","Sure. Can we go over the interview questions now, really quickly?"]', '["좋아요, 화요일 2시 괜찮아요. 그 주는 완전히 비어 있어서 문제없어요.","아니요, 저는 이번 달에 벌써 한 번 했어요. 이번엔 다른 사람한테 부탁해요.","좋아요. 지금 면접 질문 좀 빨리 같이 볼까요?"]', '["Aren''t you on call next week?","Hmm. We all have to pitch in, Derek.","After standup, please. We''re almost done."]', '["다음 주 온콜 아니에요?","음. 다들 조금씩 거들어야죠, 데릭.","스탠드업 끝나고요. 거의 다 끝났어요."]', NULL, 'Good to know. I''ll ask Linda to line up a backup.', '알아 둘게요. 린다한테 대타도 구해 두라고 할게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_pr_1', 1, NULL, 'Ten o''clock in the meeting room. Derek, Jun and Maya are all here. Sam from IT never comes to the team standup. You keep it to fifteen minutes: yesterday, today, blockers.', '회의실, 10시입니다. 데릭, 준, 마야가 모두 와 있습니다. IT의 샘은 팀 스탠드업에 오지 않습니다. 당신은 15분 안에 끝냅니다. 어제, 오늘, 막힌 점.', 'Morning. Are we waiting for anyone?', '좋은 아침이에요. 누구 기다려요?', 'Get the meeting going and remind everyone of the format.', '회의를 시작하고, 진행 방식을 다시 알려 주세요.', '[]', 'Nope, everyone''s here. Yesterday, today, blockers. Derek, want to go first?', '아뇨, 다 왔어요. 어제, 오늘, 막힌 점. 데릭, 먼저 할래요?', '["Let''s give Sam five more minutes. He might join us today.","Nope. But before updates, let me walk you through the whole rollout plan.","Nope, everyone''s here. Just talk about whatever''s on your mind."]', '["샘을 5분만 더 기다려요. 오늘은 올지도 몰라요.","아뇨. 근데 진행 상황 전에 확대 적용 계획을 처음부터 설명할게요.","아뇨, 다 왔어요. 그냥 생각나는 대로 얘기해요."]', '["Sam? He never comes to standup.","That sounds long. Maybe after?","Okay... where do I even start?"]', '["샘요? 스탠드업엔 안 오잖아요.","길어질 것 같은데요. 끝나고 할까요?","음... 어디서부터 말하죠?"]', NULL, 'Sure. Yesterday, the store export. Today, code reviews. No blockers.', '그래요. 어제는 매장 내보내기, 오늘은 코드 리뷰, 막힌 건 없어요.'),
  ('rt_standup_pr_1', 2, 'jun', 'Jun''s update has turned into a debate with Derek about switching to a new date library. It has gone on for five minutes, and Maya hasn''t spoken yet.', '준의 진행 상황 보고가 새 날짜 라이브러리로 바꿀지를 두고 데릭과의 논쟁으로 번졌습니다. 벌써 5분째이고, 마야는 아직 말도 못 했습니다.', '...and that''s why I really think we should switch. Derek, don''t you agree?', '...그래서 정말 바꿔야 한다고 생각해요. 데릭, 그렇지 않아요?', 'Stop the debate kindly and give it its own time.', '논쟁을 좋게 멈추고, 따로 시간을 잡아 주세요.', '[]', 'Good topic, but let''s take it offline. You two, ten minutes after this?', '좋은 주제인데, 따로 얘기해요. 둘이 끝나고 10분 어때요?', '["Good topic. Let''s just settle it right now. Derek, what do you think?","Jun, this is running way too long. Please keep it short next time.","Good topic. Let''s put it to a quick vote right now, everyone."]', '["좋은 주제예요. 지금 결론 내요. 데릭, 어떻게 생각해요?","준, 너무 길어요. 다음엔 짧게 해 줘요.","좋은 주제예요. 지금 다 같이 투표해요."]', '["Great! Okay, Derek, so here''s the thing...","Oh. Sorry. I didn''t notice.","A vote? Maya hasn''t even given her update."]', '["좋아요! 그럼 데릭, 그러니까요...","아. 죄송해요. 몰랐어요.","투표요? 마야는 아직 보고도 안 했는데요."]', NULL, 'Sure. Sorry, I got carried away.', '네. 죄송해요, 너무 신났어요.'),
  ('rt_standup_pr_1', 3, NULL, 'Maya has given her update. Fourteen minutes have passed. You are the one who talks to Greg Whitfield at Summit Retail.', '마야도 보고를 마쳤습니다. 14분이 지났습니다. 서밋 리테일의 그렉 휫필드와 연락하는 사람은 당신입니다.', 'Oh, one blocker: I still don''t have the store list from Summit for the next stores.', '아, 막힌 거 하나요. 다음 매장 목록을 서밋에서 아직 못 받았어요.', 'Take this one on yourself and wrap up the meeting.', '이 일은 당신이 맡고, 회의를 마무리하세요.', '[]', 'I''ll chase Greg for that today. Thanks, everyone. See you tomorrow.', '오늘 그렉한테 받아 낼게요. 다들 고마워요. 내일 봐요.', '["Can you email Greg about it yourself? I''m pretty busy today.","I''ll chase Greg today. Before we go, any other topics to discuss?","Okay. Let''s just wait for Greg to send it when he''s ready."]', '["그렉한테 직접 메일 보내 줄래요? 제가 오늘 좀 바빠서요.","오늘 그렉한테 받아 낼게요. 가기 전에, 다른 얘기할 거 있어요?","알겠어요. 그렉이 준비되면 보내 주겠죠, 기다려요."]', '["Me? You''re the one Greg talks to.","We''re at fourteen minutes already.","But I can''t start without it."]', '["저요? 그렉이랑 얘기하는 건 프리야잖아요.","벌써 14분이에요.","근데 그게 없으면 시작을 못 해요."]', NULL, 'Thanks, Priya. See you.', '고마워요, 프리야. 내일 봐요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_pr_2', 1, NULL, 'Ten o''clock standup. Before the meeting, a manager at one of the five pilot stores emailed you: the low-stock list on the dashboard shows items the store doesn''t even carry. Jun built the list. Derek built the data import.', '10시 스탠드업입니다. 회의 전에 시범 매장 다섯 곳 중 한 곳의 관리자가 메일을 보냈습니다. 대시보드의 재고 부족 목록에 그 매장이 팔지도 않는 물건이 나온다고요. 목록은 준이, 데이터 가져오기는 데릭이 만들었습니다.', 'Before we start, you said you had something from the stores?', '시작하기 전에, 매장에서 온 게 있다고 했죠?', 'Share the feedback briefly, without blaming anyone.', '누구 탓도 하지 말고 매장 의견을 짧게 전하세요.', '[]', 'Yes. A pilot store says the low-stock list shows items they don''t carry.', '네. 시범 매장 한 곳에서 재고 부족 목록에 안 파는 물건이 나온대요.', '["Yes. A pilot store says Jun''s low-stock list is broken again.","Yes. A pilot store says the dashboard won''t load for them at all.","Yes. The store manager wrote me a long email. Let me read you all of it."]', '["네. 시범 매장 한 곳에서 준이 만든 재고 부족 목록이 또 고장 났대요.","네. 시범 매장 한 곳에서 대시보드가 아예 안 뜬대요.","네. 매장 관리자가 긴 메일을 보냈어요. 전부 읽어 드릴게요."]', '["Let''s not put that on Jun yet.","Won''t load? It loads fine for me.","Maybe just the short version?"]', '["아직 준 탓으로 돌리지 말아요.","안 뜬다고요? 저는 잘 뜨는데요.","짧게 요점만 말해 줄래요?"]', NULL, 'Hmm. That might be my import, not his list.', '음. 그건 준의 목록이 아니라 제 가져오기 문제일 수도 있어요.'),
  ('rt_standup_pr_2', 2, 'jun', 'Derek thinks the product catalog may not be filtered by store when it''s imported. Other people are still waiting to give their updates.', '데릭은 상품 목록을 가져올 때 매장별로 걸러지지 않는 것 같다고 봅니다. 다른 사람들은 아직 보고를 기다리고 있습니다.', 'Should I look into it? I built that list.', '제가 볼까요? 그 목록은 제가 만들었어요.', 'Decide who looks into it, and keep the standup moving.', '누가 살펴볼지 정하고, 스탠드업은 계속 진행하세요.', '[]', 'Yes, with Derek. It might be the import. Can you two check after standup?', '네, 데릭이랑 같이요. 가져오기 문제일 수도 있어요. 둘이 끝나고 봐 줄래요?', '["Yes, please. Actually, let''s all dig into it together right now.","No, Derek can handle it. Jun, you don''t need to touch it.","Let''s just leave it for now. It''s only one store out of five, after all."]', '["네, 부탁해요. 아니, 지금 다 같이 파 봐요.","아니요, 데릭이 하면 돼요. 준은 손대지 않아도 돼요.","일단 그냥 둬요. 어차피 다섯 곳 중 한 곳뿐이잖아요."]', '["Now? Everyone else still has updates.","Oh. Okay. I just wanted to help.","But it''s one of our pilot stores, right?"]', '["지금요? 다른 분들 보고가 아직 남았는데요.","아. 네. 그냥 돕고 싶었어요.","근데 우리 시범 매장이잖아요?"]', NULL, 'Sure. We''ll sort it out.', '네. 해결해 볼게요.'),
  ('rt_standup_pr_2', 3, NULL, 'You handle all communication with the stores. Derek and Jun expect to know more by the end of the day.', '매장과의 연락은 모두 당신이 맡습니다. 데릭과 준은 오늘 안에 더 알게 될 것 같다고 합니다.', 'Should we tell the store anything?', '매장에 뭐라고 해야 할까요?', 'Say how you''ll handle the store.', '매장에 어떻게 대응할지 말하세요.', '[]', 'I''ll reply that we''re on it, with an update by the end of the day.', '지금 살펴보고 있다고 답하고, 오늘 안에 다시 알려 드릴게요.', '["I''ll just tell them it''s fixed, so they stop worrying about it.","Let''s not reply until we know more. That could take a few days.","Maybe you could reply, Derek? You know the data better than I do."]', '["그냥 고쳤다고 할게요. 그래야 걱정을 안 하죠.","더 알 때까지 답하지 말아요. 며칠 걸릴 수도 있어요.","데릭이 답해 줄래요? 데이터는 데릭이 더 잘 알잖아요."]', '["Fixed? We haven''t even looked yet.","A few days? They''ll think we ignored them.","Isn''t talking to the stores your thing?"]', '["고쳤다고요? 아직 보지도 않았는데요.","며칠요? 무시당했다고 생각할 거예요.","매장 연락은 프리야 일 아니에요?"]', NULL, 'Sounds good. We''ll have something for you by four.', '좋아요. 4시까지 알려 드릴게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_pr_3', 1, NULL, 'Ten o''clock standup. The team board is up on the screen. Four tickets have said in progress for more than two weeks, and two of them have Derek''s name on them.', '10시 스탠드업입니다. 화면에 팀 보드가 떠 있습니다. 티켓 네 개가 2주 넘게 진행 중으로 남아 있고, 그중 두 개에 데릭의 이름이 있습니다.', 'Morning. Want me to start?', '좋은 아침이에요. 제가 먼저 할까요?', 'Before the updates, raise the board problem without singling anyone out.', '진행 상황을 듣기 전에, 누구를 콕 집지 말고 보드 문제를 꺼내세요.', '[]', 'Sure, but first: a few tickets look stale. Could everyone update their statuses today?', '그래요, 근데 먼저요. 묵은 티켓이 좀 보여요. 다들 오늘 상태를 갱신해 줄래요?', '["Sure, but first: Derek, two of your tickets haven''t moved in weeks. What''s going on?","Sure, but first: let''s go through every ticket on the board, one by one, right now.","Sure. The board looks great, by the way. Everything''s right up to date."]', '["그래요, 근데 먼저요. 데릭, 데릭 티켓 두 개가 몇 주째 그대로예요. 어떻게 된 거예요?","그래요, 근데 먼저요. 지금 보드의 티켓을 하나하나 다 짚어 봐요.","그래요. 그나저나 보드가 아주 좋네요. 전부 최신 상태예요."]', '["Oof. Okay. In front of everyone?","Every ticket? That''s an hour.","Really? Some of those look pretty old."]', '["윽. 네. 다들 보는 앞에서요?","티켓 전부요? 한 시간은 걸려요.","정말요? 꽤 오래된 것도 있던데요."]', NULL, 'Fair. Some of mine are definitely out of date. Okay, me first.', '맞아요. 제 것도 분명 오래된 게 있어요. 그럼 저부터 할게요.'),
  ('rt_standup_pr_3', 2, NULL, 'Derek is building the data API for the new store comparison page. Jun is already building the page itself, and yesterday he said he was guessing at the data format.', '데릭은 새 매장 비교 페이지에 쓸 데이터 API를 만들고 있습니다. 준은 이미 페이지를 만들고 있고, 어제 데이터 형식을 짐작으로 하고 있다고 했습니다.', 'Today I''m building the API for the comparison page. Should be done in a couple of days.', '오늘은 비교 페이지 API를 만들어요. 이틀쯤이면 끝날 거예요.', 'Connect his work to Jun''s, and suggest they team up.', '그의 일을 준의 일과 이어 주고, 둘이 손을 맞추자고 하세요.', '[]', 'Jun''s building that page and guessing at the format. Could you two sync after standup?', '준이 그 페이지를 만들면서 형식을 짐작하고 있어요. 둘이 끝나고 맞춰 볼래요?', '["Great. Jun can just wait until your API is done, and then start the page.","Jun''s building that page too. Can you two settle the format right now, here?","Great. Jun hasn''t started the page yet, so there''s no rush on your side."]', '["좋아요. 준은 데릭 API가 끝날 때까지 기다렸다가 페이지를 시작하면 돼요.","준도 그 페이지를 만들고 있어요. 둘이 지금 여기서 형식을 정할래요?","좋아요. 준은 아직 페이지를 시작 안 했으니 서두를 필요 없어요."]', '["Wait a couple of days? That seems like a waste.","Here? We''d hold everyone up.","Hasn''t he? I thought he started already."]', '["이틀이나 기다려요? 아까운데요.","여기서요? 다들 붙잡아 두게 돼요.","안 했어요? 벌써 시작한 줄 알았는데요."]', NULL, 'Good catch. Jun, let''s talk right after this.', '잘 짚었어요. 준, 끝나고 바로 얘기해요.'),
  ('rt_standup_pr_3', 3, 'jun', 'Until the format is settled, Jun can keep building the page layout, so his work isn''t actually stopped.', '형식이 정해질 때까지 준은 페이지 레이아웃을 계속 만들 수 있으니, 그의 일은 실제로 멈춘 게 아닙니다.', 'Sure. Should I mark my page ticket as blocked until we agree on the format?', '좋아요. 형식을 정할 때까지 제 페이지 티켓을 막힘으로 바꿀까요?', 'Answer so the board shows the real state of his work.', '보드가 그의 일의 실제 상태를 보여 주도록 답하세요.', '[]', 'Not blocked, since you can keep building the layout. Just add a note about the format.', '막힘은 아니에요. 레이아웃은 계속 만들 수 있으니까요. 형식 얘기만 메모로 남겨요.', '["Yes, mark it blocked, and stop working on it until Derek''s API is done.","Don''t bother with the board, honestly. Nobody really looks at it anyway.","Not blocked. Actually, just mark it done, so the board looks good for Greg."]', '["네, 막힘으로 바꾸고 데릭 API가 끝날 때까지 손 놓고 있어요.","솔직히 보드는 신경 쓰지 말아요. 어차피 아무도 잘 안 봐요.","막힘은 아니에요. 그냥 완료로 바꿔요. 그렉이 보기에 좋게요."]', '["Stop? But I can still do the layout.","Oh. Didn''t you just ask us to update it?","Done? But it isn''t, though."]', '["손 놓으라고요? 레이아웃은 계속할 수 있는데요.","어. 방금 갱신해 달라고 하지 않았어요?","완료요? 아직 안 끝났는데요."]', NULL, 'Got it. I''ll add the note right after this.', '알겠어요. 끝나고 바로 메모 남길게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_pr_4', 1, 'jun', 'Ten o''clock standup. The designer says the design for the new store comparison page will be ready tomorrow. Meanwhile, pilot stores have asked for a fix: some dashboard colors are hard to read for color-blind staff.', '10시 스탠드업입니다. 디자이너는 새 매장 비교 페이지의 디자인이 내일 나온다고 합니다. 한편 시범 매장들은 색맹인 직원이 대시보드의 몇몇 색을 읽기 어렵다며 수정을 요청했습니다.', 'Today I wanted to start the comparison page, but the design isn''t ready. So I''m kind of stuck.', '오늘 비교 페이지를 시작하려 했는데 디자인이 아직이에요. 그래서 좀 막혀 있어요.', 'Suggest something useful for Jun to do until the design arrives.', '디자인이 나올 때까지 준이 할 만한 쓸모 있는 일을 제안하세요.', '[]', 'The design lands tomorrow. Could you take the color contrast fix today?', '디자인은 내일 나와요. 오늘은 색 대비 수정을 맡아 줄래요?', '["The design lands tomorrow. Just start coding the page without it today.","Why isn''t it ready yet? Who''s holding it up this time?","The design lands next week. Could you take the color fix until then?"]', '["디자인은 내일 나와요. 오늘은 디자인 없이 그냥 페이지 코딩을 시작해요.","왜 아직 안 됐어요? 이번엔 누가 붙잡고 있는 거예요?","디자인은 다음 주에 나와요. 그때까지 색 수정을 맡아 줄래요?"]', '["Without a design? I might have to redo it all.","Uh, I''m not sure. The designer just said tomorrow.","Next week? I heard tomorrow."]', '["디자인 없이요? 전부 다시 해야 할 수도 있어요.","어, 잘 모르겠어요. 디자이너는 그냥 내일이라고 했어요.","다음 주요? 저는 내일이라고 들었는데요."]', NULL, 'Sure. The store managers will like that one.', '좋아요. 매장 관리자들이 좋아하겠네요.'),
  ('rt_standup_pr_4', 2, NULL, 'Derek gets excited. A full redesign of the color theme would take days and isn''t planned.', '데릭이 신이 납니다. 색 테마를 통째로 다시 짜면 며칠이 걸리고, 계획에도 없습니다.', 'Ooh, if we''re touching colors, we should rethink the whole theme. Like, the reds we use for alerts...', '오, 색을 건드릴 거면 테마 전체를 다시 생각해야 해요. 예를 들어 경고에 쓰는 빨간색이...', 'Acknowledge the idea, but keep the standup on track.', '아이디어는 인정하되, 스탠드업이 옆길로 새지 않게 하세요.', '[]', 'Good point, but that''s a bigger one. Let''s talk it through after standup.', '좋은 지적인데, 그건 더 큰 얘기예요. 스탠드업 끝나고 얘기해요.', '["Good point. Let''s redesign the whole theme right now, together.","Derek, that''s not your job. Leave the colors to the designer.","Good point. Jun, go ahead and change the whole theme today, then."]', '["좋은 지적이에요. 지금 다 같이 테마 전체를 다시 짜요.","데릭, 그건 데릭 일이 아니에요. 색은 디자이너한테 맡겨요.","좋은 지적이에요. 그럼 준, 오늘 테마 전체를 바꿔요."]', '["Right now? We''d be here all morning.","Whoa. I was just trying to help.","The whole theme? That''s way more than a day."]', '["지금요? 오전 내내 여기 있게 될걸요.","워. 그냥 도우려던 건데요.","테마 전체요? 하루로는 어림없어요."]', NULL, 'Fair. I''ll grab you after.', '그래요. 끝나고 찾아갈게요.'),
  ('rt_standup_pr_4', 3, 'maya', 'The comparison page is due to Summit Retail at the end of next week. Losing one day to the design still leaves enough room in the schedule.', '비교 페이지는 다음 주 말까지 서밋 리테일에 넘기기로 했습니다. 디자인 때문에 하루를 잃어도 일정에는 아직 여유가 있습니다.', 'Do we need to tell Summit the comparison page slipped a day?', '비교 페이지가 하루 밀렸다고 서밋에 알려야 해요?', 'Answer her, and give the reason.', '대답하고, 이유를 말하세요.', '[]', 'Not yet. There''s still room in the schedule, so the date holds.', '아직은요. 일정에 여유가 있어서 날짜는 안 바뀔 거예요.', '["Yes, let''s tell Greg it''ll be two weeks late, just to be safe.","No need. Greg never really reads our updates anyway.","Not yet. There''s no room in the schedule, so let''s just hope."]', '["네, 혹시 모르니 그렉한테 2주 늦어진다고 해요.","그럴 필요 없어요. 어차피 그렉은 우리 소식을 잘 안 읽어요.","아직은요. 일정에 여유가 없으니 그냥 잘되길 바라요."]', '["Two weeks? For one day?","Let''s not assume that.","Hope isn''t much of a plan."]', '["2주요? 하루 밀린 걸로요?","그렇게 단정하지 말아요.","바라는 건 계획이 아니잖아요."]', NULL, 'Okay. Flag it if that changes.', '좋아요. 상황이 바뀌면 알려 줘요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_standup_pr_5', 1, NULL, 'Ten o''clock standup, your turn. Yesterday Greg Whitfield called: he''d like weather on the dashboard, so stores can plan their staffing. You told him the team would look into it. Nothing was promised.', '10시 스탠드업, 당신 차례입니다. 어제 그렉 휫필드가 전화했습니다. 매장이 인력 배치를 계획할 수 있게 대시보드에 날씨를 넣고 싶다고요. 당신은 팀이 검토해 보겠다고 했고, 아무것도 약속하지 않았습니다.', 'Priya, your turn.', '프리야, 차례예요.', 'Share the news, and be clear about what you did and didn''t agree to.', '소식을 전하고, 무엇에 동의했고 무엇에 동의하지 않았는지 분명히 하세요.', '[]', 'Greg asked for weather on the dashboard. I told him we''d look into it, nothing more.', '그렉이 대시보드에 날씨를 넣어 달래요. 검토해 보겠다고만 했어요.', '["Greg asked for weather on the dashboard. I said we''d have it ready next week.","Greg wants weather now. Honestly, he changes his mind every other week.","Greg called about weather. It''s not that important, though, so moving on."]', '["그렉이 대시보드에 날씨를 넣어 달래요. 다음 주까지 해 주겠다고 했어요.","그렉이 이번엔 날씨를 원해요. 솔직히 그 사람은 툭하면 마음이 바뀌어요.","그렉이 날씨 얘기로 전화했어요. 별로 중요하진 않으니 넘어갈게요."]', '["Next week? Without asking us?","Careful. He''s our client on this.","Weather? That sounds kind of big."]', '["다음 주요? 우리한테 묻지도 않고요?","조심해요. 이 일의 고객이잖아요.","날씨요? 꽤 큰 일 같은데요."]', NULL, 'Weather, huh. That could get big.', '날씨라. 일이 커질 수도 있겠네요.'),
  ('rt_standup_pr_5', 2, 'jun', 'Jun lights up. Derek starts to say something about the cost of weather data. The standup is already at twelve minutes.', '준의 얼굴이 밝아집니다. 데릭이 날씨 데이터 비용 얘기를 꺼내려 합니다. 스탠드업은 벌써 12분째입니다.', 'Ooh, weather! We could show a forecast for each store, and color the busy days, and...', '오, 날씨! 매장마다 예보를 보여 주고, 바쁜 날은 색으로 표시하고...', 'Thank Jun for the energy, and give the idea its own time.', '준의 열의에 고마워하고, 그 아이디어는 따로 시간을 잡아 주세요.', '[]', 'Love the energy. Let''s set up thirty minutes this afternoon for it.', '열정 좋아요. 오늘 오후에 30분 따로 잡아요.', '["Love the energy. Let''s design it right here, while we''re all together.","Jun, slow down. It''s not really up to you what we build.","Love the energy. Start building it today, and we''ll surprise Greg."]', '["열정 좋아요. 다 모였을 때 여기서 바로 설계해요.","준, 천천히 해요. 뭘 만들지는 준이 정하는 게 아니에요.","열정 좋아요. 오늘 만들기 시작해서 그렉을 놀라게 해 줘요."]', '["Here? We''re almost out of time, though.","Oh. Sorry. I just got excited.","Today? I thought nothing was promised yet."]', '["여기서요? 시간이 거의 다 됐는데요.","아. 죄송해요. 그냥 신나서요.","오늘요? 아직 약속한 건 없다면서요."]', NULL, 'Sure! I''ll bring some ideas.', '좋아요! 아이디어 좀 가져갈게요.'),
  ('rt_standup_pr_5', 3, NULL, 'This sprint is already full with the rollout to the next group of stores, and Summit has said the rollout comes first.', '이번 스프린트는 다음 매장들로의 확대 적용으로 이미 꽉 찼고, 서밋은 확대 적용이 먼저라고 했습니다.', 'Before we wrap up: should weather go into this sprint?', '끝내기 전에요. 날씨를 이번 스프린트에 넣어요?', 'Give a clear answer based on priorities.', '우선순위에 따라 분명하게 답하세요.', '[]', 'No, the rollout comes first. We''ll size weather for the next sprint.', '아니요, 확대 적용이 먼저예요. 날씨는 다음 스프린트를 위해 규모를 가늠해 봐요.', '["Yes, let''s squeeze it in somehow. The rollout can slip a little.","Yes, add it. Greg will be happy, and in the end that''s what matters.","No, and let''s not do weather at all. It''s just a distraction."]', '["네, 끼워 넣어요. 확대 적용은 좀 밀려도 돼요.","네, 넣어요. 그렉이 좋아할 거고, 그게 중요하죠.","아니요, 날씨는 아예 하지 말아요. 괜히 정신만 사나워요."]', '["Summit said the rollout comes first, though.","Sure, but the sprint''s already full.","At all? Greg might not love that."]', '["서밋이 확대 적용이 먼저라고 했잖아요.","그렇긴 한데, 스프린트가 이미 꽉 찼어요.","아예요? 그렉이 별로 안 좋아할걸요."]', NULL, 'Works for me. Good standup.', '좋아요. 좋은 스탠드업이었어요.');
REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('rt_1on1_jun_1', '1:1: too much on your plate', '1:1: 할 일이 너무 많아요', 'office_manager', 'maya', 16, NULL, '10:45', '11:45', NULL, 'Your biweekly 1:1 with Maya. Be honest about your workload, agree on what can wait, and work out how to handle the next extra request.', '격주로 하는 마야와의 1:1입니다. 업무량을 솔직하게 말하고, 미뤄도 되는 일을 정하고, 다음에 일이 더 들어오면 어떻게 할지 정하세요.', 0, 0, 2100, 'meeting,manager,one-on-one,routine', 'jun'),
  ('rt_1on1_jun_2', '1:1: where you want to grow', '1:1: 어떻게 성장하고 싶은지', 'office_manager', 'maya', 16, NULL, '10:45', '11:45', NULL, 'Maya wants to talk about the long term. Share a career goal, ask how reviews work here, take her feedback well, and agree on a next step.', '마야가 장기적인 이야기를 하고 싶어 합니다. 커리어 목표를 말하고, 이곳의 평가가 어떻게 이뤄지는지 묻고, 그녀의 피드백을 잘 받아들이고, 다음 단계를 정하세요.', 0, 0, 2101, 'meeting,manager,one-on-one,routine', 'jun'),
  ('rt_1on1_jun_3', '1:1: a conference and feedback for Maya', '1:1: 콘퍼런스, 그리고 마야에게 하는 피드백', 'office_manager', 'maya', 16, NULL, '10:45', '11:45', NULL, 'Ask Maya to use your training budget on a developer conference, explain what the team gets out of it, give her honest feedback when she asks, and say how your work will be covered.', '교육 예산으로 개발자 콘퍼런스에 가도 되는지 마야에게 묻고, 팀에 어떤 도움이 되는지 설명하고, 그녀가 물으면 솔직한 피드백을 주고, 자리를 비우는 동안 일이 어떻게 돌아갈지 말하세요.', 0, 0, 2102, 'meeting,manager,one-on-one,routine', 'jun'),
  ('rt_1on1_dk_1', '1:1: the pager won''t stop', '1:1: 호출이 멈추지 않아요', 'office_manager', 'maya', 16, NULL, '10:45', '11:45', NULL, 'In your biweekly 1:1, be honest with Maya about the on-call load, propose a fix for a noisy alert, plan some real time off, and help her spread the rotation.', '격주 1:1에서 온콜 부담을 마야에게 솔직하게 말하고, 쓸데없이 울리는 알림을 고칠 방법을 제안하고, 제대로 된 휴가를 계획하고, 온콜 순번을 나누는 일을 도우세요.', 0, 0, 2103, 'meeting,manager,one-on-one,routine', 'derek'),
  ('rt_1on1_dk_2', '1:1: surprises mid-sprint', '1:1: 스프린트 중간의 깜짝 요청', 'office_manager', 'maya', 16, NULL, '10:45', '11:45', NULL, 'Raise a working problem with Priya without blaming her, agree on how to handle it, and make sure Jun gets credit for good work.', '프리야와의 업무상 문제를 그녀를 탓하지 않고 꺼내고, 어떻게 풀지 정하고, 준이 잘한 일을 제대로 인정받게 하세요.', 0, 0, 2104, 'meeting,manager,one-on-one,routine', 'derek'),
  ('rt_1on1_dk_3', '1:1: interviews and what''s next', '1:1: 면접, 그리고 다음 단계', 'office_manager', 'maya', 16, NULL, '10:45', '11:45', NULL, 'Give Maya a clear update on the backend developer interviews, keep your interview load manageable, and talk honestly about your own career path.', '백엔드 개발자 면접 진행 상황을 마야에게 분명하게 알리고, 면접 부담을 감당할 만하게 조절하고, 당신의 커리어 방향을 솔직하게 이야기하세요.', 0, 0, 2105, 'meeting,manager,one-on-one,routine', 'derek'),
  ('rt_1on1_pr_1', 'PM-EM sync: Greg wants more', 'PM-EM 싱크: 그렉이 더 원해요', 'office_manager', 'maya', 16, NULL, '10:45', '11:45', NULL, 'Your biweekly sync with Maya. Tell her what the client is asking for, agree on a trade-off, and plan how you''ll take it to Greg.', '마야와 격주로 하는 싱크입니다. 고객이 무엇을 요청했는지 말하고, 무엇을 내주고 무엇을 지킬지 정하고, 그렉에게 어떻게 전할지 계획하세요.', 0, 0, 2106, 'meeting,manager,one-on-one,routine', 'priya'),
  ('rt_1on1_pr_2', 'PM-EM sync: the hire and the roadmap', 'PM-EM 싱크: 채용과 로드맵', 'office_manager', 'maya', 16, NULL, '10:45', '11:45', NULL, 'Update Maya on the backend developer hire, adjust the phase two plan to match, give balanced feedback on Jun, and tell Maya one thing that would help you.', '백엔드 개발자 채용 상황을 마야에게 알리고, 그에 맞게 2단계 계획을 조정하고, 준에 대해 균형 잡힌 피드백을 주고, 당신에게 도움이 될 한 가지를 마야에게 말하세요.', 0, 0, 2107, 'meeting,manager,one-on-one,routine', 'priya'),
  ('rt_1on1_pr_3', 'PM-EM sync: running on empty', 'PM-EM 싱크: 방전 직전', 'office_manager', 'maya', 16, NULL, '10:45', '11:45', NULL, 'Maya has noticed your late-night emails. Be honest about how you''re doing, plan some time off with coverage, set a sensible limit, and give credit to a colleague.', '마야가 당신의 늦은 밤 메일을 알아챘습니다. 지금 상태를 솔직하게 말하고, 대신 맡을 사람을 정해 휴가를 계획하고, 적당한 선을 정하고, 동료의 공을 알리세요.', 0, 0, 2108, 'meeting,manager,one-on-one,routine', 'priya');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_jun_1', 1, NULL, 'Your biweekly 1:1 in Maya''s office. Lately you''ve been staying until seven: store rollout tickets, code reviews, and an estimate Priya asked you for on the mobile app.', '마야의 방에서 격주로 하는 1:1입니다. 요즘 일곱 시까지 남아 있습니다. 매장 확대 티켓, 코드 리뷰, 거기에 프리야가 부탁한 모바일 앱 견적까지요.', 'Hi, Jun. Have a seat. So, how are things going? Be honest.', '안녕하세요, 준. 앉아요. 요즘 어때요? 솔직하게요.', 'Tell her the truth about how the last couple of weeks have felt, and why.', '지난 2주가 어땠는지 이유와 함께 솔직하게 말하세요.', '[]', 'Honestly, I''m stretched thin. Rollout tickets, reviews, Priya''s estimate... I''m here until seven.', '솔직히 좀 벅차요. 확대 티켓, 리뷰, 프리야가 부탁한 견적까지... 일곱 시까지 있어요.', '["Great, actually. The rollout is quiet, so I''ve had plenty of time for reviews and Priya''s estimate.","Honestly, it''s a mess. Priya keeps dumping her work on me, and I''m here until seven every night.","It''s fine. I can handle anything you give me. Feel free to add more if the team needs it."]', '["좋아요, 사실. 확대 적용이 조용해서 리뷰도 하고 프리야 견적도 할 시간이 넉넉해요.","솔직히 엉망이에요. 프리야가 자기 일을 자꾸 저한테 떠넘겨서 매일 일곱 시까지 있어요.","괜찮아요. 뭘 주셔도 다 할 수 있어요. 팀에 필요하면 더 주셔도 돼요."]', '["Quiet? Then why do I see you online at seven?","Let''s keep it about the work, not about Priya. What did she ask for?","I appreciate that, but I need the real picture, Jun."]', '["조용하다고요? 그럼 일곱 시에 왜 접속해 있는 거예요?","프리야 말고 일 얘기를 하죠. 프리야가 뭘 부탁했어요?","고마운 말이지만, 실제 상황을 알아야 해요, 준."]', NULL, 'Thanks for telling me. That''s exactly what these 1:1s are for.', '말해 줘서 고마워요. 1:1이 바로 그러라고 있는 거예요.'),
  ('rt_1on1_jun_1', 2, NULL, 'Maya pulls up the team board. The store rollout is the top priority right now. The mobile app is phase two, and no work on it has started yet.', '마야가 팀 보드를 띄웁니다. 지금 최우선은 매장 확대 적용입니다. 모바일 앱은 2단계이고, 아직 아무 작업도 시작하지 않았습니다.', 'Okay. Let''s look at it together. What could wait?', '좋아요. 같이 봐요. 뭘 미룰 수 있을까요?', 'Suggest which task can be pushed back, based on what matters most right now.', '지금 무엇이 가장 중요한지를 근거로, 뒤로 미룰 일을 제안하세요.', '[]', 'The mobile estimate, I think. Phase two hasn''t started, so the rollout comes first.', '모바일 견적이요. 2단계는 아직 시작 전이니까 확대 적용이 먼저일 것 같아요.', '["The rollout tickets, I think. The stores can wait a bit, but Priya needs her estimate.","Nothing, really. If I skip lunch for a week or two, I can get it all done.","The code reviews. Derek can just merge his own changes for a while."]', '["확대 티켓이요. 매장은 좀 기다려도 되지만, 프리야는 견적이 필요하잖아요.","딱히 없어요. 한두 주 점심을 거르면 다 할 수 있어요.","코드 리뷰요. 당분간 데릭이 자기 코드는 직접 머지하면 되잖아요."]', '["Hmm. The stores are what Greg is watching right now.","Skipping lunch isn''t a plan, Jun.","Without a review? I''d rather not."]', '["흠. 지금 그렉이 지켜보는 게 바로 매장이에요.","점심 거르는 건 계획이 아니에요, 준.","리뷰 없이요? 그건 안 하는 게 좋겠어요."]', NULL, 'Agreed. I''ll tell Priya the estimate moves to later. She''ll understand.', '동의해요. 견적은 나중으로 미룬다고 제가 프리야한테 말할게요. 이해할 거예요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_jun_1', 3, NULL, 'Maya taps her pen on her notebook.', '마야가 펜으로 공책을 톡톡 두드립니다.', 'Next time someone brings you something extra, what will you do?', '다음에 누가 일을 더 가져오면 어떻게 할 거예요?', 'Say how you''ll handle new requests without taking everything on or turning people away.', '모든 걸 떠안지도, 사람을 돌려보내지도 않고 새 요청을 어떻게 다룰지 말하세요.', '[]', 'I''ll ask how urgent it is, and check with you or Derek before I say yes.', '얼마나 급한지 묻고, 수락하기 전에 마야나 데릭에게 확인할게요.', '["I''ll just say no. I already have enough work, and they can find someone else.","I''ll say yes and stay late. I don''t want anyone to think I''m not a team player.","I''ll send them all to you. You can decide on everything that comes to me."]', '["그냥 거절할게요. 일은 이미 충분하니까 다른 사람을 찾으면 되죠.","수락하고 늦게까지 남을게요. 팀을 생각 안 하는 사람처럼 보이기 싫어요.","전부 마야한테 보낼게요. 저한테 오는 건 다 마야가 정하시면 돼요."]', '["That might come across badly. Most requests are fair ones.","That''s how we got here, Jun.","Everything? Let''s not go that far. You can make some calls yourself."]', '["그러면 안 좋게 비칠 수 있어요. 대부분은 정당한 요청이에요.","그래서 지금 이렇게 된 거예요, 준.","전부요? 그렇게까진 말고요. 어떤 건 준이 직접 정해도 돼요."]', NULL, 'Perfect. "Let me check first" is always a fine answer.', '좋아요. "먼저 확인해 볼게요"는 언제든 괜찮은 대답이에요.'),
  ('rt_1on1_jun_1', 4, NULL, 'The half hour is almost up.', '30분이 거의 다 됐습니다.', 'Anything else on your mind before we wrap up?', '마무리하기 전에 더 하고 싶은 얘기 있어요?', 'Thank her, and say what you''ll do right after this meeting.', '고맙다고 하고, 회의가 끝나면 바로 무엇을 할지 말하세요.', '[]', 'No, that helped a lot. I''ll update the board to show the estimate as later.', '아니요, 많이 도움됐어요. 견적이 뒤로 밀린 게 보이게 보드를 고쳐 둘게요.', '["No, that helped. I''ll go tell Priya myself that her estimate is cancelled.","Not really. I''ll get back to the estimate and try to finish it tonight.","Actually, could we make these monthly? Every two weeks feels like a lot."]', '["아니요, 도움됐어요. 견적은 취소됐다고 제가 직접 프리야한테 말할게요.","딱히요. 다시 견적으로 돌아가서 오늘 밤에 끝내 볼게요.","사실, 이거 한 달에 한 번으로 하면 안 될까요? 2주마다는 좀 많은 것 같아요."]', '["Cancelled? It''s just later. And I said I''d talk to her.","Tonight? We just agreed it can wait.","Let''s keep them for now. I think they''re helping."]', '["취소요? 그냥 나중으로 미룬 거예요. 그리고 프리야한테는 제가 말한다고 했잖아요.","오늘 밤에요? 방금 미뤄도 된다고 했잖아요.","당분간은 이대로 해요. 도움이 되고 있는 것 같아요."]', NULL, 'Great. Let me know if you have any questions.', '좋아요. 궁금한 게 있으면 언제든 말해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_jun_2', 1, NULL, 'Your biweekly 1:1. Maya has a fresh page in her notebook titled "Jun: goals." You enjoy the backend data work most, and you liked working with the store managers in the pilot.', '격주 1:1입니다. 마야의 공책에 "준: 목표"라고 적힌 새 페이지가 펼쳐져 있습니다. 당신은 백엔드 데이터 작업이 제일 재미있고, 시범 운영 때 매장 관리자들과 일한 것도 좋았습니다.', 'Today I''d like to talk about the long term. Where do you want to be in a year or two?', '오늘은 장기적인 얘기를 하고 싶어요. 1~2년 뒤에 어디에 있고 싶어요?', 'Share a goal that fits what you enjoy most.', '가장 즐기는 일에 맞는 목표를 말하세요.', '[]', 'I''d like to own a backend service end to end, and keep working with the stores.', '백엔드 서비스 하나를 처음부터 끝까지 맡고 싶어요. 매장과 일하는 것도 계속하고 싶고요.', '["I''d like to move to frontend design. Data work isn''t really my thing, to be honest.","Honestly, I want your job. Give me a year, and I''ll be managing this whole team.","I haven''t really thought about it. I just work on whatever tickets I get each day."]', '["프런트엔드 디자인 쪽으로 가고 싶어요. 솔직히 데이터 작업은 잘 안 맞아요.","솔직히 마야 자리를 원해요. 1년만 주시면 이 팀 전체를 관리하고 있을 거예요.","별로 생각 안 해 봤어요. 그냥 매일 받는 티켓을 처리할 뿐이에요."]', '["Really? Derek says the data side is where you shine.","Ha. Ambition is good. Let''s start with a step or two before that.","That''s okay, but I''d like you to think about it. It''s your career."]', '["정말요? 데릭은 준이 데이터 쪽에서 빛난다던데요.","하. 야망은 좋아요. 그 전에 한두 걸음부터 시작하죠.","괜찮아요, 그래도 생각해 봤으면 해요. 준의 커리어니까요."]', NULL, 'I like that. Owning a service is a very reachable goal here.', '좋네요. 서비스 하나를 맡는 건 여기서 충분히 이룰 수 있는 목표예요.'),
  ('rt_1on1_jun_2', 2, NULL, 'New hires here get a performance review and a raise discussion after their first 90 days. After that, reviews come twice a year.', '이곳 신입은 첫 90일이 지나면 성과 평가와 연봉 논의를 합니다. 그 뒤로는 1년에 두 번 평가가 있습니다.', 'That ties into your reviews. Do you know how they work here?', '그게 평가와도 이어져요. 여기서 평가가 어떻게 되는지 알아요?', 'Admit what you don''t know, and ask what she looks at.', '모르는 건 모른다고 하고, 그녀가 무엇을 보는지 물어보세요.', '[]', 'Not really. What do you look at, and how can I prepare?', '잘 몰라요. 어떤 걸 보시고, 저는 어떻게 준비하면 돼요?', '["Sure. Reviews are just about how many tickets I close, right?","Yes. And I''d like a big raise, so let''s plan for that now.","Not really. But that''s HR''s job, so I''ll just ask Linda."]', '["그럼요. 평가는 티켓을 몇 개 처리했는지만 보는 거죠?","네. 그리고 연봉을 많이 올리고 싶으니까 지금부터 그걸 계획해요.","잘 몰라요. 그래도 그건 인사팀 일이니까 린다한테 물어볼게요."]', '["Tickets are part of it, but far from all of it.","Let''s talk about the work first, then the numbers.","Linda can explain the forms, but I write your review."]', '["티켓도 일부지만, 그게 전부는 절대 아니에요.","일 얘기를 먼저 하고, 숫자는 그다음에 하죠.","서류는 린다가 설명해 줄 수 있지만, 평가는 제가 써요."]', NULL, 'Impact, teamwork, and growth. Keep a short list of your wins as you go. It makes it much easier.', '성과, 팀워크, 성장이요. 잘한 일을 그때그때 짧게 적어 두세요. 훨씬 쉬워져요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_jun_2', 3, NULL, 'Maya sets her pen down.', '마야가 펜을 내려놓습니다.', 'Here''s one thing to work on. In design discussions, you go quiet, even when you have good ideas. Derek has noticed too.', '하나 개선할 점이 있어요. 설계 논의 때 좋은 아이디어가 있어도 조용해져요. 데릭도 알아챘고요.', 'Take the feedback well, and ask for a way to get better at it.', '피드백을 잘 받아들이고, 나아질 방법을 청하세요.', '[]', 'That''s fair. I worry about being wrong. Could I get a chance to practice?', '맞는 말이에요. 틀릴까 봐 걱정돼서요. 연습할 기회를 얻을 수 있을까요?', '["That''s not really fair. Derek talks so much that nobody else gets a word in.","Okay. From now on, I''ll speak up in every meeting, about everything.","Sorry. I''m just not good at that stuff. I''m more of a quiet coder."]', '["그건 좀 불공평해요. 데릭이 말을 너무 많이 해서 다른 사람은 끼어들 틈이 없어요.","알겠어요. 이제부터 모든 회의에서 모든 것에 대해 말할게요.","죄송해요. 그런 건 원래 잘 못해요. 저는 조용히 코딩하는 타입이라서요."]', '["Derek does talk a lot. But this is about you, Jun.","Every meeting? Let''s aim for the ones that count.","I think you''re selling yourself short."]', '["데릭이 말이 많긴 하죠. 그래도 이건 준 얘기예요.","모든 회의요? 중요한 회의부터 목표로 하죠.","스스로를 너무 낮춰 보는 것 같아요."]', NULL, 'Being wrong is fine. That''s what design talks are for.', '틀려도 괜찮아요. 설계 논의가 그러라고 있는 거예요.'),
  ('rt_1on1_jun_2', 4, NULL, 'The team holds a design review whenever a big piece of work starts. The next one is about a new sales report for the stores.', '팀은 큰 작업을 시작할 때마다 설계 리뷰를 합니다. 다음 리뷰는 매장용 새 매출 보고서에 관한 것입니다.', 'Here''s an idea. How about you lead the next design review?', '이건 어때요? 다음 설계 리뷰를 준이 진행해 보는 거예요.', 'Accept, and say what help you''d like to get ready for it.', '받아들이고, 준비하는 데 어떤 도움을 받고 싶은지 말하세요.', '[]', 'I''ll do it. Could I walk Derek through my plan the day before?', '할게요. 전날 데릭에게 제 계획을 먼저 보여 줘도 될까요?', '["I''ll do it, as long as Derek runs the meeting and I just take notes.","Sure, no prep needed. I''ll just figure it out as I go in the room.","Maybe later. Let me watch a few more first, and then I''ll decide."]', '["할게요. 회의는 데릭이 진행하고 저는 메모만 한다면요.","그럼요, 준비는 필요 없어요. 회의실에서 하면서 알아서 할게요.","나중에요. 몇 번 더 지켜보고 나서 정할게요."]', '["Then Derek is leading it, Jun.","A little prep would go a long way.","You''ve watched plenty. I think you''re ready."]', '["그럼 진행하는 건 데릭이잖아요, 준.","조금만 준비해도 훨씬 나을 거예요.","충분히 지켜봤어요. 준비된 것 같아요."]', NULL, 'Great plan. He''ll be glad to help. Let me know if you have any questions.', '좋은 계획이에요. 데릭도 기꺼이 도울 거예요. 궁금한 게 있으면 언제든 말해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_jun_3', 1, NULL, 'Your biweekly 1:1. Each developer has a training budget of $1,500 a year, and you haven''t used yours. A two-day developer conference is coming up in Ridgeport: $600 a ticket, plus one night at a hotel.', '격주 1:1입니다. 개발자마다 1년에 1,500달러의 교육 예산이 있는데, 당신은 아직 쓰지 않았습니다. 리지포트에서 이틀짜리 개발자 콘퍼런스가 곧 열립니다. 티켓은 600달러, 호텔 1박이 추가됩니다.', 'So, what''s on your list today?', '자, 오늘은 어떤 얘기를 할까요?', 'Bring up the conference, and ask whether you can go.', '콘퍼런스 얘기를 꺼내고, 가도 되는지 물어보세요.', '[]', 'There''s a developer conference in Ridgeport. Could I use my training budget for it?', '리지포트에서 개발자 콘퍼런스가 있어요. 거기에 교육 예산을 써도 될까요?', '["There''s a developer conference in Ridgeport. I already bought a ticket. Is that okay?","There''s a conference I''d like to go to. Could the company cover the whole week?","Could I get some money for training? I''m not sure what for yet, but something."]', '["리지포트에서 개발자 콘퍼런스가 있어요. 티켓은 벌써 샀어요. 괜찮죠?","가고 싶은 콘퍼런스가 있어요. 회사에서 일주일 전부 지원해 줄 수 있어요?","교육비를 좀 받을 수 있을까요? 뭘 할지는 아직 모르겠지만 뭔가요."]', '["You bought it already? Next time, ask first, please.","A whole week? I thought it was a two-day event.","Come back when you have something specific in mind."]', '["벌써 샀어요? 다음엔 먼저 물어봐 줘요.","일주일 전부요? 이틀짜리 행사인 줄 알았는데요.","구체적으로 생각한 게 생기면 다시 와요."]', NULL, 'You haven''t touched your budget yet, so it''s possible. Tell me more.', '아직 예산을 하나도 안 썼으니 가능해요. 더 얘기해 봐요.'),
  ('rt_1on1_jun_3', 2, NULL, 'Half the talks are about building mobile apps: the same kind of work as phase two, the mobile app for Summit Retail.', '발표의 절반이 모바일 앱 개발에 관한 것입니다. 서밋 리테일의 모바일 앱인 2단계와 같은 종류의 일입니다.', 'What would you and the team get out of it?', '준과 팀에는 어떤 도움이 될까요?', 'Connect the conference to the team''s upcoming work, and offer to pass on what you learn.', '콘퍼런스를 팀의 다음 일과 연결하고, 배운 걸 전하겠다고 하세요.', '[]', 'Half the talks are on mobile apps, which we''ll need for phase two. I''ll share notes after.', '발표 절반이 모바일 앱이라 2단계에 필요해요. 다녀와서 정리한 걸 공유할게요.', '["Half the talks are on mobile apps, and I''d love to see Ridgeport again. It''s a great city.","Mostly networking, honestly. It''s good to meet people, in case I ever look for a new job.","Half the talks are on web design, which we''ll need for the store dashboard rollout."]', '["발표 절반이 모바일 앱이고, 리지포트도 다시 가 보고 싶어요. 멋진 도시예요.","솔직히 주로 인맥이요. 혹시 이직할 때를 대비해서 사람을 만나 두면 좋잖아요.","발표 절반이 웹 디자인이라 매장 대시보드 확대 적용에 필요해요."]', '["The city is a nice bonus, but I need a work reason.","Hmm. That''s not quite what I want to hear, Jun.","Web design? I thought it was mostly mobile."]', '["도시는 덤이고, 업무상 이유가 필요해요.","흠. 그건 별로 듣고 싶은 말이 아니네요, 준.","웹 디자인이요? 주로 모바일인 줄 알았는데요."]', NULL, 'That''s a good case. A short talk at the team meeting afterward would be great.', '좋은 근거네요. 다녀와서 팀 회의 때 짧게 발표해 주면 좋겠어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_jun_3', 3, NULL, 'Maya asks everyone on her team this question. Lately, priority changes reach you late: you often find out after you''ve already started on something else.', '마야는 팀원 모두에게 이 질문을 합니다. 요즘 우선순위 변경이 늦게 전해집니다. 다른 일을 이미 시작한 뒤에야 알게 되는 일이 잦습니다.', 'Now it''s my turn to ask. What''s one thing I could do better as your manager?', '이번엔 제가 물어볼게요. 매니저로서 제가 더 잘할 수 있는 게 하나 있다면 뭘까요?', 'Give her honest, specific feedback in a constructive way.', '솔직하고 구체적인 피드백을 건설적으로 전하세요.', '[]', 'Could I hear about priority changes sooner? Sometimes I''ve already started something else.', '우선순위가 바뀌는 걸 좀 더 일찍 들을 수 있을까요? 가끔은 이미 다른 일을 시작한 뒤라서요.', '["Nothing, really. You''re a great manager. I wouldn''t change a single thing about you.","Honestly, priorities change all the time, and nobody around here ever tells me anything.","Could we have fewer 1:1s? I could use that time to close more of my tickets instead."]', '["딱히 없어요. 훌륭한 매니저세요. 하나도 바꾸고 싶은 게 없어요.","솔직히 우선순위가 맨날 바뀌는데, 여기선 아무도 저한테 아무 말도 안 해 줘요.","1:1을 좀 줄이면 안 될까요? 그 시간에 티켓을 더 처리할 수 있을 텐데요."]', '["That''s kind, but there''s always something. Think about it.","Nobody? That''s a little strong. Can you give me an example?","I''d rather keep them. Is there something else behind that?"]', '["고마운 말이지만, 뭔가 늘 있기 마련이에요. 생각해 봐요.","아무도요? 좀 지나친 말 같은데요. 예를 하나 들어 줄래요?","1:1은 유지하고 싶어요. 그 말 뒤에 다른 이유가 있어요?"]', NULL, 'That''s fair, and useful. I''ll give you a heads-up as soon as I know.', '맞는 말이고, 도움이 돼요. 제가 아는 즉시 미리 알려 줄게요.'),
  ('rt_1on1_jun_3', 4, NULL, 'The conference is on a Thursday and Friday. You aren''t on call that week, and Derek offered to keep an eye on your rollout tickets while you''re away.', '콘퍼런스는 목요일과 금요일입니다. 그 주에 당신은 온콜이 아니고, 데릭이 자리를 비우는 동안 확대 티켓을 봐 주겠다고 했습니다.', 'Send me the details, and I''ll approve it. Who covers your work while you''re gone?', '자세한 걸 보내 주면 승인할게요. 없는 동안 일은 누가 맡아요?', 'Tell her how your work will be covered.', '일이 어떻게 처리될지 말하세요.', '[]', 'Derek offered to watch my rollout tickets, and I''m not on call that week.', '데릭이 확대 티켓을 봐 주기로 했고, 그 주엔 제가 온콜이 아니에요.', '["Nobody, really. I''ll just check my email at the conference between talks.","Derek offered to watch my tickets, and I''ll do my on-call shift from the hotel.","I figured you could watch them. You know the rollout better than anyone."]', '["딱히 없어요. 콘퍼런스에서 발표 사이사이에 메일을 확인할게요.","데릭이 티켓을 봐 주기로 했고, 온콜은 호텔에서 할게요.","마야가 봐 주시면 될 것 같았어요. 확대 적용은 누구보다 잘 아시잖아요."]', '["Then you won''t really be at the conference.","On call? I thought you weren''t on that week.","Me? I don''t think so. I''m in meetings all day."]', '["그럼 콘퍼런스에 제대로 있는 게 아니잖아요.","온콜이요? 그 주엔 아닌 줄 알았는데요.","저요? 안 될 것 같아요. 저는 하루 종일 회의예요."]', NULL, 'Sounds good. Have fun, and learn a lot. Let me know if you have any questions.', '좋아요. 재밌게 다녀오고, 많이 배워 와요. 궁금한 게 있으면 언제든 말해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_dk_1', 1, NULL, 'Your biweekly 1:1. With more stores on the dashboard, you were paged at night three times on your last on-call week. Two were the same sync alert, and both were false alarms.', '격주 1:1입니다. 대시보드를 쓰는 매장이 늘면서, 지난 온콜 주간에 밤에 세 번 호출을 받았습니다. 두 번은 같은 동기화 알림이었고, 둘 다 오경보였습니다.', 'Derek, you look tired. How are you holding up?', '데릭, 피곤해 보여요. 좀 어때요?', 'Be honest about how the on-call week went, with the facts.', '온콜 주간이 어땠는지 사실대로 솔직하게 말하세요.', '[]', 'Not great. Three nights of pages, and two were false alarms from one sync alert.', '별로예요. 사흘 밤 호출이 왔는데, 두 번은 같은 동기화 알림의 오경보였어요.', '["Fine. It was a quiet week. Just one page, and it was a real problem I fixed fast.","Not great. Jun''s code keeps waking me up at night. Someone should talk to him.","I''m fine. I''ve done on call for ten years. A few pages never hurt anybody."]', '["괜찮아요. 조용한 주였어요. 호출은 한 번뿐이었고, 진짜 문제라 금방 고쳤어요.","별로예요. 준이 짠 코드 때문에 밤마다 깨요. 누가 준한테 말 좀 해야 해요.","괜찮아요. 온콜만 10년째예요. 호출 몇 번에 큰일 안 나요."]', '["One? The log shows three.","Is it really Jun''s code? Let''s look at the alerts first.","Maybe. But you look like it hurt a little."]', '["한 번이요? 기록엔 세 번인데요.","정말 준의 코드 때문이에요? 알림부터 보죠.","그럴지도요. 그래도 좀 힘들었던 얼굴인데요."]', NULL, 'Three nights is a lot. And false alarms are the worst kind.', '사흘 밤이면 많아요. 게다가 오경보가 제일 나쁜 종류고요.'),
  ('rt_1on1_dk_1', 2, NULL, 'The sync alert fires whenever a store''s data is a few minutes late, which happens every night during the stores'' backups.', '동기화 알림은 매장 데이터가 몇 분만 늦어도 울리는데, 매일 밤 매장 백업 시간마다 그렇게 됩니다.', 'What would help?', '뭐가 도움이 될까요?', 'Suggest a practical fix for the noisy alert.', '시끄러운 알림을 고칠 현실적인 방법을 제안하세요.', '[]', 'Let''s change the alert so it waits out the nightly backups. I can do it this week.', '알림이 밤마다 하는 백업 시간은 기다리도록 바꾸죠. 이번 주에 제가 할 수 있어요.', '["Let''s just turn off the sync alert. If something''s really wrong, the stores will call us.","Let''s change the alert, but I''m swamped. Could Priya ask Greg to stop the backups?","Honestly, someone else should take on call for a while. I''ve done more than my share."]', '["그냥 동기화 알림을 끄죠. 정말 문제가 있으면 매장에서 전화하겠죠.","알림을 바꾸긴 해야 하는데 너무 바빠요. 프리야가 그렉한테 백업을 멈춰 달라고 할 수 있을까요?","솔직히 당분간 다른 사람이 온콜을 맡아야 해요. 저는 할 만큼 했어요."]', '["And find out from Greg? I''d rather not.","The backups are theirs, Derek. We can''t ask them to stop.","Maybe, but that doesn''t fix the alert."]', '["그걸 그렉한테 듣고 알자고요? 그건 싫어요.","백업은 그쪽 거예요, 데릭. 멈추라고 할 순 없어요.","그럴 수도 있지만, 그런다고 알림이 고쳐지진 않아요."]', NULL, 'Do it. Put it at the top of your list, ahead of new work.', '그렇게 해요. 새 작업보다 앞에, 목록 맨 위에 두세요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_dk_1', 3, NULL, 'You have nine days of PTO left this year, and you haven''t taken a day off in months.', '올해 유급 휴가가 9일 남아 있고, 몇 달째 하루도 쉬지 않았습니다.', 'And when did you last take real time off?', '그리고 마지막으로 제대로 쉰 게 언제예요?', 'Admit it''s been too long, and say what you''ll do about it.', '너무 오래됐다고 인정하고, 어떻게 할지 말하세요.', '[]', 'It''s been months. I have nine days left. I''ll plan a few once the alert is fixed.', '몇 달 됐어요. 9일 남았어요. 알림 고치고 나서 며칠 계획할게요.', '["Last month, I think. I only have two days left, so I''ll save them for emergencies.","Not in a while. But the rollout needs me, so I''ll just take time off next year.","It''s been months. I''ll take all nine days starting tomorrow. You''ll figure it out."]', '["지난달이었던 것 같아요. 이틀밖에 안 남아서 급할 때 쓰려고 아껴 둘게요.","꽤 됐어요. 그래도 확대 적용에 제가 필요하니까 휴가는 내년에 쓸게요.","몇 달 됐어요. 내일부터 9일 다 쓸게요. 알아서 해 주세요."]', '["Two? HR says you have nine.","Days you don''t take just disappear, Derek.","Tomorrow? Let''s give the team a little notice."]', '["이틀이요? 인사팀은 9일이라던데요.","안 쓴 휴가는 그냥 사라져요, 데릭.","내일요? 팀에 조금은 미리 알려 주죠."]', NULL, 'Good. Pick days when you''re not on call, and put them on the team calendar.', '좋아요. 온콜이 아닌 날로 골라서 팀 달력에 올려요.'),
  ('rt_1on1_dk_1', 4, NULL, 'Jun has asked to learn on call, but he hasn''t been on the rotation yet.', '준이 온콜을 배우고 싶다고 했지만, 아직 순번에 들어간 적은 없습니다.', 'One more thing. Should we grow the rotation, so it doesn''t all land on a few people?', '하나 더요. 몇 사람한테만 몰리지 않게 온콜 순번을 늘릴까요?', 'Agree, and suggest a careful way to bring Jun in.', '동의하고, 준을 신중하게 합류시킬 방법을 제안하세요.', '[]', 'Yes. Jun could shadow my next on-call week, then take one with me as backup.', '네. 준이 다음 제 온콜 주간을 옆에서 보고, 그다음엔 제가 백업을 서고 한 주 맡으면 돼요.', '["Yes. Put Jun on alone next week. He''ll learn fastest by figuring it out himself.","No. Jun asked, but he''s too new. On call is a senior job, and I''d rather keep it.","Yes. Let''s wait for the backend hire and give most of the rotation to them."]', '["네. 다음 주에 준 혼자 맡겨요. 스스로 해결해 봐야 제일 빨리 배워요.","아니요. 준이 원하긴 하지만 너무 신입이에요. 온콜은 시니어 일이니 제가 계속할게요.","네. 백엔드 신입이 오면 순번 대부분을 그 사람한테 주죠."]', '["Alone? That''s a lot for his first time.","You just told me it''s wearing you down.","Most of it, in their first weeks? That''s not fair to them."]', '["혼자요? 처음치고는 너무 벅차요.","방금 지쳐 간다고 했잖아요.","들어오자마자 대부분을요? 그건 그 사람한테 불공평해요."]', NULL, 'I like it. Talk to Jun, and I''ll update the schedule. Let me know if you have any questions.', '좋아요. 준과 얘기해 봐요. 일정표는 제가 고칠게요. 궁금한 게 있으면 언제든 말해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_dk_2', 1, NULL, 'Your biweekly 1:1. Twice this sprint, Priya added small requests from Greg in the middle of the sprint without checking with you, and the team had to drop planned work.', '격주 1:1입니다. 이번 스프린트에 두 번, 프리야가 당신과 상의 없이 그렉의 작은 요청을 스프린트 중간에 넣었고, 팀은 계획한 일을 빼야 했습니다.', 'What''s on your list today?', '오늘은 어떤 얘기가 있어요?', 'Raise the problem calmly, focusing on what it does to the team.', '팀에 미치는 영향에 초점을 맞춰 차분하게 문제를 꺼내세요.', '[]', 'Mid-sprint requests. Twice now, new work came in and we dropped planned tickets.', '스프린트 중간 요청이요. 벌써 두 번 새 일이 들어와서 계획했던 티켓을 빼야 했어요.', '["Priya. She keeps saying yes to Greg, and I''m tired of cleaning up after her.","Mid-sprint requests. One small one came in this sprint, but it''s no big deal.","Mid-sprint requests. From now on, I''ll just ignore anything that comes in late."]', '["프리야요. 그렉한테 계속 알겠다고 하는데, 뒤처리하는 데 지쳤어요.","스프린트 중간 요청이요. 이번에 작은 게 하나 들어왔는데, 별일 아니에요.","스프린트 중간 요청이요. 앞으로 늦게 들어오는 건 그냥 무시할게요."]', '["Let''s keep it about the work, not about Priya.","Then why is it on your list?","That''s not your call alone, Derek."]', '["프리야 말고 일 얘기를 하죠.","그럼 왜 오늘 얘기할 거리에 있어요?","그건 데릭 혼자 정할 일이 아니에요."]', NULL, 'That''s a real problem. Dropped work hurts both the team and the client.', '실제로 문제네요. 계획한 일이 빠지면 팀도 고객도 손해예요.'),
  ('rt_1on1_dk_2', 2, NULL, 'You haven''t talked to Priya about it yet. You wanted Maya''s advice first.', '아직 프리야와 이 얘기를 하지 않았습니다. 먼저 마야의 조언을 듣고 싶었습니다.', 'Have you talked to Priya about it?', '프리야하고 얘기해 봤어요?', 'Answer honestly, and say how you''ll take it from here.', '솔직하게 답하고, 이제 어떻게 할지 말하세요.', '[]', 'Not yet. I''ll talk to her and suggest we look at new requests together first.', '아직이요. 프리야와 얘기해서, 새 요청은 먼저 같이 보자고 제안할게요.', '["Yes, twice, and she didn''t listen. That''s why I''m bringing it to you now.","Not yet. I was hoping you could tell her for me. It''s easier coming from you.","Not yet. I''ll send her a long email tonight with every example, and copy you."]', '["네, 두 번이나요. 근데 안 듣더라고요. 그래서 지금 마야한테 가져온 거예요.","아직이요. 마야가 대신 말해 주셨으면 해요. 마야가 말하는 게 낫잖아요.","아직이요. 오늘 밤에 사례를 전부 적어서 긴 메일을 보낼게요. 마야도 참조로 넣고요."]', '["Twice? She hasn''t mentioned it to me.","It''s better coming from you. You two work together every day.","A long email at night? A face-to-face talk would go better."]', '["두 번이요? 프리야는 저한테 아무 말 없었는데요.","데릭이 말하는 게 나아요. 둘이 매일 같이 일하잖아요.","밤에 긴 메일이요? 얼굴 보고 얘기하는 게 나을 거예요."]', NULL, 'Good. If you two get stuck, bring it to me, and we''ll sort it out together.', '좋아요. 둘이 풀리지 않으면 저한테 가져와요. 같이 정리해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_dk_2', 3, NULL, 'Last sprint, Jun found a bug in a store''s sales totals before the client noticed. He fixed it, wrote a clear note to the team, and stayed calm the whole time.', '지난 스프린트에 준이 고객이 알아채기 전에 한 매장의 매출 합계 버그를 찾았습니다. 그는 버그를 고치고, 팀에 명확한 설명을 남기고, 내내 침착했습니다.', 'Okay. Anything else?', '좋아요. 또 있어요?', 'Make sure Jun''s work gets noticed, with the details.', '준이 한 일이 자세히 알려지게 하세요.', '[]', 'Yes, Jun. He caught a sales totals bug before the client saw it, and his write-up was great.', '네, 준이요. 고객이 보기 전에 매출 합계 버그를 잡았고, 정리한 글도 훌륭했어요.', '["Yes, Jun. He caught a bug in the sales totals, but honestly, I had to fix most of it myself.","Yes, the sales totals bug. I caught it before the client saw it, and I fixed it fast.","Yes, Jun. He''s doing fine. Nothing special this sprint, but no problems either."]', '["네, 준이요. 매출 합계 버그를 잡긴 했는데, 솔직히 대부분은 제가 고쳤어요.","네, 매출 합계 버그요. 고객이 보기 전에 제가 잡아서 금방 고쳤어요.","네, 준이요. 잘하고 있어요. 이번엔 특별한 건 없지만 문제도 없어요."]', '["Really? His note says he fixed it.","You did? I heard it was Jun.","Nothing special? Wasn''t there a bug he caught?"]', '["정말요? 준의 글엔 자기가 고쳤다고 돼 있던데요.","데릭이요? 준이 했다고 들었는데요.","특별한 게 없다고요? 준이 잡은 버그가 있지 않았어요?"]', NULL, 'That''s great to hear. I hadn''t heard the details.', '좋은 소식이네요. 자세한 얘기는 못 들었었어요.'),
  ('rt_1on1_dk_2', 4, NULL, 'Maya writes Jun''s performance reviews, and feedback from teammates goes into them.', '준의 성과 평가는 마야가 쓰고, 동료들의 피드백도 평가에 들어갑니다.', 'Should I thank him at the team meeting, or would you like to?', '팀 회의에서 제가 고맙다고 할까요, 아니면 데릭이 할래요?', 'Suggest a way to recognize him that also helps him at review time.', '그를 인정하면서 평가 때도 도움이 될 방법을 제안하세요.', '[]', 'Let me thank him at standup. Could you note it for his review, too?', '스탠드업에서 제가 고맙다고 할게요. 평가에도 적어 주실래요?', '["Let''s not make a big deal of it. Too much praise might go to his head.","You do it. And maybe give him a raise right away, while you''re at it.","Let me thank him at standup. Reviews are just about numbers, so skip that."]', '["크게 만들지 말죠. 칭찬이 지나치면 우쭐해질 수도 있어요.","마야가 해 주세요. 하는 김에 바로 연봉도 좀 올려 주시고요.","스탠드업에서 제가 고맙다고 할게요. 평가는 숫자만 보니까 거긴 빼도 돼요."]', '["Hmm. A little praise goes a long way, Derek.","Raises go through the review, not a team meeting.","Not just numbers. This is exactly what I look for."]', '["흠. 칭찬 조금이 큰 힘이 돼요, 데릭.","연봉은 팀 회의가 아니라 평가를 거쳐요.","숫자만이 아니에요. 바로 이런 걸 봐요."]', NULL, 'Deal. I''ll add it to his notes. Let me know if you have any questions.', '좋아요. 평가 메모에 넣을게요. 궁금한 게 있으면 언제든 말해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_dk_3', 1, NULL, 'Your biweekly 1:1. You''ve interviewed four candidates for the backend role. One stood out: strong on databases and great at explaining her thinking. The other three struggled with system design.', '격주 1:1입니다. 백엔드 자리 지원자 네 명을 면접했습니다. 한 명이 돋보였습니다. 데이터베이스에 강하고 자기 생각을 잘 설명했습니다. 나머지 셋은 시스템 설계에서 고전했습니다.', 'How''s the backend hiring going from your side?', '데릭이 보기에 백엔드 채용은 어떻게 돼 가요?', 'Give her a short, clear update with your recommendation.', '추천 의견과 함께 짧고 분명하게 알리세요.', '[]', 'Four interviews so far. One stood out, strong on databases. I''d move her forward.', '지금까지 네 명 봤어요. 한 명이 돋보였는데, 데이터베이스에 강해요. 다음 단계로 올리고 싶어요.', '["Four interviews so far. They were all strong, so honestly, I''d hire any of them.","Not great. Nobody''s been good enough. Maybe we should stop looking for now.","Four so far. One stood out, so let''s skip the rest and make her an offer today."]', '["지금까지 네 명 봤어요. 다 뛰어나서 솔직히 누굴 뽑아도 좋아요.","별로예요. 괜찮은 사람이 없었어요. 당분간 채용을 멈춰야 할지도요.","지금까지 넷이요. 한 명이 돋보였으니 나머지 절차는 건너뛰고 오늘 제안하죠."]', '["All of them? Your notes say three struggled with design.","Nobody? I thought one of them did really well.","Today? She still has to meet me and Priya."]', '["다요? 메모엔 셋이 설계에서 고전했다던데요.","아무도요? 한 명은 정말 잘했다고 들었는데요.","오늘요? 아직 저랑 프리야도 만나야 해요."]', NULL, 'Good. I''ll set up her final round with me and Priya.', '좋아요. 저랑 프리야와 하는 최종 면접을 잡을게요.'),
  ('rt_1on1_dk_3', 2, NULL, 'The panel takes about two hours of your week: two interviews, plus a write-up for each. On busy days, the write-ups pile up.', '면접관 일은 일주일에 두 시간쯤 걸립니다. 면접 두 번에, 면접마다 평가서를 써야 합니다. 바쁜 날엔 평가서가 밀립니다.', 'You''re on a lot of panels. Is it too much on top of the dashboard?', '면접에 많이 들어가네요. 대시보드 일까지 하면 너무 많아요?', 'Be honest that it''s mostly manageable, and suggest one change.', '대체로 할 만하다고 솔직히 말하고, 바꿀 점 하나를 제안하세요.', '[]', 'Mostly fine, but the write-ups pile up. Could I block time right after each one?', '대체로 괜찮은데 평가서가 밀려요. 면접 직후에 시간을 따로 잡아 둬도 될까요?', '["It''s way too much. Please take me off the panel completely. Someone else can do it.","It''s fine. When I''m busy, I just skip the write-ups and tell Linda in person.","Mostly it''s fine. Could Jun do the write-ups for me? He has some free time."]', '["너무 많아요. 면접관에서 완전히 빼 주세요. 다른 사람이 하면 돼요.","괜찮아요. 바쁠 땐 평가서는 건너뛰고 린다한테 직접 말해요.","대체로 괜찮아요. 평가서는 준이 대신 써 주면 안 될까요? 준이 좀 한가하거든요."]', '["Completely? You''re our best interviewer, Derek.","We need those in writing. It''s only fair to the candidates.","Jun wasn''t in the room. That wouldn''t work."]', '["완전히요? 데릭이 우리 최고의 면접관인데요.","평가는 글로 남겨야 해요. 그래야 지원자한테 공정해요.","준은 면접에 없었잖아요. 그건 안 돼요."]', NULL, 'Do it. Put thirty minutes after each interview on your calendar.', '그렇게 해요. 면접마다 바로 뒤에 30분을 달력에 잡아 둬요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_dk_3', 3, NULL, 'You love the technical side and don''t want to stop coding. Mentoring Jun has been the best part of your year.', '당신은 기술 쪽 일을 좋아하고 코딩을 그만두고 싶지 않습니다. 올해 가장 좋았던 건 준을 이끌어 준 일이었습니다.', 'Now let''s talk about you. Down the road, do you see yourself managing people, or growing as an engineer?', '이제 데릭 얘기를 하죠. 앞으로 사람을 관리하는 쪽이에요, 엔지니어로 성장하는 쪽이에요?', 'Share your honest preference, and what you enjoy most.', '솔직한 선호와 가장 즐기는 일을 말하세요.', '[]', 'Growing as an engineer. But I''d like to keep mentoring. That''s been the best part.', '엔지니어로 성장하는 쪽이요. 그래도 멘토링은 계속하고 싶어요. 그게 제일 좋았어요.', '["Managing people, for sure. Honestly, I''m tired of coding and ready to stop for good.","Whichever pays more, honestly. I''ll go wherever the money is. No hard feelings.","Growing as an engineer. And I''d rather not mentor anymore. It slows me down."]', '["당연히 관리 쪽이요. 솔직히 코딩은 지겨워서 이제 완전히 그만두고 싶어요.","솔직히 돈 더 주는 쪽이요. 돈 있는 데로 갈 거예요. 나쁜 뜻은 없어요.","엔지니어로 성장하는 쪽이요. 그리고 멘토링은 그만하고 싶어요. 속도가 느려져요."]', '["Really? I''ve never seen you happier than in a code review.","Ha. Fair, but let''s think about what you enjoy.","That surprises me. Jun says you''re a great mentor."]', '["정말요? 코드 리뷰할 때만큼 즐거워 보이는 걸 본 적이 없는데요.","하. 그럴 수 있죠. 그래도 뭘 즐기는지 생각해 봐요.","의외네요. 준은 데릭이 훌륭한 멘토라던데요."]', NULL, 'That makes sense. A senior engineering path has plenty of room for mentoring.', '이해돼요. 시니어 엔지니어의 길에도 멘토링할 자리는 많아요.'),
  ('rt_1on1_dk_3', 4, NULL, 'Phase two, a mobile app for Summit Retail, needs someone to design how it talks to the dashboard''s backend.', '서밋 리테일의 모바일 앱인 2단계에는 앱이 대시보드 백엔드와 어떻게 연결될지 설계할 사람이 필요합니다.', 'Then let''s set a goal for your next review. Any ideas?', '그럼 다음 평가 때까지의 목표를 정하죠. 생각나는 거 있어요?', 'Suggest a concrete goal tied to the team''s next big project.', '팀의 다음 큰 프로젝트와 연결된 구체적인 목표를 제안하세요.', '[]', 'I''d like to lead the technical design for the phase two mobile app.', '2단계 모바일 앱의 기술 설계를 이끌고 싶어요.', '["I''d like to rewrite the whole dashboard from scratch. It''s already getting messy.","I''d like to lead the phase two design, and also manage Jun officially.","Maybe just to do good work? Goals like that are hard to pin down anyway."]', '["대시보드를 처음부터 전부 다시 짜고 싶어요. 벌써 지저분해지고 있어요.","2단계 설계를 이끌고, 준도 공식적으로 관리하고 싶어요.","그냥 일 잘하기 정도는 어때요? 어차피 그런 목표는 딱 정하기 어렵잖아요."]', '["From scratch? It''s live in the stores, Derek.","Manage Jun? You just said you''d rather not manage.","Let''s be more specific than that."]', '["처음부터요? 매장에서 이미 쓰고 있어요, 데릭.","준을 관리한다고요? 방금 관리 쪽은 아니라고 했잖아요.","그보다는 더 구체적으로 정하죠."]', NULL, 'That''s a great goal. I''ll write it down. Let me know if you have any questions.', '좋은 목표예요. 적어 둘게요. 궁금한 게 있으면 언제든 말해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_pr_1', 1, NULL, 'Your biweekly PM-EM sync with Maya. Greg Whitfield emailed this morning: he wants a new weekly sales report on every store''s dashboard before the rollout is finished. The team is already at full capacity.', '마야와 격주로 하는 PM-EM 싱크입니다. 오늘 아침 그렉 휘트필드가 메일을 보냈습니다. 확대 적용이 끝나기 전에 모든 매장 대시보드에 새 주간 매출 보고서를 넣어 달라고요. 팀은 이미 여력이 없습니다.', 'Hi, Priya. What''s the latest from Summit Retail?', '안녕하세요, 프리야. 서밋 리테일 쪽 최근 소식은요?', 'Sum up the request and your concern in a few words.', '요청과 걱정되는 점을 짧게 요약하세요.', '[]', 'Greg wants a new sales report before the rollout ends. But the team is already full.', '그렉이 확대 적용이 끝나기 전에 새 매출 보고서를 원해요. 그런데 팀은 이미 꽉 찼어요.', '["Greg wants a new sales report, and I already told him yes. Can the team fit it in?","Greg wants a new sales report before the rollout ends. The team has plenty of room.","Greg is being difficult again. He always wants more and never wants to pay for it."]', '["그렉이 새 매출 보고서를 원하는데, 이미 하겠다고 했어요. 팀이 끼워 넣을 수 있을까요?","그렉이 확대 적용이 끝나기 전에 새 매출 보고서를 원해요. 팀은 여유가 충분해요.","그렉이 또 까다롭게 굴어요. 늘 더 원하면서 돈은 절대 안 내려고 해요."]', '["You said yes already? That makes this harder.","Plenty of room? Derek would disagree.","Careful. He''s our client, and a good one."]', '["벌써 하겠다고 했어요? 그럼 더 어려워지는데요.","여유가 충분하다고요? 데릭은 생각이 다를걸요.","조심해요. 우리 고객이고, 좋은 고객이에요."]', NULL, 'Okay. It''s a fair ask, but the timing is tough.', '그렇군요. 요청 자체는 무리가 아닌데, 시기가 어렵네요.'),
  ('rt_1on1_pr_1', 2, NULL, 'The rollout to the remaining stores is what the contract promises. Derek thinks the report would take the team about two weeks.', '남은 매장에 확대 적용하는 건 계약에서 약속한 일입니다. 데릭은 보고서에 팀이 2주쯤 걸릴 거라고 봅니다.', 'So what do you want to tell him?', '그럼 그렉한테 뭐라고 할 거예요?', 'Propose a trade-off that protects what the contract promises.', '계약에서 약속한 걸 지키는 선에서 주고받을 안을 제안하세요.', '[]', 'Rollout first. Then the report right after, or he swaps it for something else.', '확대 적용이 먼저예요. 보고서는 그 직후에 하거나, 그렉이 다른 걸 빼고 바꿔 넣거나요.', '["We''ll do both. The team can work a couple of weekends, and Greg never has to know.","We''ll pause the rollout for two weeks and build the report first. He''s the client.","Flat out no. It wasn''t in the contract, so honestly, it''s not our problem at all."]', '["둘 다 하죠. 팀이 주말에 두어 번 나오면 되고, 그렉은 몰라도 돼요.","확대 적용을 2주 멈추고 보고서부터 만들죠. 고객이잖아요.","딱 잘라 안 된다고 해요. 계약에 없던 거니까 솔직히 우리 문제가 아니에요."]', '["Weekends? Not on my team.","The rollout is what we promised. Let''s not pause it.","Too blunt. We want him to keep coming back."]', '["주말이요? 우리 팀에선 안 돼요.","확대 적용은 우리가 약속한 거예요. 멈추지 말죠.","너무 직설적이에요. 계속 우리를 찾게 해야죠."]', NULL, 'Good. Giving him a choice is better than giving him a no.', '좋아요. 안 된다고 하는 것보다 선택지를 주는 게 나아요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_pr_1', 3, NULL, 'You know Greg well and would rather lead the call yourself. A written estimate from Derek would make your case stronger.', '그렉을 잘 아는 당신이 통화를 직접 이끄는 게 좋겠다고 생각합니다. 데릭의 견적이 글로 있으면 설득력이 커집니다.', 'Do you want me on the call with Greg?', '그렉과 통화할 때 제가 같이 들어갈까요?', 'Say you''ll lead it, and ask for the support you need.', '직접 이끌겠다고 하고, 필요한 지원을 요청하세요.', '[]', 'I''ll lead it. Could you get me Derek''s estimate in writing first?', '제가 이끌게요. 먼저 데릭의 견적을 글로 받아 주실 수 있어요?', '["Could you run it instead? Greg listens to you more than me anyway.","I''ll lead it. Skip the estimate. I''ll just give him a rough guess.","I''ll lead it, but let''s keep Derek out of it. He says no to everything."]', '["대신 진행해 주실래요? 어차피 그렉은 저보다 마야 말을 더 들어요.","제가 이끌게요. 견적은 됐어요. 대충 감으로 말할게요.","제가 이끌게요. 근데 데릭은 빼죠. 뭐든 안 된다고만 하니까요."]', '["Really? You know him much better than I do.","A guess? Greg likes real numbers.","That''s not fair to Derek. Let''s get his number."]', '["정말요? 그렉은 프리야가 저보다 훨씬 잘 알잖아요.","감으로요? 그렉은 정확한 숫자를 좋아해요.","데릭한테 공정하지 않아요. 데릭의 숫자를 받죠."]', NULL, 'I''ll ask him today. You''ll have it by tomorrow.', '오늘 부탁할게요. 내일까지는 받을 거예요.'),
  ('rt_1on1_pr_1', 4, NULL, 'The five-store pilot is going well. Store managers say they check the dashboard every morning.', '매장 다섯 곳의 시범 운영은 잘되고 있습니다. 매장 관리자들은 매일 아침 대시보드를 확인한다고 합니다.', 'How will you open the conversation?', '대화는 어떻게 시작할 거예요?', 'Describe how you''ll start: on a positive note, before the hard part.', '어떻게 시작할지 말하세요. 어려운 얘기 전에 긍정적으로요.', '[]', 'With good news: managers check it every morning. Then I''ll give him the options.', '좋은 소식으로요. 관리자들이 매일 아침 확인한대요. 그다음에 안을 줄게요.', '["With the bad news first. I''ll tell him it can''t happen and then let him react.","With good news: the rollout is already finished. Then I''ll give him the options.","With an apology. I''ll say sorry the team can''t keep up, and offer a discount."]', '["나쁜 소식부터요. 안 된다고 말하고 반응을 볼게요.","좋은 소식으로요. 확대 적용이 벌써 끝났다고요. 그다음에 안을 줄게요.","사과부터요. 팀이 못 따라가서 죄송하다고 하고 할인을 제안할게요."]', '["That might put him on the defensive.","Finished? We''re still rolling it out.","A discount? Let''s not give money away."]', '["그러면 방어적으로 나올 수 있어요.","끝났다고요? 아직 확대 중이잖아요.","할인이요? 돈을 그냥 내주진 말죠."]', NULL, 'Perfect. Start strong, then give him choices. Let me know if you have any questions.', '완벽해요. 힘 있게 시작하고, 선택지를 주세요. 궁금한 게 있으면 언제든 말해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_pr_2', 1, NULL, 'Your biweekly sync with Maya. For the backend role, two candidates passed Derek''s technical interview, and he was very impressed by one. The final round is with Maya, and it isn''t on her calendar yet.', '마야와의 격주 싱크입니다. 백엔드 자리에 두 명이 데릭의 기술 면접을 통과했고, 데릭은 그중 한 명에게 크게 감탄했습니다. 최종 면접은 마야가 보는데, 아직 그녀의 달력에 잡혀 있지 않습니다.', 'Where are we on the backend hire?', '백엔드 채용은 어디까지 왔어요?', 'Give the update, and ask for the one thing that''s holding it up.', '현황을 알리고, 일을 막고 있는 한 가지를 요청하세요.', '[]', 'Two passed Derek''s round, and he loved one. We just need a slot for your final.', '두 명이 데릭 면접을 통과했고, 한 명은 데릭이 아주 마음에 들어 해요. 마야의 최종 면접만 잡으면 돼요.', '["Two passed Derek''s round. I''ll make an offer myself today, so we don''t lose them.","Nobody has passed Derek''s round yet. We might need to post the job again soon.","Two passed Derek''s round. Linda was supposed to book the final with you already."]', '["두 명이 데릭 면접을 통과했어요. 놓치지 않게 오늘 제가 직접 제안할게요.","아직 데릭 면접을 통과한 사람이 없어요. 곧 공고를 다시 내야 할지도요.","두 명이 데릭 면접을 통과했어요. 최종 면접은 린다가 벌써 잡았어야 했는데요."]', '["An offer before the final round? Let''s not skip steps.","That''s not what Derek told me.","Let''s not worry about who. Let''s just book it now."]', '["최종 면접 전에 제안이요? 단계를 건너뛰진 말죠.","데릭한테 들은 얘기랑 다른데요.","누구 탓인지는 신경 쓰지 말고, 지금 잡죠."]', NULL, 'Fair. I''ll find two slots this week.', '맞아요. 이번 주에 두 자리 찾아볼게요.'),
  ('rt_1on1_pr_2', 2, NULL, 'Even with a quick offer, a new hire takes several weeks to start, and longer to get up to speed. Phase two, the mobile app, is next on the roadmap.', '빨리 제안하더라도 신입이 출근하기까지 몇 주, 손에 익기까지는 더 걸립니다. 로드맵에서 다음은 모바일 앱인 2단계입니다.', 'Even if they say yes, they won''t be up to speed for a while. How does that change phase two?', '수락하더라도 한동안은 제 속도가 안 날 거예요. 2단계는 어떻게 바뀌어요?', 'Suggest how to adjust the plan so phase two can still begin.', '2단계를 그래도 시작할 수 있게 계획을 어떻게 고칠지 제안하세요.', '[]', 'The current team starts on design, and the new hire takes backend work later.', '지금 팀으로 설계부터 시작하고, 백엔드 일은 신입이 나중에 맡으면 돼요.', '["It doesn''t change anything. The new hire can lead phase two from their first week.","We push phase two back six months to be safe. I''m sure Greg won''t mind the wait.","We start with design, and Derek covers all the backend work on top of the rollout."]', '["달라지는 건 없어요. 신입이 첫 주부터 2단계를 이끌면 돼요.","안전하게 2단계를 6개월 미루죠. 그렉도 기다리는 건 괜찮을 거예요.","설계부터 시작하고, 백엔드 일은 데릭이 확대 적용과 함께 전부 맡으면 돼요."]', '["From week one? That''s a lot to ask of anyone.","Six months? I''m pretty sure Greg would mind.","Derek''s plate is full already."]', '["첫 주부터요? 누구한테든 무리한 요구예요.","6개월이요? 그렉은 분명히 신경 쓸걸요.","데릭은 이미 일이 꽉 찼어요."]', NULL, 'That works. Let''s put it on the roadmap that way.', '좋아요. 로드맵에 그렇게 넣죠.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_pr_2', 3, NULL, 'Jun''s demo for the store managers went really well. One thing you''ve noticed: he says yes to every request you give him, then works late to finish.', '준이 매장 관리자들에게 한 시연은 아주 잘됐습니다. 눈에 띈 점이 하나 있습니다. 당신이 주는 요청은 다 받아들이고, 끝내려고 늦게까지 일합니다.', 'I''m gathering feedback on Jun for his review. You work with him every day. Anything?', '준의 평가를 위해 피드백을 모으고 있어요. 매일 같이 일하잖아요. 뭐 있어요?', 'Give balanced feedback: something specific he does well, and one area to grow.', '균형 잡힌 피드백을 주세요. 잘하는 구체적인 점 하나와 성장할 점 하나요.', '[]', 'His store demo was excellent. But he says yes to everything, then works late.', '매장 시연은 훌륭했어요. 그런데 뭐든 다 받아들이고 늦게까지 일해요.', '["He''s great. Honestly, nothing to improve. He never says no to anything I ask.","His store demo was okay, but honestly, he''s slow. He''s always there late.","His store demo was excellent. That''s all I''d rather say about a coworker."]', '["훌륭해요. 솔직히 고칠 게 없어요. 제가 뭘 부탁해도 절대 거절을 안 해요.","매장 시연은 괜찮았는데, 솔직히 느려요. 늘 늦게까지 남아 있어요.","매장 시연은 훌륭했어요. 동료에 대해선 거기까지만 말하고 싶어요."]', '["Never says no? That might be part of the problem.","Slow? I think he''s just taking on too much.","It''s okay to be honest here. It helps him grow."]', '["절대 거절을 안 한다고요? 그게 문제의 일부일 수도 있어요.","느리다고요? 그냥 일을 너무 많이 떠안는 것 같은데요.","여기선 솔직해도 돼요. 그래야 준이 성장해요."]', NULL, 'That matches what I''ve seen. I''ll work with him on pushing back.', '제가 본 것과 같네요. 거절하는 법을 같이 연습해 볼게요.'),
  ('rt_1on1_pr_2', 4, NULL, 'The team''s capacity numbers usually reach you after you''ve already shared a rough plan with Greg, so you sometimes have to walk things back.', '팀의 가용 인력 수치는 보통 당신이 그렉에게 대략적인 계획을 공유한 뒤에야 옵니다. 그래서 가끔 말을 거둬들여야 합니다.', 'And what''s one thing I could do to make your job easier?', '그리고 프리야 일이 수월해지려면 제가 뭘 하면 될까요?', 'Give her specific feedback that would help your planning.', '계획 세우는 데 도움이 될 구체적인 피드백을 주세요.', '[]', 'Could I get capacity numbers before I share plans with Greg, not after?', '그렉에게 계획을 공유한 뒤가 아니라, 그 전에 가용 인력 수치를 받을 수 있을까요?', '["Nothing at all. You''re perfect. I wouldn''t change anything about how you run the team.","Could you handle Greg from now on? Then I wouldn''t need the capacity numbers at all.","Honestly, your numbers always show up late, and it makes me look bad in front of Greg."]', '["하나도 없어요. 완벽하세요. 팀 운영 방식에서 바꿀 게 하나도 없어요.","앞으로 그렉은 마야가 맡아 주실래요? 그러면 가용 인력 수치가 아예 필요 없어요.","솔직히 마야 숫자는 늘 늦게 와서, 그렉 앞에서 제가 난처해져요."]', '["Nobody''s perfect. Think about it.","Greg is your client relationship, Priya.","That''s fair, but it came out a little sharp."]', '["완벽한 사람은 없어요. 생각해 봐요.","그렉과의 관계는 프리야 몫이에요.","맞는 말이지만, 좀 날카롭게 들렸어요."]', NULL, 'Good point. I''ll send you capacity at the start of every planning cycle. Let me know if you have any questions.', '좋은 지적이에요. 계획 주기를 시작할 때마다 가용 인력을 보내 줄게요. 궁금한 게 있으면 언제든 말해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_pr_3', 1, NULL, 'Your biweekly sync. You''ve been answering Greg''s emails around midnight, and you''re running on coffee. Maya noticed the timestamps.', '격주 싱크입니다. 요즘 자정 무렵에 그렉의 메일에 답하고 있고, 커피로 버티고 있습니다. 마야가 보낸 시각을 알아챘습니다.', 'Priya, I saw emails from you at midnight. How are you doing, really?', '프리야, 자정에 보낸 메일을 봤어요. 정말 괜찮아요?', 'Admit how you''re actually doing.', '실제로 어떤 상태인지 인정하세요.', '[]', 'Honestly, I''m worn out. I keep answering Greg at night, and it''s catching up with me.', '솔직히 지쳤어요. 밤에 계속 그렉한테 답하다 보니 몸이 못 버티네요.', '["Great, actually. Midnight is my most productive time. I honestly love working then.","Worn out. Greg is impossible. He expects answers at midnight, every single night.","Sorry about that. I''ll schedule my emails to go out in the morning, so you won''t see."]', '["좋아요, 사실. 자정이 제일 능률이 오르는 시간이에요. 솔직히 그때 일하는 게 좋아요.","지쳤어요. 그렉은 답이 없어요. 매일 밤 자정에 답장을 기대해요.","죄송해요. 메일은 아침에 나가게 예약해 둘게요. 그럼 안 보이실 거예요."]', '["Really? You look exhausted, Priya.","Every night? Has he actually asked for that?","Hiding the timestamps isn''t the point."]', '["정말요? 많이 지쳐 보여요, 프리야.","매일 밤이요? 그렉이 정말 그렇게 요구했어요?","시각을 숨기는 게 중요한 게 아니에요."]', NULL, 'Thanks for being honest. Let''s fix this before it gets worse.', '솔직하게 말해 줘서 고마워요. 더 나빠지기 전에 바로잡죠.'),
  ('rt_1on1_pr_3', 2, NULL, 'You have PTO you haven''t used. Derek knows the dashboard inside out and has met Greg, and Maya can handle anything urgent.', '쓰지 않은 유급 휴가가 있습니다. 데릭은 대시보드를 속속들이 알고 그렉도 만나 봤으며, 급한 일은 마야가 처리할 수 있습니다.', 'I want you to take a few days off. Who could cover the client while you''re out?', '며칠 쉬었으면 해요. 없는 동안 고객은 누가 맡을 수 있을까요?', 'Propose a coverage plan using the people who know the work.', '일을 아는 사람들로 대신 맡을 계획을 제안하세요.', '[]', 'Derek knows the dashboard and has met Greg. You could take anything urgent.', '데릭이 대시보드를 알고 그렉도 만나 봤어요. 급한 일이 생기면 마야가 나서 주시고요.', '["Nobody, really. I''ll bring my laptop and check email once or twice a day.","Jun could do it. He''s new, but handling Greg alone would be good practice.","Derek knows the dashboard, but he''s never met Greg, so maybe I shouldn''t go."]', '["딱히 없어요. 노트북 들고 가서 하루에 한두 번 메일을 확인할게요.","준이 하면 돼요. 신입이지만 그렉을 혼자 상대해 보는 게 좋은 연습이 될 거예요.","데릭이 대시보드는 알지만 그렉을 만난 적이 없어서, 안 가는 게 나을지도요."]', '["That''s not time off, Priya.","Alone with Greg? That''s a lot for Jun.","He''s met Greg, hasn''t he? I''m sure of it."]', '["그건 쉬는 게 아니에요, 프리야.","혼자 그렉을요? 준한테는 벅차요.","데릭은 그렉을 만났잖아요? 확실해요."]', NULL, 'Good. Ask Derek, and I''ll be the backup.', '좋아요. 데릭한테 부탁하고, 백업은 제가 할게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_1on1_pr_3', 3, NULL, 'Greg works normal office hours. Nothing he has sent at night has been urgent so far.', '그렉은 보통 근무 시간에 일합니다. 그가 밤에 보낸 메일 중 급한 건 지금까지 하나도 없었습니다.', 'And once you''re back? How do we keep this from happening again?', '그리고 돌아와서는요? 다시 이렇게 되지 않으려면 어떻게 할까요?', 'Suggest a reasonable limit on after-hours email.', '퇴근 후 메일에 대해 합리적인 선을 제안하세요.', '[]', 'I''ll stop answering after seven. Nothing he''s sent at night has been urgent so far.', '일곱 시 이후엔 답하지 않을게요. 그렉이 밤에 보낸 것 중 급한 건 없었으니까요.', '["I''ll tell Greg he can only email us during business hours, or we stop answering.","I''ll keep answering at night, but only for an hour. That seems like a fair deal.","I''ll stop answering after seven, even if the dashboard goes down for every store."]', '["그렉한테 근무 시간에만 메일하라고, 아니면 답 안 한다고 말할게요.","밤에도 계속 답하되, 한 시간만 할게요. 그 정도면 적당한 것 같아요.","일곱 시 이후엔 답 안 할게요. 모든 매장 대시보드가 멈춰도요."]', '["Let''s not lay down rules for the client.","An hour every night still adds up.","Real emergencies are different. Those still need someone."]', '["고객한테 규칙을 정해 주진 말죠.","매일 밤 한 시간도 쌓이면 커요.","진짜 비상 상황은 달라요. 그땐 누군가는 있어야 해요."]', NULL, 'That''s healthy. Real emergencies go to whoever''s on call anyway.', '건강한 선이네요. 진짜 비상 상황은 어차피 온콜 담당자한테 가요.'),
  ('rt_1on1_pr_3', 4, NULL, 'When the pilot stores'' tablets lost Wi-Fi, Sam Reyes from IT stayed late to fix them, so the managers could open the dashboard the next morning.', '시범 매장의 태블릿이 와이파이에 연결되지 않았을 때, IT팀 샘 레예스가 늦게까지 남아 고쳐서 다음 날 아침 관리자들이 대시보드를 열 수 있었습니다.', 'Before you go. Anything good from the team I should know about?', '가기 전에요. 제가 알아야 할 좋은 소식 있어요?', 'Make sure a colleague outside the team gets credit for helping.', '팀 밖의 동료가 도와준 공을 인정받게 하세요.', '[]', 'Sam from IT stayed late fixing the tablets'' Wi-Fi. He kept the pilot going.', 'IT팀 샘이 늦게까지 남아서 태블릿 와이파이를 고쳤어요. 덕분에 시범 운영이 안 멈췄어요.', '["Sam from IT fixed the store tablets'' Wi-Fi, but only after I reminded him three times.","Derek stayed late to fix the store tablets'' Wi-Fi. He saved the pilot that night.","Not really. Everyone just did their jobs this time. Nothing really worth mentioning."]', '["IT팀 샘이 매장 태블릿 와이파이를 고치긴 했는데, 제가 세 번이나 말한 뒤에요.","데릭이 늦게까지 남아서 매장 태블릿 와이파이를 고쳤어요. 그날 밤 시범 운영을 살렸어요.","딱히요. 이번엔 다들 자기 일을 했을 뿐이에요. 특별히 말할 건 없어요."]', '["Three times? I heard he jumped right on it.","Derek? I thought Sam handled the tablets.","I bet somebody went the extra mile."]', '["세 번이요? 바로 달려들었다고 들었는데요.","데릭이요? 태블릿은 샘이 맡은 줄 알았는데요.","분명 누군가는 더 애썼을 텐데요."]', NULL, 'I''ll email his manager and copy you. Now go plan those days off. Let me know if you have any questions.', '샘의 매니저에게 메일 보내고 프리야도 참조로 넣을게요. 이제 가서 휴가 계획 세워요. 궁금한 게 있으면 언제든 말해요.');
REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('rt_planning_dev_1', 'Sprint planning: what fits', '스프린트 계획: 들어갈 만큼만', 'office_meeting', 'priya', 16, NULL, '13:15', '14:15', NULL, 'Every other Monday, Priya plans the next two weeks with the team. Estimate a story, speak up when the sprint gets too full, and flag a risk before you commit.', '격주 월요일마다 프리야가 팀과 다음 2주를 계획합니다. 스토리를 추정하고, 스프린트가 너무 차면 말하고, 약속하기 전에 위험 요소를 알리세요.', 0, 0, 2200, 'meeting,planning,routine', 'jun,derek'),
  ('rt_planning_dev_2', 'Splitting the big ticket', '큰 티켓 쪼개기', 'office_meeting', 'priya', 16, NULL, '13:15', '14:15', NULL, 'Priya brings a huge, vague ticket to sprint planning. Find out what done means, suggest splitting it, and be honest about how much you can take on.', '프리야가 크고 모호한 티켓을 스프린트 계획 회의에 가져왔습니다. 완료의 기준이 뭔지 알아내고, 쪼개자고 제안하고, 당신이 얼마나 맡을 수 있는지 솔직하게 말하세요.', 0, 0, 2210, 'meeting,planning,routine', 'jun,derek'),
  ('rt_planning_pr_1', 'Setting the sprint goal', '스프린트 목표 정하기', 'office_meeting', 'derek', 16, NULL, '13:15', '14:15', NULL, 'You run sprint planning. Give the team one clear goal, put the backlog in the right order, and keep the sprint to what the team can finish.', '스프린트 계획 회의는 당신이 진행합니다. 팀에 분명한 목표 하나를 주고, 백로그 순서를 바로잡고, 스프린트를 팀이 끝낼 수 있는 만큼으로 지키세요.', 0, 0, 2220, 'meeting,planning,routine', 'priya'),
  ('rt_planning_pr_2', 'A surprise request at planning', '계획 회의에 날아든 요청', 'office_meeting', 'derek', 16, NULL, '13:15', '14:15', NULL, 'A new request from the client lands just as planning starts. Find out how big it is, make room by trading scope instead of adding it, and wrap up with a clear commitment.', '계획 회의가 시작되자마자 고객의 새 요청이 들어옵니다. 얼마나 큰지 알아보고, 더하는 대신 범위를 맞바꿔 자리를 만들고, 분명한 약속으로 마무리하세요.', 0, 0, 2230, 'meeting,planning,routine', 'priya'),
  ('rt_retro_1', 'Retro: the checklist and the reviews', '회고: 체크리스트와 코드 리뷰', 'office_meeting', 'maya', 16, NULL, '14:45', '15:45', NULL, 'Every other Friday, Maya runs the sprint retro. Name what went well, raise a problem without blaming anyone, and turn it into an action item you own.', '격주 금요일마다 마야가 스프린트 회고를 진행합니다. 잘된 것을 말하고, 누구도 탓하지 않고 문제를 꺼내고, 그것을 당신이 맡는 실행 항목으로 바꾸세요.', 0, 0, 2300, 'meeting,retro,routine', 'all'),
  ('rt_retro_2', 'Retro: shout-outs and late-night messages', '회고: 감사 인사와 한밤의 메시지', 'office_meeting', 'maya', 16, NULL, '14:45', '15:45', NULL, 'Sam from IT joins this retro. Give him a specific thank-you, take his feedback well, and pick up the small action item that comes out of it.', '이번 회고에는 IT의 샘이 함께합니다. 그에게 구체적으로 고맙다고 하고, 그의 의견을 잘 받아들이고, 거기서 나온 작은 실행 항목을 맡으세요.', 0, 0, 2310, 'meeting,retro,routine', 'all'),
  ('rt_retro_3', 'Retro after a rough sprint', '힘든 스프린트 뒤의 회고', 'office_meeting', 'maya', 16, NULL, '14:45', '15:45', NULL, 'A hard sprint: two stories didn''t make it. Be honest about how it felt, describe what went wrong without blaming anyone, and give Tom useful feedback about the room.', '힘든 스프린트였습니다. 스토리 두 개를 끝내지 못했어요. 어땠는지 솔직하게 말하고, 누구도 탓하지 않고 무엇이 잘못됐는지 설명하고, 톰에게 회의실에 대해 쓸모 있는 의견을 주세요.', 0, 0, 2320, 'meeting,retro,routine', 'all'),
  ('rt_allhands_1', 'All-hands: news and a profile check', '전사 회의: 회사 소식과 인사 정보 점검', 'office_meeting', 'maya', 16, NULL, '15:45', '16:45', NULL, 'The monthly company all-hands. Ask Maya a good question about the dashboard, be honest with Linda about your HR details, and make sure you understand Tom''s kitchen rule.', '매달 열리는 전사 회의입니다. 마야에게 대시보드에 대해 좋은 질문을 하고, 인사 정보에 대해 린다에게 솔직하게 말하고, 톰이 말하는 탕비실 규칙을 제대로 알아들으세요.', 0, 0, 2400, 'meeting,all-hands,routine', 'all'),
  ('rt_allhands_2', 'All-hands: launch news and the holiday party', '전사 회의: 출시 소식과 연말 파티', 'office_meeting', 'maya', 16, NULL, '15:45', '16:45', NULL, 'The monthly all-hands brings good news. Say a few words that credit the team, plan around Sam''s laptop update, and ask Linda a fresh question about the holiday party.', '매달 열리는 전사 회의에 좋은 소식이 있습니다. 팀에 공을 돌리는 말을 몇 마디 하고, 샘의 노트북 업데이트에 맞춰 계획을 세우고, 린다에게 연말 파티에 대해 새로운 질문을 하세요.', 0, 0, 2410, 'meeting,all-hands,routine', 'all');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_planning_dev_1', 1, NULL, 'Monday afternoon, sprint planning. Priya shares the board on the big screen. First story: store managers want to export the weekly sales table as a CSV file. You built that table last sprint, so the work is small: one button and a download.', '월요일 오후, 스프린트 계획 회의입니다. 프리야가 큰 화면에 보드를 띄웁니다. 첫 스토리는 매장 매니저들이 주간 매출 표를 CSV 파일로 내려받고 싶어 한다는 것입니다. 그 표는 지난 스프린트에 당신이 만들었으니 일은 작습니다. 버튼 하나와 다운로드뿐이에요.', 'First up, the CSV export. How many points do we think?', '첫 번째는 CSV 내보내기예요. 몇 포인트쯤 될까요?', 'Give your estimate, and say why you think it is small.', '추정치를 말하고, 왜 작은 일이라고 보는지 설명하세요.', '[]', 'I''d say two points. The table already exists, so it''s mostly one button.', '2포인트요. 표는 이미 있으니까 버튼 하나가 대부분이에요.', '["I''d say thirteen points. We''ve never built that table, so it''s a lot of work.","Whatever you think, Priya. Just put down any number, and we''ll see.","I''d say two days. I can finish it by Wednesday if nobody bugs me."]', '["13포인트요. 그 표를 만든 적이 없으니까 일이 많아요.","프리야 생각대로 해요. 아무 숫자나 적어 두고 두고 봐요.","이틀이요. 아무도 안 건드리면 수요일까지 끝낼 수 있어요."]', '["Never built it? You shipped that table last sprint.","Any number isn''t an estimate. What''s your gut?","We estimate in points, not days. And nobody will bug you, promise."]', '["만든 적이 없다고요? 지난 스프린트에 그 표를 내놨잖아요.","아무 숫자는 추정이 아니에요. 감으로는 어때요?","우린 날짜가 아니라 포인트로 추정해요. 그리고 아무도 안 건드릴게요, 약속해요."]', NULL, 'Two points it is. Next one.', '그럼 2포인트로 해요. 다음 거요.'),
  ('rt_planning_dev_1', 2, NULL, 'Priya keeps pulling stories into the sprint. Lately the team finishes about thirty points per sprint. The sprint now holds forty-five, including a login redesign nobody has looked at yet.', '프리야가 스프린트에 스토리를 계속 끌어옵니다. 요즘 팀은 스프린트마다 30포인트쯤 끝냅니다. 지금 스프린트에는 45포인트가 들어 있고, 아직 아무도 들여다보지 않은 로그인 화면 개편도 있습니다.', 'And let''s pull in the login redesign too. Greg would love to see that.', '로그인 화면 개편도 넣어요. 그렉이 보면 좋아할 거예요.', 'You think this is more than the team can finish. Say so kindly, with the numbers.', '팀이 끝낼 수 있는 양보다 많다고 생각합니다. 숫자를 들어 정중하게 말하세요.', '[]', 'That puts us at forty-five. We usually finish about thirty. What should drop?', '그러면 45가 돼요. 우린 보통 30쯤 끝내요. 뭘 빼야 할까요?', '["Sure, add it. We can always work late at the end of the sprint to finish.","That puts us at forty-five. We usually finish about fifty, so we''re fine.","No way. You do this every sprint, Priya. You always pile on too much."]', '["좋아요, 넣어요. 스프린트 막판에 야근하면 끝낼 수 있어요.","그러면 45가 돼요. 우린 보통 50쯤 끝내니까 괜찮아요.","말도 안 돼요. 프리야는 매번 이래요. 늘 너무 많이 넣어요."]', '["Late nights aren''t a plan. I''d rather be honest now.","Fifty? Our last few sprints were closer to thirty.","Whoa. Okay. That felt a little personal."]', '["야근은 계획이 아니에요. 지금 솔직한 게 나아요.","50이요? 최근 스프린트는 30에 가까웠어요.","와. 알겠어요. 좀 저를 겨냥한 말 같네요."]', NULL, 'Fair. The login redesign stays in the backlog. That gets us to thirty-one.', '맞아요. 로그인 개편은 백로그에 남겨 둘게요. 그러면 31이에요.'),
  ('rt_planning_dev_1', 3, 'maya', 'Maya sits in on planning today. One story left in the sprint, store alerts, needs a new API from Summit Retail''s team, and they haven''t delivered it yet.', '오늘은 마야도 계획 회의에 들어와 있습니다. 스프린트에 남은 스토리 하나인 매장 알림은 서밋 리테일 팀의 새 API가 필요한데, 그쪽에서 아직 주지 않았습니다.', 'Before we commit, any risks we should know about?', '확정하기 전에, 우리가 알아야 할 위험 요소가 있나요?', 'Point out what could block you, and suggest a way to follow up.', '당신의 일을 막을 수 있는 것을 짚고, 어떻게 챙길지 제안하세요.', '[]', 'The store alerts need Summit''s new API, and we don''t have it. Can someone check with them?', '매장 알림에 서밋의 새 API가 필요한데 아직 없어요. 누가 그쪽에 확인해 줄 수 있을까요?', '["Nope, no risks. Everything this sprint is in our own hands, so we''re fine.","The store alerts need Summit''s new API. If it''s late, that''s their fault, not ours.","The login redesign worries me. It''s big, and nobody has even looked at it."]', '["아뇨, 위험 요소 없어요. 이번 스프린트는 다 우리 손에 달렸으니 괜찮아요.","매장 알림에 서밋의 새 API가 필요해요. 늦으면 그쪽 잘못이지 우리 잘못은 아니에요.","로그인 개편이 걱정돼요. 크고, 아무도 들여다보지 않았어요."]', '["No risks? What about the alerts story?","Maybe, but blame won''t get us the API. What can we do?","The login redesign is out of this sprint, remember?"]', '["위험 요소가 없다고요? 알림 스토리는요?","그럴 수도 있지만, 탓해서 API가 오진 않아요. 우리가 뭘 할 수 있죠?","로그인 개편은 이번 스프린트에서 뺐잖아요, 기억나요?"]', NULL, 'Good catch. Priya will ping their team today. Then we''re committed.', '잘 짚었어요. 프리야가 오늘 그쪽 팀에 연락할 거예요. 그러면 확정이에요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_planning_dev_2', 1, NULL, 'Sprint planning. Priya''s top story is "Inventory page for all stores." It has a title and a mockup, but no acceptance criteria. Nobody knows what "done" means yet.', '스프린트 계획 회의입니다. 프리야의 맨 위 스토리는 "전 매장 재고 페이지"입니다. 제목과 목업은 있지만 인수 조건이 없습니다. "완료"가 무엇인지 아직 아무도 모릅니다.', 'The inventory page. It''s the big one Greg keeps asking about. Can we estimate it?', '재고 페이지요. 그렉이 계속 묻는 큰 거예요. 추정할 수 있을까요?', 'You can''t size it yet. Explain what''s missing before anyone can put a number on it.', '아직은 크기를 잴 수 없습니다. 숫자를 매기기 전에 무엇이 빠졌는지 설명하세요.', '[]', 'Not yet. There are no acceptance criteria. What exactly counts as done here?', '아직은요. 인수 조건이 없어요. 여기선 정확히 뭐가 완료인가요?', '["Sure, let''s call it five points. It''s just one page. How hard can it be?","Not yet. There''s no mockup, so we don''t know what the page looks like.","Not yet. Honestly, whoever wrote this ticket didn''t think it through."]', '["좋아요, 5포인트로 해요. 페이지 하나잖아요. 얼마나 어렵겠어요?","아직은요. 목업이 없으니까 페이지가 어떻게 생겼는지 몰라요.","아직은요. 솔직히 이 티켓 쓴 사람이 생각을 덜 했네요."]', '["Famous last words. One page can hide a lot of work.","There''s a mockup, though. It''s attached right there.","Ouch. I wrote it. But okay, it is a little thin."]', '["다들 그렇게 말하죠. 페이지 하나에 일이 많이 숨어 있을 수 있어요.","목업은 있어요. 바로 거기 첨부돼 있어요.","아야. 제가 썼어요. 그래도 좀 부실한 건 맞네요."]', NULL, 'Fair. Done means managers see stock levels for every store, updated every hour.', '맞아요. 완료는 매니저들이 모든 매장의 재고를 보는 거예요. 매시간 갱신되고요.'),
  ('rt_planning_dev_2', 2, NULL, 'Stock for every store, updated hourly. That''s three parts: a new data feed, the page itself, and the hourly refresh. All together, it''s far too big for one sprint.', '모든 매장의 재고, 매시간 갱신. 세 부분입니다. 새 데이터 피드, 페이지 자체, 매시간 갱신. 한꺼번에 하면 한 스프린트에 넣기엔 너무 큽니다.', 'So how do we fit this in? Greg wants it soon.', '그럼 이걸 어떻게 넣죠? 그렉은 빨리 원해요.', 'Suggest a way to deliver it in smaller pieces, one at a time.', '더 작은 조각으로 하나씩 내놓을 방법을 제안하세요.', '[]', 'Let''s split it in three: the data feed first, then the page, then the refresh.', '셋으로 나눠요. 데이터 피드 먼저, 그다음 페이지, 그다음 갱신이요.', '["Let''s just do the whole thing this sprint. If we all push hard, we''ll make it.","Let''s split it in two: the web page now, and the mobile app version later.","Tell Greg it can''t be done. It''s way too big, and we''re busy already."]', '["그냥 이번 스프린트에 다 해요. 다 같이 밀어붙이면 돼요.","둘로 나눠요. 웹 페이지는 지금, 모바일 앱 버전은 나중에요.","그렉한테 안 된다고 해요. 너무 크고 우린 이미 바빠요."]', '["Push hard? That''s how people burn out.","The app is a separate project. I mean this page.","Let''s not refuse a client when we really mean not all at once."]', '["밀어붙인다고요? 그러다 다들 지쳐요.","앱은 별개 프로젝트예요. 저는 이 페이지 얘기예요.","한꺼번에는 안 된다는 걸 안 된다고 고객한테 말하진 말아요."]', NULL, 'I like it. The data feed goes in this sprint. The rest comes next.', '좋아요. 데이터 피드는 이번 스프린트에 넣어요. 나머지는 다음에요.'),
  ('rt_planning_dev_2', 3, NULL, 'The data feed is five points. You already have eight points this sprint, and you''re interviewing backend candidates on two afternoons.', '데이터 피드는 5포인트입니다. 당신은 이번 스프린트에 이미 8포인트를 맡았고, 이틀 오후는 백엔드 지원자 면접이 있습니다.', 'Who wants to take the data feed?', '데이터 피드는 누가 맡을래요?', 'Be honest about your own load before you volunteer.', '자원하기 전에 당신이 맡은 양을 솔직하게 말하세요.', '[]', 'I''m at eight points, plus two interview afternoons. I could pair on it, though.', '저는 8포인트에 면접 오후가 이틀이에요. 그래도 같이 짝으로 할 순 있어요.', '["I''ll take it. I''ve got almost nothing on my plate this sprint anyway.","I''ll take it, plus anything else, and I''ll still do all the interviews.","Not me. Interviews eat my whole week. Someone else should do them."]', '["제가 할게요. 어차피 이번 스프린트엔 맡은 게 거의 없어요.","제가 할게요. 다른 것도 다 주세요. 면접도 다 할게요.","전 빼 주세요. 면접이 일주일을 다 잡아먹어요. 다른 사람이 해야 해요."]', '["Nothing? I count eight points with your name on them.","That''s a lot. I don''t want you working weekends.","We really need this hire. Those interviews matter."]', '["거의 없다고요? 당신 이름이 붙은 게 8포인트인데요.","그건 너무 많아요. 주말에 일하는 건 싫어요.","이번 채용은 정말 중요해요. 그 면접도 중요해요."]', NULL, 'Thanks for being straight with me. I''ll find who has room, and you can pair.', '솔직하게 말해 줘서 고마워요. 여유 있는 사람을 찾을 테니 짝으로 해 줘요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_planning_pr_1', 1, NULL, 'Monday afternoon, sprint planning. The team is in the meeting room, and the board is on the screen. Summit Retail''s store managers keep saying the same thing: the dashboard is slow to load in the mornings. Every other request can wait.', '월요일 오후, 스프린트 계획 회의입니다. 팀이 회의실에 모였고 화면에 보드가 떠 있습니다. 서밋 리테일 매장 매니저들은 같은 말을 계속합니다. 아침마다 대시보드가 느리게 뜬다고요. 다른 요청은 다 기다릴 수 있습니다.', 'Okay, we''re all here. What''s the goal for this sprint?', '자, 다 모였어요. 이번 스프린트 목표는 뭐예요?', 'Give the team a single, clear goal based on what the client needs most.', '고객에게 가장 필요한 것을 바탕으로 팀에 분명한 목표 하나를 주세요.', '[]', 'One goal: make the dashboard load fast in the mornings. Everything else comes second.', '목표는 하나예요. 아침에 대시보드가 빨리 뜨게 하는 것. 나머지는 그다음이에요.', '["Let''s try to do a bit of everything this sprint. Every request matters equally.","One goal: start building the mobile app. The dashboard can wait a few weeks.","One goal: make it load fast. Honestly, it''s embarrassing it was ever that slow."]', '["이번 스프린트엔 조금씩 다 해 봐요. 모든 요청이 똑같이 중요해요.","목표는 하나예요. 모바일 앱 만들기 시작. 대시보드는 몇 주 기다려도 돼요.","목표는 하나예요. 빨리 뜨게 하기. 솔직히 그렇게 느렸다니 창피해요."]', '["A bit of everything usually means nothing gets finished.","The app''s not until January. The stores are complaining now.","Hey, we built it on a tight deadline. Let''s not go there."]', '["조금씩 다 하면 보통 아무것도 안 끝나요.","앱은 1월이에요. 매장들은 지금 불만이고요.","이봐요, 촉박한 일정에 만든 거예요. 그 얘긴 하지 말죠."]', NULL, 'Clear enough. Speed first. I''ll write it at the top of the board.', '분명하네요. 속도가 먼저. 보드 맨 위에 적을게요.'),
  ('rt_planning_pr_1', 2, 'jun', 'Jun points at the backlog. Right at the top sits a new color theme for the dashboard. Greg mentioned it once, in passing. The loading fix is below it.', '준이 백로그를 가리킵니다. 맨 위에 대시보드 새 색상 테마가 있습니다. 그렉이 지나가듯 한 번 말한 것입니다. 로딩 개선은 그 아래에 있습니다.', 'Should I start with the color theme? It''s right at the top.', '색상 테마부터 할까요? 맨 위에 있어서요.', 'Put the work in an order that matches the goal you just set, and explain why.', '방금 정한 목표에 맞게 일의 순서를 정하고, 이유를 말하세요.', '[]', 'Let''s move the loading fix above it. Speed is our goal. The colors can wait.', '로딩 개선을 그 위로 올려요. 우리 목표는 속도예요. 색상은 기다려도 돼요.', '["Yes, start with the colors. Greg mentioned them, so they must be urgent.","Let''s just delete the color theme. Greg will never notice it''s gone.","Start wherever you like. The order of the backlog doesn''t really matter."]', '["네, 색상부터 해요. 그렉이 말했으니 급한 게 분명해요.","색상 테마는 그냥 지워요. 그렉은 없어진 줄도 모를 거예요.","하고 싶은 데서 시작해요. 백로그 순서는 별로 중요하지 않아요."]', '["Urgent? I think he only brought it up once.","Delete it? What if he asks about it later?","Then why do we keep the backlog in order?"]', '["급하다고요? 한 번 말한 것뿐인 것 같은데요.","지운다고요? 나중에 물어보면요?","그럼 백로그 순서는 왜 정해 두는 거예요?"]', NULL, 'Got it. I''ll grab the loading fix first.', '알겠어요. 로딩 개선부터 잡을게요.'),
  ('rt_planning_pr_1', 3, NULL, 'The sprint now holds thirty-four points. The team usually finishes about thirty, and Derek will be out on Friday. Protecting the team from overload is part of your job.', '스프린트에 지금 34포인트가 들어 있습니다. 팀은 보통 30쯤 끝내고, 데릭은 금요일에 쉽니다. 팀이 과부하에 걸리지 않게 지키는 것도 당신의 일입니다.', 'Thirty-four points. Do we go for it?', '34포인트예요. 그대로 갈까요?', 'Keep the sprint realistic, and decide what comes out.', '스프린트를 현실적으로 맞추고, 무엇을 뺄지 정하세요.', '[]', 'No. With you out Friday, let''s aim for twenty-eight. The color theme comes out.', '아뇨. 금요일에 쉬니까 28로 맞춰요. 색상 테마는 빼요.', '["Yes, let''s go for it. Thirty-four is close to thirty, and we can stretch.","No. With you out Friday, let''s aim for twenty-eight. The loading fix comes out.","Yes. But if we don''t finish, I''m the one who explains it to Maya, so please finish."]', '["네, 그대로 가요. 34는 30이랑 비슷하고, 좀 무리하면 돼요.","아뇨. 금요일에 쉬니까 28로 맞춰요. 로딩 개선은 빼요.","네. 근데 못 끝내면 마야한테 설명하는 건 저니까, 꼭 끝내 줘요."]', '["Stretch with one person out? That''s a lot.","The loading fix is the whole goal, though.","No pressure, huh? That''s not a great way to start."]', '["한 명 빠지는데 무리한다고요? 그건 많아요.","로딩 개선이 목표 전부잖아요.","부담 주는 거 아니죠? 시작부터 그건 좀 아니에요."]', NULL, 'Twenty-eight it is. That feels doable. Nice planning.', '28로 하죠. 할 만하겠어요. 계획 잘했어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_planning_pr_2', 1, NULL, 'Planning has just started. Derek pulls up an email from Greg Whitfield: Summit Retail wants a holiday sales report for all store managers by the end of this sprint. The sprint is already full at thirty points.', '계획 회의가 막 시작됐습니다. 데릭이 그렉 휫필드의 메일을 띄웁니다. 서밋 리테일이 이번 스프린트가 끝날 때까지 모든 매장 매니저용 연말 매출 보고서를 원합니다. 스프린트는 이미 30포인트로 꽉 찼습니다.', 'Greg sent this an hour ago. A holiday sales report, by the end of the sprint.', '그렉이 한 시간 전에 보냈어요. 연말 매출 보고서요, 스프린트 끝까지.', 'Before deciding anything, find out how big the request really is.', '무엇이든 정하기 전에, 요청이 실제로 얼마나 큰지 알아보세요.', '[]', 'Okay. Before I answer Greg, how big is it? Can you give me a rough size?', '알겠어요. 그렉한테 답하기 전에, 얼마나 커요? 대략 크기 좀 알려 줄래요?', '["Fine, add it. Greg''s the client, so whatever he asks for goes in the sprint.","Ignore it for now. If it''s really important, Greg will send another email.","Okay. Let''s tell Greg yes right away, and figure out the size later."]', '["좋아요, 넣어요. 그렉이 고객이니까 요청하는 건 다 스프린트에 들어가요.","일단 무시해요. 정말 중요하면 그렉이 메일을 또 보낼 거예요.","알겠어요. 그렉한테 바로 된다고 하고, 크기는 나중에 알아봐요."]', '["On top of thirty points? Something would break.","Ignore the client? That won''t end well.","Yes before we know the size? That''s risky."]', '["30포인트 위에요? 뭔가 터질 거예요.","고객을 무시한다고요? 끝이 안 좋을 거예요.","크기도 모르고 된다고요? 위험해요."]', NULL, 'About eight points. The data''s already there. It''s mostly the layout.', '8포인트쯤이요. 데이터는 이미 있어요. 대부분 화면 배치예요.'),
  ('rt_planning_pr_2', 2, 'maya', 'Eight points, and the sprint is full, so something has to give. The lowest story on the board is an admin settings page no store manager has asked for. A security patch also has to ship this sprint. Maya leans in.', '8포인트인데 스프린트가 꽉 찼으니 뭔가는 빠져야 합니다. 보드에서 가장 낮은 스토리는 어느 매장 매니저도 요청하지 않은 관리자 설정 페이지입니다. 보안 패치도 이번 스프린트에 꼭 나가야 합니다. 마야가 몸을 기울입니다.', 'So what''s the plan? We can''t add eight points to a full sprint.', '그래서 계획은요? 꽉 찬 스프린트에 8포인트를 더할 순 없어요.', 'Propose a trade that keeps the sprint the same size.', '스프린트 크기를 그대로 두는 맞교환을 제안하세요.', '[]', 'We swap. The report goes in, and the admin settings page moves to next sprint.', '맞바꿔요. 보고서를 넣고, 관리자 설정 페이지는 다음 스프린트로 옮겨요.', '["We add it anyway. I''ll ask everyone to put in a few extra hours this week.","We swap. The report goes in, and the security patch waits until next sprint.","We tell Greg no. Holiday reports were never part of the deal anyway."]', '["그냥 넣어요. 이번 주에 다들 몇 시간씩 더 일해 달라고 할게요.","맞바꿔요. 보고서를 넣고, 보안 패치는 다음 스프린트까지 기다려요.","그렉한테 안 된다고 해요. 연말 보고서는 원래 계약에 없었어요."]', '["Extra hours? Let''s not make that a habit.","The patch can''t wait. Pick something else.","Let''s not refuse a client over eight points we can make room for."]', '["추가 근무요? 그게 습관이 되면 안 돼요.","패치는 못 기다려요. 다른 걸 골라요.","자리를 만들 수 있는 8포인트 때문에 고객을 거절하진 말아요."]', NULL, 'Good trade. Let Greg know what moved, so there are no surprises.', '좋은 맞교환이에요. 뭐가 옮겨졌는지 그렉한테 알려 줘요. 놀라지 않게요.'),
  ('rt_planning_pr_2', 3, NULL, 'The board is set: thirty points, the holiday report in, admin settings out. Planning is almost over, and you need the team''s commitment before everyone goes back to their desks.', '보드가 정리됐습니다. 30포인트, 연말 보고서는 넣고, 관리자 설정은 뺐습니다. 회의가 거의 끝났고, 다들 자리로 돌아가기 전에 팀의 약속을 받아야 합니다.', 'Anything else before we wrap up?', '마무리하기 전에 더 할 말 있어요?', 'Sum up what the team is committing to, and check that everyone agrees.', '팀이 약속하는 내용을 정리하고, 모두 동의하는지 확인하세요.', '[]', 'Quick recap: thirty points, report in, settings out. Is everyone okay with that?', '짧게 정리할게요. 30포인트, 보고서는 넣고, 설정은 빼요. 다들 괜찮아요?', '["Quick recap: thirty-eight points, report in, nothing out. Everyone okay?","Nope, that''s it. Back to work, everyone, and don''t let me down this time.","Quick recap: thirty points, settings in, report out. Is everyone okay?"]', '["짧게 정리할게요. 38포인트, 보고서는 넣고, 빼는 건 없어요. 다들 괜찮아요?","아뇨, 끝이에요. 다들 일하러 가요. 이번엔 실망시키지 말고요.","짧게 정리할게요. 30포인트, 설정은 넣고, 보고서는 빼요. 다들 괜찮아요?"]', '["Thirty-eight? I thought we swapped something out.","This time? Did we let you down last time?","Wait, isn''t it the other way around?"]', '["38이요? 하나 맞바꾼 줄 알았는데요.","이번엔요? 지난번엔 우리가 실망시켰어요?","잠깐, 반대 아니에요?"]', NULL, 'Works for me. I''ll start on the report this afternoon.', '좋아요. 보고서는 오늘 오후부터 시작할게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_retro_1', 1, NULL, 'Friday afternoon. Maya has drawn three columns on the whiteboard: Went well, To improve, Action items. This sprint''s release went out with zero bugs, thanks to a new release checklist the team tried.', '금요일 오후입니다. 마야가 화이트보드에 세 칸을 그렸습니다. 잘된 것, 개선할 것, 실행 항목. 이번 스프린트 배포는 팀이 새로 써 본 배포 체크리스트 덕분에 버그 없이 나갔습니다.', 'Let''s start on a good note. What went well this sprint?', '좋은 얘기로 시작하죠. 이번 스프린트에 뭐가 잘됐어요?', 'Share a real win from this sprint and what made it work.', '이번 스프린트의 진짜 성과와, 무엇 덕분이었는지 말하세요.', '[]', 'The release went out with zero bugs. I think the new checklist really helped.', '배포가 버그 하나 없이 나갔어요. 새 체크리스트가 정말 도움이 된 것 같아요.', '["The release had a few bugs, but at least we fixed them pretty fast.","Honestly, nothing went well. This sprint was a mess from start to finish.","The release went great, mostly because I double-checked everyone''s work."]', '["배포에 버그가 좀 있었지만, 그래도 꽤 빨리 고쳤어요.","솔직히 잘된 건 없어요. 이번 스프린트는 처음부터 끝까지 엉망이었어요.","배포가 잘됐어요. 주로 제가 모두의 작업을 다시 확인한 덕분이에요."]', '["A few bugs? I counted zero. Give us some credit.","Nothing? We shipped with zero bugs!","Hmm. It was a team effort, though, wasn''t it?"]', '["버그가 좀 있었다고요? 전 하나도 못 셌는데요. 우리 좀 칭찬해요.","하나도요? 버그 없이 배포했잖아요!","흠. 그래도 다 같이 한 거잖아요, 그렇죠?"]', NULL, 'Agreed. The checklist stays. That goes under Went well.', '동의해요. 체크리스트는 계속 써요. 잘된 것 칸에 적을게요.'),
  ('rt_retro_1', 2, NULL, 'On to To improve. This sprint, code reviews often sat for two or three days before anyone looked at them. It slowed everyone down, you included. In retros, the team talks about the process, not about people.', '개선할 것으로 넘어갑니다. 이번 스프린트에는 코드 리뷰가 누가 보기까지 이삼일씩 묵는 일이 잦았습니다. 당신을 포함해 모두가 느려졌습니다. 회고에서 팀은 사람이 아니라 과정을 얘기합니다.', 'Okay. What could we do better?', '좋아요. 뭘 더 잘할 수 있을까요?', 'Bring up the slow reviews without pointing at anyone.', '누구도 지목하지 않고 느린 리뷰 문제를 꺼내세요.', '[]', 'Reviews often waited two or three days. Could we agree on a time limit?', '리뷰가 이삼일씩 기다리는 일이 많았어요. 기한을 정해 볼까요?', '["Some people take forever to review code. I think they know who they are.","Reviews were really fast this sprint. I don''t have anything to improve.","Reviews waited two or three days. Maybe we should skip them for small changes."]', '["어떤 사람들은 리뷰가 한없이 느려요. 본인들은 알 거예요.","이번 스프린트엔 리뷰가 정말 빨랐어요. 개선할 게 없어요.","리뷰가 이삼일씩 기다렸어요. 작은 변경은 리뷰를 건너뛰면 어떨까요."]', '["Let''s keep it about the process, not people.","Fast? Some reviews sat for three days.","Skipping reviews is how bugs sneak in. Let''s speed them up instead."]', '["사람 말고 과정 얘기로 해요.","빨랐다고요? 사흘씩 묵은 리뷰도 있었어요.","리뷰를 건너뛰면 버그가 숨어들어요. 대신 빨리 하는 쪽으로 해요."]', NULL, 'Good one. Slow reviews goes under To improve.', '좋아요. 느린 리뷰를 개선할 것 칸에 적을게요.'),
  ('rt_retro_1', 3, NULL, 'Under Action items, Maya wants every problem turned into a small, concrete step with one person''s name on it. Nobody has offered to own the review problem yet.', '실행 항목 칸에서, 마야는 모든 문제를 작고 구체적인 단계로 바꾸고 한 사람의 이름을 붙이고 싶어 합니다. 리뷰 문제를 맡겠다는 사람은 아직 없습니다.', 'So what''s our action item for reviews? And who owns it?', '그럼 리뷰에 대한 실행 항목은 뭘까요? 그리고 누가 맡죠?', 'Suggest a specific step, and offer to take it on yourself.', '구체적인 단계를 제안하고, 직접 맡겠다고 하세요.', '[]', 'Reviews within one day. I can set up a daily reminder in our team chat.', '리뷰는 하루 안에요. 팀 채팅에 매일 알림을 제가 설정할게요.', '["Let''s all just try to be better about reviews. It''ll work itself out.","Reviews within one day. Maybe Sam could set up the reminder for us?","Reviews within one hour, every time, no matter what else is going on."]', '["다들 리뷰를 좀 더 잘해 보기로 해요. 알아서 해결될 거예요.","리뷰는 하루 안에요. 알림은 샘이 설정해 주면 어떨까요?","리뷰는 무슨 일이 있어도 매번 한 시간 안에요."]', '["Trying to be better is hard to check next time. Something concrete?","Sam helps with IT, not our reviews. Could you own it?","One hour, no matter what? That would wreck everyone''s focus."]', '["더 잘해 보자는 건 다음에 확인하기 어려워요. 구체적인 걸로요?","샘은 IT 담당이지 우리 리뷰 담당이 아니에요. 직접 맡아 줄래요?","무슨 일이 있어도 한 시간이요? 다들 집중이 다 깨질 거예요."]', NULL, 'Perfect. One-day reviews, and the reminder is yours. Thanks, everyone.', '완벽해요. 리뷰는 하루 안에, 알림은 당신 담당이에요. 다들 고마워요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_retro_2', 1, NULL, 'Friday afternoon retro. Maya always opens with shout-outs. This sprint, Sam from IT stayed late on Tuesday to fix the build server, so the team could release on time. Sam has joined the retro today.', '금요일 오후 회고입니다. 마야는 늘 감사 인사로 시작합니다. 이번 스프린트에 IT의 샘이 화요일에 늦게까지 남아 빌드 서버를 고쳐서, 팀이 제때 배포할 수 있었습니다. 오늘은 샘도 회고에 왔습니다.', 'Let''s start with shout-outs. Who wants to thank someone?', '감사 인사부터 해요. 누구한테 고맙다고 할 사람?', 'Thank the right person, and be specific about what they did.', '고마운 사람에게, 그가 한 일을 구체적으로 들어 고맙다고 하세요.', '[]', 'Shout-out to Sam for fixing the build server Tuesday night. We shipped on time thanks to him.', '화요일 밤에 빌드 서버를 고쳐 준 샘에게 고마워요. 덕분에 제때 배포했어요.', '["Shout-out to Sam for the build server. It was down so long I almost gave up.","Shout-out to Tom for fixing the build server Tuesday night. He saved our release.","Shout-out to the whole team. Everyone was great. You all know what you did."]', '["빌드 서버 고쳐 준 샘에게 고마워요. 너무 오래 죽어 있어서 포기할 뻔했어요.","화요일 밤에 빌드 서버를 고쳐 준 톰에게 고마워요. 우리 배포를 살렸어요.","팀 전체에 고마워요. 다들 훌륭했어요. 뭘 했는지 다들 알잖아요."]', '["Let''s keep the thank-you a thank-you, maybe?","Tom? I think Sam fixed that one.","Nice, but who did what? Specific thanks mean more."]', '["감사 인사는 감사 인사로만 할까요?","톰이요? 그건 샘이 고친 것 같은데요.","좋아요, 그런데 누가 뭘 했죠? 구체적인 감사가 더 와닿아요."]', NULL, 'Love it. Sam, you really saved us that night.', '좋아요. 샘, 그날 밤 정말 우릴 살렸어요.'),
  ('rt_retro_2', 2, 'sam', 'Sam has a point to raise. Twice this sprint, someone messaged him about a laptop problem at ten at night instead of filing a help desk ticket. He doesn''t say who, and Maya reminds everyone the retro is blameless.', '샘이 꺼낼 얘기가 있습니다. 이번 스프린트에 두 번, 누군가 헬프데스크 티켓을 내는 대신 밤 10시에 노트북 문제로 그에게 메시지를 보냈습니다. 그는 누군지 말하지 않고, 마야는 회고가 누구도 탓하지 않는 자리라고 다시 말합니다.', 'Can I add one? Late-night messages about laptops. Tickets work better for me.', '하나 보태도 될까요? 밤늦게 오는 노트북 메시지요. 저한텐 티켓이 더 좋아요.', 'Accept his point, and suggest something that would help.', '그의 말을 받아들이고, 도움이 될 만한 것을 제안하세요.', '[]', 'Fair point. Could we put the help desk link on our team page?', '맞는 말이에요. 헬프데스크 링크를 팀 페이지에 올려 둘까요?', '["Who was it? Just tell us, so we can make sure it doesn''t happen again.","Well, tickets take forever. Messaging you directly is just faster for us.","That''s fair. Maybe IT could stay online later, so you can answer them?"]', '["누구였어요? 말해 주면 다시는 안 그러게 할게요.","근데 티켓은 한참 걸려요. 직접 메시지 보내는 게 우리한텐 빨라요.","맞는 말이에요. IT가 더 늦게까지 접속해 있으면 답할 수 있지 않을까요?"]', '["It''s not about who. It''s about the habit.","Tickets are faster than you think. I check them first.","Stay online later? I''m one guy, friend."]', '["누구 문제가 아니에요. 습관 문제예요.","티켓은 생각보다 빨라요. 전 티켓부터 봐요.","더 늦게까지요? 저 혼자예요, 친구."]', NULL, 'That would help a lot. Thanks for hearing me out.', '그거면 정말 도움이 돼요. 들어 줘서 고마워요.'),
  ('rt_retro_2', 3, NULL, 'Last step: every action item needs an owner. The help desk link is the only one without a name, and it''s about a five-minute job.', '마지막 단계입니다. 실행 항목마다 맡을 사람이 있어야 합니다. 헬프데스크 링크만 이름이 없고, 5분이면 되는 일입니다.', 'Who can add the help desk link to the team page?', '헬프데스크 링크를 팀 페이지에 누가 올려 줄래요?', 'Take the small task, and say when it will be done.', '작은 일을 맡고, 언제까지 할지 말하세요.', '[]', 'I''ll do it. It''s a quick job. It''ll be up before I leave today.', '제가 할게요. 금방 하는 일이에요. 오늘 퇴근 전에 올릴게요.', '["I''ll do it, but it''s a big job. Give me until the end of next sprint.","Sam should do it. It''s his help desk, so it''s really his job, not ours.","I''ll do it today, and I''ll redesign the whole team page while I''m at it."]', '["제가 할게요. 근데 큰일이라 다음 스프린트 끝까지 시간을 주세요.","샘이 해야죠. 그의 헬프데스크니까 우리 일이 아니라 그의 일이에요.","오늘 할게요. 하는 김에 팀 페이지 전체도 새로 디자인할게요."]', '["Next sprint? For one link?","He raised it. Let''s help him out.","Let''s keep it small. Just the link."]', '["다음 스프린트요? 링크 하나에요?","샘이 꺼낸 얘기잖아요. 우리가 도와줘요.","작게 가요. 링크만요."]', NULL, 'Thanks. That''s everything. Good sprint, everyone. Enjoy the weekend.', '고마워요. 이걸로 끝이에요. 다들 수고했어요. 주말 잘 보내요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_retro_3', 1, NULL, 'A hard sprint. A late change from the client meant redoing the store map twice, and two stories didn''t make it. Maya starts the retro with a quick mood check: one word each.', '힘든 스프린트였습니다. 고객의 막판 변경 때문에 매장 지도를 두 번 다시 만들었고, 스토리 두 개를 끝내지 못했습니다. 마야가 짧은 기분 점검으로 회고를 시작합니다. 한 사람당 한 단어씩요.', 'Before we dig in, one word for how this sprint felt.', '본격적으로 하기 전에, 이번 스프린트가 어땠는지 한 단어로요.', 'Give an honest one-word feeling, and add one short reason.', '솔직한 기분을 한 단어로 말하고, 짧은 이유를 하나 붙이세요.', '[]', 'Tired. Redoing the store map twice took a lot out of us.', '지쳤어요. 매장 지도를 두 번 다시 만드느라 힘이 많이 빠졌어요.', '["Amazing. Everything went exactly the way we planned it on day one.","Tired. Mostly because some people kept changing their minds all sprint.","Tired. Redoing the store map three times took a lot out of us."]', '["최고였어요. 첫날 계획한 그대로 다 됐어요.","지쳤어요. 주로 어떤 사람들이 스프린트 내내 마음을 바꿔서요.","지쳤어요. 매장 지도를 세 번 다시 만드느라 힘이 많이 빠졌어요."]', '["Amazing? We missed two stories, though.","Let''s not say some people. What happened, not who?","Three? I counted two. But I get it."]', '["최고였다고요? 스토리 두 개를 놓쳤는데요.","어떤 사람들이라는 말은 빼요. 누가 아니라 무슨 일이 있었죠?","세 번이요? 전 두 번으로 셌어요. 그래도 무슨 말인지 알아요."]', NULL, 'Thanks for being honest. Tired is fair. Let''s see what we can learn.', '솔직하게 말해 줘서 고마워요. 지칠 만해요. 뭘 배울 수 있는지 봐요.'),
  ('rt_retro_3', 2, NULL, 'The map change arrived in the middle of the sprint, and the team said yes without checking what else would slip. Nobody did anything wrong on purpose.', '지도 변경은 스프린트 한가운데 들어왔고, 팀은 다른 무엇이 밀릴지 확인하지 않고 받아들였습니다. 일부러 잘못한 사람은 아무도 없습니다.', 'So what happened with the map, and what would we do differently?', '그래서 지도는 어떻게 된 거고, 다음엔 뭘 다르게 할까요?', 'Describe the cause without blaming anyone, and suggest a better way next time.', '누구도 탓하지 않고 원인을 설명하고, 다음엔 어떻게 하면 좋을지 제안하세요.', '[]', 'We took the change without trading anything out. Next time, let''s swap something first.', '아무것도 빼지 않고 변경을 받았어요. 다음엔 먼저 하나를 맞바꿔요.', '["The client keeps changing their mind. Maybe we should stop working with them.","Whoever said yes to that change made a mistake. They should have asked first.","We took the change without trading anything out. Next time, let''s just work faster."]', '["고객이 계속 마음을 바꿔요. 그쪽이랑 일을 그만해야 할지도 몰라요.","그 변경을 받아들인 사람이 실수했어요. 먼저 물어봤어야죠.","아무것도 빼지 않고 변경을 받았어요. 다음엔 그냥 더 빨리 일해요."]', '["They''re our biggest client. Let''s look at what we control.","Let''s not hunt for who. What about the process?","Faster isn''t really a plan, is it?"]', '["우리 최대 고객이에요. 우리가 바꿀 수 있는 걸 봐요.","누군지 찾지 말아요. 과정은 어땠죠?","더 빨리는 계획이라고 하기 어렵죠?"]', NULL, 'Exactly. A change mid-sprint needs a trade. I''ll write that down.', '바로 그거예요. 스프린트 중간 변경에는 맞교환이 필요해요. 적어 둘게요.'),
  ('rt_retro_3', 3, 'tom', 'Tom from the front desk pokes his head in. He looks after the meeting room equipment. Today the projector cut out twice during the retro.', '안내 데스크의 톰이 고개를 들이밉니다. 그는 회의실 장비를 관리합니다. 오늘 회고 중에 프로젝터가 두 번 꺼졌습니다.', 'Sorry to barge in. How was the room for you folks today?', '불쑥 들어와서 미안해요. 오늘 회의실 어땠어요?', 'Mention the equipment problem politely, so he can fix it.', '그가 고칠 수 있게 장비 문제를 정중하게 말하세요.', '[]', 'Mostly good. The projector cut out twice, though. Could you look at it?', '대체로 좋았어요. 그런데 프로젝터가 두 번 꺼졌어요. 한번 봐 주실래요?', '["Terrible. That projector is junk. Why do we even keep it around?","Great, no problems at all! Thanks for setting up the room for us.","Mostly good. The projector cut out twice. Sam should fix it tonight."]', '["최악이었어요. 저 프로젝터는 고물이에요. 왜 아직도 두는 거예요?","좋았어요, 아무 문제 없었어요! 회의실 준비해 줘서 고마워요.","대체로 좋았어요. 프로젝터가 두 번 꺼졌어요. 샘이 오늘 밤에 고쳐야 해요."]', '["Whoa. Okay, I''ll look at it. No need to be harsh.","Really? I heard the projector acted up.","Sam''s swamped. The room is my department."]', '["와. 알겠어요, 볼게요. 그렇게 심하게 말할 건 없잖아요.","정말요? 프로젝터가 말썽이었다고 들었는데요.","샘은 바빠요. 회의실은 제 담당이에요."]', NULL, 'Thanks for telling me. I''ll swap the cable before Monday.', '말해 줘서 고마워요. 월요일 전에 케이블을 바꿔 둘게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_allhands_1', 1, NULL, 'The first Thursday of the month: all-hands in the meeting room, with remote folks on the screen. Maya gives the engineering update: the store dashboard is live in the five pilot stores, and managers check it about twice a day. Then she opens the floor.', '매달 첫 목요일, 회의실에서 전사 회의가 열리고 원격 근무자들은 화면으로 들어와 있습니다. 마야가 엔지니어링 소식을 전합니다. 매장 대시보드가 시범 매장 다섯 곳에서 돌아가고 있고, 매니저들은 하루에 두 번쯤 확인합니다. 그리고 질문을 받습니다.', 'That''s the update. Questions? Don''t be shy.', '소식은 여기까지예요. 질문 있어요? 부끄러워하지 말고요.', 'Ask something useful about what comes next for the dashboard.', '대시보드의 다음 단계에 대해 쓸모 있는 질문을 하세요.', '[]', 'Thanks, Maya. When do you expect it to reach the rest of the stores?', '고마워요, 마야. 나머지 매장에는 언제쯤 들어갈 것 같아요?', '["Thanks, Maya. Why do the managers only check it once a week?","Thanks. Is the parking garage going to be open this weekend?","Thanks, Maya. Could you show each store''s exact sales numbers right now?"]', '["고마워요, 마야. 매니저들은 왜 일주일에 한 번만 확인해요?","고마워요. 이번 주말에 주차장 열어요?","고마워요, 마야. 매장별 정확한 매출 숫자를 지금 보여 줄 수 있어요?"]', '["Once a week? It''s about twice a day, actually.","Ha. Better ask Tom that one in a minute.","Those are Summit''s numbers. I can''t put them up here."]', '["일주일에 한 번이요? 사실 하루에 두 번쯤이에요.","하하. 그건 이따가 톰한테 물어보세요.","그건 서밋의 숫자예요. 여기 띄울 순 없어요."]', NULL, 'Good question. We roll out store by store, and the mobile app starts in January.', '좋은 질문이에요. 매장별로 차례로 넓히고, 모바일 앱은 1월에 시작해요.'),
  ('rt_allhands_1', 2, 'linda', 'Linda from HR takes the mic. She reminds everyone to keep their emergency contact and home address up to date in the HR portal. You haven''t looked at yours since your first week.', '인사팀 린다가 마이크를 잡습니다. 인사 포털에 비상 연락처와 집 주소를 최신으로 유지해 달라고 다시 당부합니다. 당신은 입사 첫 주 이후로 한 번도 들여다보지 않았습니다.', 'Quick show of hands: who has checked their emergency contact lately?', '손 한번 들어 볼까요? 최근에 비상 연락처 확인하신 분?', 'Admit honestly that you haven''t, and ask where in the portal you would do it.', '확인하지 않았다고 솔직하게 말하고, 포털 어디에서 하면 되는지 물어보세요.', '[]', 'Not since my first week, honestly. Where in the portal do I update it?', '솔직히 첫 주 이후로는 안 했어요. 포털 어디에서 고치면 돼요?', '["Yes, I updated mine this morning. Everything is already in there.","Not yet. Could I just email you the details, and you put them in?","Not yet. Does HR really need that? It feels a bit personal to share."]', '["네, 오늘 아침에 고쳤어요. 이미 다 들어가 있어요.","아직이요. 제가 메일로 보내면 대신 넣어 주실 수 있어요?","아직이요. 인사팀에 꼭 필요해요? 알려 주기엔 좀 사적인 것 같아요."]', '["This morning? Then you can skip this part. But I don''t think so.","Please don''t email personal details. The portal is safer, and it takes a minute.","It''s only for emergencies. I hope we never need it, but we might."]', '["오늘 아침이요? 그럼 이건 넘어가도 되겠네요. 그런데 아닌 것 같은데요.","개인 정보는 메일로 보내지 말아 주세요. 포털이 더 안전하고, 1분이면 돼요.","비상시에만 써요. 쓸 일이 없길 바라지만, 혹시 모르잖아요."]', NULL, 'Thanks for being honest. It''s under My Profile. Please do it by the end of next week.', '솔직하게 말해 줘서 고마워요. 내 프로필 메뉴에 있어요. 다음 주 말까지 해 주세요.'),
  ('rt_allhands_1', 3, 'tom', 'Tom has the last slide: office news. The kitchen fridge gets cleaned out every Friday at 5 p.m. You keep your lunch in that fridge.', '톰이 마지막 슬라이드를 맡았습니다. 사무실 소식입니다. 탕비실 냉장고는 매주 금요일 오후 5시에 비웁니다. 당신은 그 냉장고에 점심을 넣어 둡니다.', 'And please, folks, label your food. Anything left at five on Friday goes out.', '그리고 여러분, 음식에 이름 좀 붙여 주세요. 금요일 5시에 남은 건 버려요.', 'Repeat the rule back to make sure you understood it.', '제대로 알아들었는지 규칙을 다시 말해 확인하세요.', '[]', 'Just to check: anything still in the fridge at five on Friday gets thrown out?', '확인차 여쭤요. 금요일 5시에 냉장고에 남은 건 버려지는 거죠?', '["Just to check: the fridge gets cleaned out every Monday morning, right?","Do we really have to label everything? That sounds like a lot of work.","Just to check: we can leave food over the weekend if it''s labeled, right?"]', '["확인차 여쭤요. 냉장고는 매주 월요일 아침에 비우는 거죠?","꼭 다 이름을 붙여야 해요? 일이 많아 보이는데요.","확인차 여쭤요. 이름만 붙이면 주말 동안 둬도 되는 거죠?"]', '["Fridays at five. Mondays would be a crime scene.","A marker and two seconds. Trust me, it''s worth it.","Nope. Labeled or not, Friday at five it goes."]', '["금요일 5시요. 월요일이면 끔찍한 꼴을 보게 될 거예요.","마커 하나에 2초면 돼요. 정말 그럴 만한 가치가 있어요.","아뇨. 이름이 있든 없든 금요일 5시면 버려요."]', NULL, 'You got it. Label it, or lose it. Thanks, everybody.', '맞아요. 이름 붙이거나, 잃거나. 다들 고마워요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('rt_allhands_2', 1, NULL, 'Monthly all-hands. Maya starts with good news: the store dashboard just went live in another group of Summit Retail stores, and their VP sent a thank-you note. The room claps. Maya turns to you.', '매달 열리는 전사 회의입니다. 마야가 좋은 소식으로 시작합니다. 매장 대시보드가 서밋 리테일의 다른 매장들에도 막 들어갔고, 그쪽 부사장이 감사 편지를 보냈습니다. 다들 박수를 칩니다. 마야가 당신을 돌아봅니다.', 'Want to say a few words about the launch?', '출시에 대해 몇 마디 해 줄래요?', 'Say something short that gives the credit to the whole team.', '팀 전체에 공을 돌리는 짧은 말을 하세요.', '[]', 'Sure. This was a team effort. Thanks to everyone who built, tested and shipped it.', '네. 모두가 함께한 일이에요. 만들고, 테스트하고, 내놓은 모든 분께 고마워요.', '["Sure. Honestly, I did most of the hard parts, but the team helped a bit too.","Sure. It went fine, I guess. Let''s see if it actually holds up next week.","Sure. Huge thanks to Greg and his team. They built most of it for us."]', '["네. 솔직히 어려운 부분은 제가 거의 했지만, 팀도 조금 도왔어요.","네. 그럭저럭 된 것 같아요. 다음 주에도 버티는지 봐야죠.","네. 그렉과 그 팀에 정말 고마워요. 거의 다 그쪽이 만들어 줬어요."]', '["Uh, okay. I think a lot of people put work in.","That''s a little gloomy for a celebration.","Greg''s team? We built it. They''re the client."]', '["어, 그래요. 많은 사람이 애쓴 것 같은데요.","축하 자리치고 좀 우울하네요.","그렉 팀이요? 우리가 만들었어요. 그쪽은 고객이고요."]', NULL, 'Well said. Let''s give the team another round of applause.', '좋은 말이에요. 팀에 한 번 더 박수 쳐 줘요.'),
  ('rt_allhands_2', 2, 'sam', 'Sam from IT has a slide: every laptop needs a security update by the end of the month. It takes about twenty minutes and restarts the computer. You have a client demo coming up.', 'IT의 샘이 슬라이드를 띄웁니다. 모든 노트북은 이달 말까지 보안 업데이트를 해야 합니다. 20분쯤 걸리고 컴퓨터가 다시 시작됩니다. 당신은 곧 고객 시연이 있습니다.', 'Questions about the laptop update? I know nobody loves a restart.', '노트북 업데이트 질문 있어요? 다시 시작되는 거 다들 싫어하는 거 알아요.', 'Ask something that helps you plan around your demo.', '시연 일정에 맞춰 계획하는 데 도움이 될 질문을 하세요.', '[]', 'Can I run it after work, so it won''t restart in the middle of my demo?', '퇴근 후에 돌려도 돼요? 시연 도중에 다시 시작되지 않게요.', '["Do I have to? My laptop has worked fine without updates for years.","Can I skip it until after the holidays? I''m pretty busy right now.","Can I run it right before my demo? It only takes about twenty seconds."]', '["꼭 해야 해요? 제 노트북은 몇 년째 업데이트 없이도 잘 돌아요.","연휴 끝날 때까지 미뤄도 돼요? 지금 좀 바빠서요.","시연 바로 전에 돌려도 돼요? 20초면 되잖아요."]', '["Years without updates? Please come see me.","End of the month, sorry. It''s a security thing.","Twenty minutes, not seconds. Maybe not right before a demo."]', '["몇 년째 업데이트를 안 했다고요? 꼭 저한테 와 주세요.","이달 말까지예요, 미안해요. 보안 문제라서요.","20초가 아니라 20분이에요. 시연 바로 전엔 안 하는 게 좋겠어요."]', NULL, 'Totally. Start it before you leave, and it''ll be done by morning.', '물론이죠. 퇴근 전에 시작해 두면 아침엔 끝나 있을 거예요.'),
  ('rt_allhands_2', 3, 'linda', 'Linda closes with the holiday party: a Friday evening at the Harbor Grill on Lake Avenue, starting at six. Partners and spouses are welcome, and RSVPs go through the online form.', '린다가 연말 파티 소식으로 마무리합니다. 금요일 저녁 6시, 레이크 애비뉴의 하버 그릴에서 열립니다. 애인과 배우자도 올 수 있고, 참석 여부는 온라인 양식으로 알립니다.', 'Any questions about the party?', '파티에 대해 질문 있어요?', 'You''re not sure what to wear. Ask about it.', '무엇을 입고 가야 할지 모르겠습니다. 물어보세요.', '[]', 'Sounds fun. Is there a dress code, or is it pretty casual?', '재밌겠네요. 복장 규정이 있어요, 아니면 편하게 가도 돼요?', '["Sounds fun. Can we bring a partner, or is it just employees this year?","Do I have to go? I''d honestly rather just have the evening off.","Sounds fun. Is it at lunchtime, so we can go back to work after?"]', '["재밌겠네요. 애인을 데려가도 돼요, 아니면 올해는 직원만이에요?","꼭 가야 해요? 솔직히 그냥 저녁에 쉬고 싶어요.","재밌겠네요. 점심때예요? 끝나고 다시 일하러 가게요."]', '["Partners are welcome! I mentioned it a minute ago.","It''s not required. But we''d love to see you there.","It''s in the evening, at six. No work after, I promise."]', '["애인도 환영이에요! 방금 말씀드렸어요.","의무는 아니에요. 그래도 와 주시면 정말 좋겠어요.","저녁 6시예요. 끝나고 일은 없어요, 약속해요."]', NULL, 'Business casual. Leave the hoodies at home, please.', '비즈니스 캐주얼이요. 후드티는 집에 두고 오세요.');
